NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'Genesis'

CHAPTERS = {
    1: {
        1: 'Zu Anbeginn hat Gott erschaffen den Himmel und die Erde.',
        2: 'Die Erde aber war wüst und wirr, und auf der Urflut lag Finsternis. Gottes Geist aber schwebte über den Gewässern.',
        3: 'Da sprach Gott: "Licht werde!" Und Licht ward.',
        4: 'Und Gott sah: Das Licht war gut. So schied Gott zwischen Licht und Finsternis.',
        5: 'Und Gott bestimmte für das Licht den Tag. Und für die Finsternis bestimmte er die Nacht. So ward Abend und ward Morgen. Ein Tag.',
        6: 'Und Gott sprach: "Mitten in den Wassern sei eine Feste! Sie scheide zwischen Wasser und Wasser!"',
        7: 'So machte Gott die Feste und schied zwischen dem Wasser unter der Feste und dem Wasser über der Feste. Und so ward es.',
        8: 'Der Feste sprach Gott den Himmel zu. So ward Abend und ward Morgen. Ein zweiter Tag.',
        9: 'Und Gott sprach: "An einem Orte sammle sich das Wasser unterm Himmel, und das Trockene erscheine!" Und so ward es.',
        10: 'Für das Trockensein bestimmte Gott die Erde, und für die Sammlung der Wasser bestimmte er die Meere. Und Gott sah: Gut war es.',
        11: 'Und Gott sprach: "Sprießen lasse die Erde Grünes! Samentragendes Kraut und Fruchtbäume, nach ihrer Art Früchte tragend, darin ihr Same für die Erde!" Und so ward es.',
        12: 'Die Erde brachte Grünes, Kraut mit Samen je nach seiner Art und Bäume mit Früchten, darin ihr Same je nach ihrer Art. Und Gott sah: Gut war es.',
        13: 'So ward Abend und ward Morgen. Ein dritter Tag.',
        14: 'Und Gott sprach: "Leuchten seien an der Himmelsfeste, zwischen Tag und Nacht zu scheiden! Dann dienen sie zu Zeichen und Gezeiten, zu Tagen und Jahren',
        15: 'und zu Leuchten an der Himmelsfeste, die Erde zu bescheinen." Und so ward es.',
        16: 'So machte Gott die zwei großen Leuchten, die größere Leuchte zum Walten über den Tag und die kleinere Leuchte zum Walten über die Nacht, und die Sterne.',
        17: 'Und Gott ließ sie an der Himmelsfeste auf die Erde scheinen,',
        18: 'über den Tag und die Nacht walten und zwischen dem Licht und der Finsternis scheiden. Und Gott sah: Gut war es.',
        19: 'So ward Abend und ward Morgen. Ein vierter Tag.',
        20: 'Und Gott sprach: "Das Wasser wimmle von lebendem Gewimmel, und auf Erden an der Himmelsfeste fliege Geflügel."',
        21: 'So schuf Gott die großen Meerestiere und alle anderen lebenden Wimmelwesen, wovon die Wasser wimmeln, nach ihren Arten und der beschwingten Vögel jegliche Art. Und Gott sah: Gut war es.',
        22: 'Da segnete Gott sie und sprach: "Seid fruchtbar! Mehret euch! Füllet der Meere Gewässer! Auf Erden mehre sich das Geflügel!"',
        23: 'So ward Abend und ward Morgen. Ein fünfter Tag.',
        24: 'Und Gott sprach:"Die Erde zeuge Lebewesen je nach ihrer Art! Vieh, Gewürm und das Wild der Erde!" Und so ward es.',
        25: 'So machte Gott das Wild der Erde nach seiner Art, das Vieh nach seiner Art und alles Gewürm des Bodens nach seiner Art. Und Gott sah: Gut war es.',
        26: 'Und Gott sprach. "Lasset uns Menschen machen als unser Bild nach unserem Gleichnis! Herrschen sollen sie über des Meeres Fische, über des Himmels Vögel, über das Vieh auf der ganzen Erde überall und über alle Wimmelwesen, die auf Erden wimmeln!"',
        27: 'Und Gott schuf den Menschen als sein Bild. Als Gottes Bild schuf er ihn. Er schuf sie als Mann und als Weib.',
        28: 'Und Gott segnete sie. Und Gott sprach zu ihnen: "Seid fruchtbar! Mehret euch! Füllet die Erde! Macht sie euch untertan! Herrschet über des Meeres Fische, über des Himmels Vögel und über alle Lebewesen, die auf Erden wimmeln!"',
        29: 'Und Gott sprach: "Euch überlasse ich alles samentragende Kraut auf der ganzen Erde und alle Bäume mit samentragender Baumfrucht, daß sie euch zur Nahrung diene.',
        30: 'Und alles andere grüne Kraut diene zur Nahrung allem Wilde, allen Vögeln des Himmels und allem Gewürm auf Erden, in dem Lebensgeist ist." Und so ward es.',
        31: 'Und Gott sah alles, was er gemacht hatte. Und sehr gut war es. So ward Abend und ward Morgen. Ein sechster Tag.',
    },
    2: {
        1: 'So wurden vollendet der Himmel und die Erde und all ihre Vielfalt.',
        2: 'Da feierte Gott am siebten Tage von seiner Arbeit, die er getan. Und er ruhte am siebten Tage ganz von seiner Arbeit, die er getan hatte.',
        3: 'So segnete Gott den siebten Tag und weihte ihn. Denn an ihm hatte er völlig von seiner Arbeit geruht, die Gott zu tun geplant hatte.',
        4: 'Dies ist die Entstehung des Himmels und der Erde, als sie erschaffen worden sind. Damals, als der Herr Gott Erde und Himmel gemacht hatte,',
        5: 'war kein Feldgesträuch im Lande, und kein Feldgewächs sproßte; denn der Herr Gott hatte dem Lande noch keinen Regen gegeben. Auch waren keine Menschen da, die den Erdboden bebaut hätten.',
        6: 'Und eine Wasserflut stieg von der Erde auf und tränkte des Erdbodens ganze Fläche.',
        7: 'Da bildete der Herr Gott den Menschen aus Staub vom Boden und blies ihm Lebensodem in die Nase. So ward der Mensch zu einem Lebewesen.',
        8: 'Nun hatte der Herr Gott im Osten einen Garten in Eden gepflanzt; dort ließ er nun den Menschen sein, den er gebildet hatte.',
        9: 'Allerlei Bäume, lieblich zur Schau und köstlich als Speise, hatte der Herr Gott aus dem Erdboden sprießen lassen, in des Gartens Mitte aber den Baum des Lebens und den Baum der Erkenntnis von Gut und Bös.',
        10: 'Und ein Fluß kam von Eden her, den Garten zu bewässern; er aber war von da ab geteilt und zu vier Häuptern geworden.',
        11: 'Pischon heißt der erste, der das ganze Sandland umfließt, wo das Gold ist.',
        12: 'Fein ist das Gold dieses Landes; dort gibt es auch Harztränen (Bdellium) und Onyxstein.',
        13: 'Und der zweite Strom heißt Gichon, der das ganze Land Kusch umfließt.',
        14: 'Der dritte Strom heißt Tigris, der östlich von Assur vorüberfließt. Der vierte Strom ist der Euphrat.',
        15: 'Der Herr Gott nahm also den Menschen und setzte ihn in Edens Garten, daß er ihn bebaue und pflege.',
        16: 'Und der Herr Gott gebot dem Menschen und sprach: "Von allen Bäumen im Garten darfst du nach Belieben essen.',
        17: 'Nur von dem Baume, der Gutes und Böses keimen lehrt, darfst du nicht essen. Denn sobald du von ihm issest, bist du des Todes."',
        18: 'Und der Herr Gott sprach: "Nicht gut ist es, daß der Mensch allein sei; ich will ihm eine Gehilfin schaffen, die ihm gleichgeartet ist."',
        19: 'Nun formte der Herr Gott aus dem Erdboden alle Tiere des Feldes und alle Vögel des Himmels. Diese brachte er zum Menschen, um zu sehen, wozu er sie bestimmte, und genau das wozu er ein Lebewesen bestimmte, sollte seine Bestimmung sein.',
        20: 'Und so gab der Mensch allem Vieh und des Himmels Vögeln und allem Wilde eine Bestimmung; aber für einen Menschen hatte keines als Beistand gepaßt, ihm gleichgeartet.',
        21: 'Da ließ der Herr Gott einen Tiefschlaf auf den Menschen sinken, und als dieser eingeschlafen, nahm er eine seiner Rippen und füllte ihre Lücke mit Fleisch.',
        22: 'Dann baute der Herr Gott die Rippe, die er vom Menschen genommen, zu einem Weibe aus und brachte sie zum Menschen.',
        23: 'Da sprach der Mensch: "Diesmal ist es Bein von meinem Bein und Fleisch von meinem Fleisch. Deshalb heißt sie Weib, weil sie vom Manne genommen ist."',
        24: 'Darum läßt ein Mann Vater und Mutter und hängt sich an sein Weib, und sie werden Ein Leib.',
        25: 'Die beiden aber, der Mensch und sein Weib, waren nackt; aber sie schämten sich nicht voreinander.',
    },
    3: {
        1: 'Die Schlange aber ist schlauer gewesen, als des Feldes Tiere alle, die der Herr Gott gemacht hat. Und so sprach sie zu dem Weibe: "Daß doch Gott gesprochen haben soll: Ihr dürft von keinem Baum des Gartens essen!"',
        2: 'Da sprach das Weib zur Schlange: "Wir dürfen von der Frucht der Bäume im Garten essen.',
        3: 'Nur von der Frucht des Baumes mitten im Garten sprach Gott: \'Davon dürft ihr nicht essen, ja nicht einmal daran rühren, sonst müßt ihr sterben.\'"',
        4: 'Die Schlange sprach zum Weibe: "Ihr werdet gewiß nicht sterben.',
        5: 'Nein! Gott weiß: Sobald ihr davon esset, gehen euch die Augen auf, und ihr seid wie Gott, erkennend Gutes und Böses."',
        6: 'Da sah das Weib: Der Baum war köstlich zum Speisen und Wollust den Augen, und berückend war der Baum, um zur Erkenntnis zu gelangen. So nahm sie von seiner Frucht und aß. Dann gab sie ihrem Manne bei ihr. Auch er aß.',
        7: 'Da gingen beiden die Augen auf, und sie erkannten, daß sie nackt waren. Und sie flochten Feigenlaub und machten sich Schürzen.',
        8: 'Da hörten sie das Geräusch des Herrn Gottes, der sich im Garten beim Tageswinde erging. Und der Mensch verbarg sich mit seinem Weibe vor dem Herrn Gott unter den Bäumen des Gartens.',
        9: 'Der Herr Gott aber rief den Menschen und fragte ihn: "Wo bist du?"',
        10: 'Er sprach: "Ich habe dein Geräusch im Garten gehört; da erschrak ich, weil ich nackt bin, und so verbarg ich mich."',
        11: 'Er sprach: "Wer hat dir verraten, daß du nackt bist? Hast du von dem Baume gegessen, von dem zu essen ich dir verboten habe?"',
        12: 'Da sprach der Mensch: "Das Weib, das du mir beigesellt, hat mir vom Baume gegeben; da aß ich."',
        13: 'Da sprach der Herr Gott zu dem Weibe: "Was hast du getan?" Und das Weib sprach: "Die, Schlange hat mich verführt; da aß ich."',
        14: 'Da sprach der Herr Gott zu der Schlange: "Weil solches du getan, bist du verflucht, mehr als alles Vieh und alles Wild. Auf deinem Bauche sollst du kriechen und Staub dein Lebtag fressen.',
        15: 'Und Feindschaft will ich setzen zwischen dich und das Weib und zwischen deinen, Stamm und ihren Stamm; zermalmen wird er dir den Kopf, willst du ihn in die Ferse stechen."',
        16: 'Zum Weibe aber sprach er: "Vermehren will ich deine Mühsal bei deiner Schwangerschaft. In Mühen sollst du Kinder gebären, und doch geht dein Verlangen hin nach deinem Manne, obschon er waltet über dich."',
        17: 'Und zu Adam sprach er: "Weil du auf deines Weibes Stimme hast gehört und von dem Baum gegessen, von dem ich dir geboten: \'Du darfst davon nicht essen\', so ruht der Fluch um deinetwillen auf dem Acker. In Mühsal sollst du dich dein Leben lang von ihm ernähren.',
        18: 'Dir soll er Dorn und Distel tragen, und doch mußt du das Kraut des Feldes essen.',
        19: 'Im Schweiße deines Angesichts wirst du dein Brot verzehren, bis du zur Erde wiederkehrst, wie du von ihr genommen bist. Denn Staub bist du und kehrst zum Staube wieder."',
        20: 'Da gab der Mensch seinem Weibe den Namen "Eva"; weil sie aller Lebenden Mutter werden sollte.',
        21: 'Und der Herr Gott machte Adam und seinem Weib Fellröcke und hüllte sie darein.',
        22: 'Dann sprach der Herr Gott: "Ja, der Mensch ist jetzt wie unsereiner im Erkennen von Gutem und Bösem. Daß er nicht seine Hand ausstrecke und gar vom Lebensbaume esse und ewig lebe!"',
        23: 'So trieb ihn der Herr Gott aus Edens Garten, damit er den Erdboden bebaue, aus dem er genommen war.',
        24: 'So verstieß er den Menschen und lagerte östlich von Edens Garten Cherube und die zuckende Schwertflamme, um den Weg zum Lebensbaum zu bewachen.',
    },
    4: {
        1: 'Der Mensch aber hatte sein Weib Eva erkannt. Da empfing sie und gebar Kain. Da sprach sie: "Ich habe mit des Herrn Beistand einem Manne das Leben gegeben."',
        2: 'Und zum zweitenmal gebar sie seinen Bruder Abel. Und Abel ward ein Schafhirte; Kain aber war Ackersmann geworden.',
        3: 'Nach einiger Zeit geschah es, daß Kain von den Ackerfrüchten dem Herrn ein Opfer brachte.',
        4: 'Auch Abel brachte ein Opfer von den Erstlingswürfen seiner Schafe dar, und zwar von den wohlgenährtesten. Und der Herr achtete auf Abel und sein Opfer.',
        5: 'Aber auf Kain und sein Opfer achtete er nicht. Da ward Kain sehr ergrimmt, und sein Antlitz sank ein.',
        6: 'Da sprach der Herr zu Kain: "Warum bist du ergrimmt? Weswegen sinkt dein Antlitz ein?',
        7: 'Nicht wahr? Bist frohen Sinnes du, dann kannst du es erheben. Wenn aber nicht, dann ruhst du an der Sünde Pforte; da lauert sie auf dich, du aber solltest sie bezwingen!"',
        8: 'Kain aber sprach mit seinem Bruder Abel, und da sie auf dem Felde waren, vergriff sich Kain an seinem Bruder Abel und schlug ihn tot.',
        9: 'Da sprach der Herr zu Kain: "Wo ist dein Bruder Abel?" Er sprach:"Ich weiß es nicht. Bin ich denn meines Bruders Hüter?"',
        10: 'Da sprach er: "Was hast du getan? Deines Bruders Blut schreit von der Erde auf zu mir.',
        11: 'Nun sei verflucht! Fern von dem Boden, der den Mund geöffnet, um deines Bruders Blut aus deiner Hand zu trinken!',
        12: 'Bebauest du den Boden, so gebe er dir fortan keine Ernte! Durchziehe irr und wirr die Erde!"',
        13: 'Da sprach Kain zum Herrn: "Allzugroß für das Vergeben ist meine Schuld.',
        14: 'So vertreibst du mich heute vom Ackerboden. Und vor deinem Angesichte muß ich mich verbergen. Irr und wirr muß ich die Erde durchwandern. Und wer mich trifft, kann mich erschlagen."',
        15: 'Da sprach der Herr zu ihm: "Nein! Wer den Kain erschlägt, verfalle der Rache siebenfachmal." Und der Herr machte Kain ein Zeichen, auf daß ihn keiner, der ihn träfe, erschlüge.',
        16: 'So zog Kain vom Herrn hinweg und siedelte im Lande Nod, östlich von Eden.',
        17: 'Und Kain erkannte sein Weib, und sie empfing und gebar Henoch. Dann baute er eine Stadt und hieß die Stadt nach seines Sohnes Namen Henoch.',
        18: 'Dem Henoch ward Irad geboren, und Irad zeugte Mechujael und Mechujael Metusael und Metusael Lamech.',
        19: 'Und Lamech nahm sich zwei Weiber: die eine hieß Ada, die andere Silla.',
        20: 'Ada gebar den Jabal; dieser ward der Stammvater der Zeltbewohner und Viehzüchter.',
        21: 'Sein Bruder hieß Jubal; dieser ward der Stammvater aller Zither- und Flötenspieler.',
        22: 'Auch Silla gebar und zwar den Tubalkain, der allerlei ehernes und eisernes Werk schmiedete. Und Tubalkains Schwester war Naama.',
        23: 'Lamech sprach zu seinen Weibern: "Ada und Silla, höret meine Rede! Lamechs Weiber, vernehmet meinen Spruch! Für meine Wunde kann ich Männer jetzt erschlagen, für meine Beulen ihre Söhne.',
        24: 'Wird Kain schon siebenfach gerächt, dann Lamech siebenundsiebzigfach."',
        25: 'Adam aber erkannte wiederum sein Weib, und sie gebar einen Sohn. Den nannte sie Set. "Denn", sprach sie, "Gott hat mir an Abels Stelle andere Nachkommen geschenkt, weil jenen Kain erschlagen hatte."',
        26: 'Aber auch dem Set ward ein Sohn geboren, und er hieß ihn Enos. Damals begann man, des Herrn Namen anzurufen.',
    },
    5: {
        1: 'Das ist die Urkunde der Geschlechterfolge Adams: Damals, als Gott den Adam schuf, machte er ihn in Gottes Ähnlichkeit.',
        2: 'Männlich und weiblich schuf er sie. Dann segnete er sie und hieß sie "Mensch", damals, als sie geschaffen worden waren.',
        3: 'Und Adam war 130 Jahre alt; da zeugte er in seiner Ähnlichkeit nach seinem Bild einen Sohn und hieß ihn Set.',
        4: 'Der Tage Adams waren es nach Sets Zeugung 800 Jahre und er zeugte noch Söhne und Töchter.',
        5: 'Und aller Tage Adams waren 930 Jahre. Da starb er.',
        6: 'Set war 105 Jahre alt; da zeugte er Enos.',
        7: 'Und Set lebte nach des Enos Zeugung 807 Jahre und zeugte noch Söhne und Töchter.',
        8: 'Und aller Tage Sets waren 912 Jahre; da starb er.',
        9: 'Enos war 90 Jahre alt; da zeugte er Kenan.',
        10: 'Und Enos lebte nach Kenans Zeugung 815 Jahre und zeugte noch Söhne und Töchter.',
        11: 'Und aller Tage des Enos waren 905 Jahre; da starb er.',
        12: 'Und Kenan war 70 Jahre alt; da zeugte er Mahalalel.',
        13: 'Und Kenan lebte nach Mahalalels Zeugung 840 Jahre und zeugte noch Söhne und Töchter.',
        14: 'Und aller Tage Kenans waren 910 Jahre; da starb er.',
        15: 'Und Mahalalel war 65 Jahre alt; da zeugte er Jered.',
        16: 'Und Mahalalel lebte nach Jereds Zeugung 830 Jahre und zeugte noch Söhne und Töchter.',
        17: 'Und aller Tage Mahalalels waren 895 Jahre; da starb er.',
        18: 'Und Jered war 162 Jahre alt; da zeugte er Henoch.',
        19: 'Und Jered lebte nach Henochs Zeugung 800 Jahre und zeugte noch Söhne und Töchter.',
        20: 'Und aller Tage Jereds waren 962 Jahre; da starb er.',
        21: 'Und Henoch war 65 Jahre alt; da zeugte er Metuselach.',
        22: 'Nach Metuselachs Zeugung wandelte Henoch mit Gott 300 Jahre und zeugte noch Söhne und Töchter.',
        23: 'Und aller Tage Henochs waren 365 Jahre.',
        24: 'Und Henoch wandelte mit Gott, und plötzlich war er nicht mehr da, weil ihn Gott weggenommen hatte.',
        25: 'Und Metuselach war 187 Jahre alt; da zeugte er Lamech.',
        26: 'Und Metuselach lebte nach Lamechs Zeugung 782 Jahre und zeugte noch Söhne und Töchter.',
        27: 'Und aller Tage Metuselachs waren 969 Jahre; da starb er.',
        28: 'Und Lamech war 182 Jahre alt; da zeugte er einen Sohn.',
        29: 'Und er hieß seinen Sohn Noe und sprach: "Dieser soll uns Trost bringen, nach unserer Arbeit und unserer Hände Mühen, aus eben diesem Boden, den der Herr verflucht hat."',
        30: 'Und Lamech lebte nach Noes Zeugung 595 Jahre und zeugte noch Söhne und Töchter.',
        31: 'Und aller Tage Lamechs waren 777 Jahre; da starb er.',
        32: 'Und Noe war 500 Jahre alt; da zeugte Noe Sem, Cham und Japhet.',
    },
    6: {
        1: 'Als die Menschen angefangen hatten, sich auf dem Erdboden zu mehren, waren ihnen Töchter geboren worden.',
        2: 'Da sahen die Göttersöhne, daß die Menschentöchter schön waren, und sie nahmen sich zu Weibern, soviel sie wollten.',
        3: 'Da sprach der Herr: "Mein Geist verbleibe nimmer länger bei den Menschen! Er ist ja nur mehr Fleisch! Nur noch auf 120 Jahre sollen seine Tage sich belaufen!"',
        4: 'In jenen Zeiten waren die Riesen auf Erden gewesen, zumal damals, als die Göttersöhne mit den Menschentöchtern verkehrten und diese ihnen Kinder gebaren. Jenes sind die Recken der Urzeit, die Männer von Namen.',
        5: 'Da sah der Herr, daß die Bosheit der Menschen auf Erden groß ward und alles Dichten und Trachten ihres Herzen allezeit böse.',
        6: 'Da reute es den Herrn, daß er die Menschen auf Erden gemacht, und er ward tief bekümmert.',
        7: 'Darauf sprach der Herr: "Vertilgen von der Erde werde ich die Menschen, die ich erschaffen habe, vom Menschen bis zum Vieh, bis zum Gewürm und zu des Himmels Vögeln; denn ich bereue, sie gemacht zu haben."',
        8: 'Noe aber hatte Huld in des Herrn Augen gefunden.',
        9: 'Dies ist Noes Geschlechterfolge: Noe war ein gerechter, unsträflicher Mann unter seinen Zeitgenossen gewesen. Noe wandelte mit Gott.',
        10: 'Und Noe zeugte drei Söhne: Sem, Cham und Japhet.',
        11: 'Die Erde aber war vor Gottes Angesicht verderbt, und die Erde füllte sich mit Frevel.',
        12: 'Und Gott sah, wie die Erde verderbt war; denn jedes Fleischwesen hatte seinen Wandel auf Erden verderbt.',
        13: 'Da sprach Gott zu Noe. "Das Ende jedes Fleischwesens ist von mir verhängt; die Erde ist ja voller Frevel, die sie tun. Und so verderbe ich sie samt der Erde.',
        14: 'Mach eine Arche dir aus Fichtenholz! Und zu Behausungen sollst du die Arche einbauen! Und dann verpiche sie mit Harz von außen und von innen!',
        15: 'Also sollst du sie machen: 300 Ellen sei der Arche Länge und 50 Ellen ihre Breite und 30 Ellen ihre Höhe!',
        16: 'Und an der Arche sollst du eine Luke machen und bis auf eine Elle sie ganz oben anbringen, alsdann der Arche Tor in eine ihrer Längsseiten einsetzen und sie in untere und mittlere und obere Stockwerke einteilen!',
        17: 'Ich lasse jetzt die Wasserflut auf Erden kommen, um alles Fleisch, das unterm Himmel, zu vertilgen, darinnen Lebensodem ist. So möge alles, was auf Erden, sterben!',
        18: 'Mit dir nun treffe ich mein Abkommen, und so gehst du samt deinen Söhnen, deinem Weibe und deinen Schwiegertöchtern in die Arche.',
        19: 'Von allem Lebenden, von jedem Fleischeswesen, sollst du je ein Paar mit in die Arche bringen, um sie bei dir am Leben zu erhalten! Nur je ein Männchen und ein Weibchen soll es sein.',
        20: 'So von den Vögeln je nach ihrer Art, vom Vieh nach seiner Art, von allem, was auf Erden kriecht, nach seiner Art. Davon soll immer je ein Pärchen zu dir kommen, daß sie am Leben bleiben!',
        21: 'Du selbst beschaffe dir von jeglicher eßbaren Speise, und speichere solches bei dir auf! Zur Nahrung dient es alsdann dir und ihnen."',
        22: 'Und Noe tat so. Ganz so, wie ihm Gott befohlen hatte, tat er.',
    },
    7: {
        1: 'Dann sprach der Herr zu Noe: "Zieh du mit deinem ganzen Hause in die Arche! Denn dich habe ich gerecht vor mir in diesem Geschlecht erfunden.',
        2: 'Von allen reinen Tieren nimm dir je sieben, jeweils ein Männchen und ein Weibchen! Doch von den Tieren, die nicht rein, jeweils nur zwei, ein Männchen und ein Weibchen!',
        3: 'Auch von des Himmels Vögeln jeweils sieben, ein männliches und weibliches, um auf der ganzen Erde einen Stamm am Leben zu erhalten.',
        4: 'Von jetzt ab über sieben Tage lasse ich auf die Erde regnen durch vierzig Tage und durch vierzig Nächte, und ich vertilge alsdann alles Lebende, das ich gemacht, vom Erdboden."',
        5: 'Und Noe tat ganz so, wie ihn der Herr geheißen hatte.',
        6: 'Noe aber war 600 Jahre alt geworden, als die Wasserflut über die Erde kam.',
        7: 'So ging Noe mit seinen Söhnen, seinem Weibe und seinen Schwiegertöchtern in die Arche vor den Wassern der Flut.',
        8: 'Von den reinen und unreinen Tieren, von den Vögeln und von allem, was auf Erden kriecht,',
        9: 'waren paarweise zu Noe in die Arche gegangen je ein Männliches und ein Weibliches, wie Gott dem Noe geboten hatte.',
        10: 'Nach sieben Tagen geschah es, da waren die Wasser der Flut schon über die Erde gekommen.',
        11: 'Im 600. Lebensjahre des Noe, am 17. Tage des 2. Monats, an diesem Tage brachen alle Sprudel des großen Meeres auf, und die Himmelsluken öffneten sich.',
        12: 'Und Regen strömte auf die Erde 40 Tage und 40 Nächte lang.',
        13: 'An eben diesem Tage waren Noe und Noes Söhne Sem, Cham und Japhet, sowie sein Weib und seine drei Schwiegertöchter mit ihnen in die Arche gegangen,',
        14: 'sie und alle Tiere nach ihrer Art und alles Vieh nach seiner Art und alles Gewürm, das auf Erden kriecht, nach seiner Art und alle Vögel nach ihrer Art, was irgendwie Flügel hatte.',
        15: 'Sie gingen zu Noe in die Arche, je ein Paar von allem Fleisch mit Lebensodem.',
        16: 'Die Einziehenden waren nun, je ein Männliches und Weibliches von jedem Fleische, eingezogen, so wie ihm Gott befohlen. Da schloß der Herr hinter ihm zu.',
        17: 'Vierzig Tage kam die Flut über die Erde. Und das Wasser wuchs und hob die Arche, daß sie über der Erde schwebte.',
        18: 'Und das Wasser stieg und wuchs gewaltig an auf Erden, und die Arche fuhr auf dem Wasser.',
        19: 'Das Wasser stieg nun in gewaltiger Höhe über die Erde, und alle hohen Berge irgendwo unter dem Himmel wurden bedeckt.',
        20: 'Fünfzehn Ellen darüber hinaus war das Wasser gestiegen; so wurden die Berge bedeckt.',
        21: 'Da starb ein jeglich Fleisch, das sich auf Erden regte, an Vögeln, Vieh und Getier und an allem Gewürm, das auf Erden kroch, sowie alle Menschen.',
        22: 'Alles, was des Lebensgeistes Odem in seiner Nase hatte, soweit es sich auf dem Trockenen befand, war tot.',
        23: 'So vertilgte er alle Wesen auf dem Erdboden, vom Menschen bis zum Vieh und Gewürm und bis zu des Himmels Vögeln. Sie wurden von der Erde vertilgt; nur Noe und was bei ihm in der Arche war, blieb übrig.',
        24: 'Und das Wasser wuchs auf Erden 150 Tage lang.',
    },
    8: {
        1: 'Da gedachte Gott des Noe und all des Getieres und all des Viehs bei ihm in der Arche. Und Gott ließ einen Wind über die Erde wehen, und das Wasser sank.',
        2: 'Dann schlossen sich des Meeres Sprudel und die Himmelsluken, und dem Regen vom Himmel ward gewehrt.',
        3: 'Und das Wasser ging allmählich zurück auf Erden, und nach Ablauf der 150 Tage minderte sich das Wasser.',
        4: 'Und die Arche ließ sich am 17. Tage des 7. Monats auf dem Araratgebirge nieder.',
        5: 'Das Wasser aber hatte immer mehr abgenommen, bis zum 10. Monat. Am 1. Tag des 10. Monats waren die Spitzen der Berge sichtbar geworden.',
        6: 'Nach Ablauf von 40 Tagen öffnete Noe das Fenster der Arche, das er gemacht hatte.',
        7: 'Und er schickte den Raben aus. Dieser flog hin und her, bis das Wasser auf Erden vertrocknet war.',
        8: 'Dann ließ Noe die Taube von sich fortfliegen, zu sehen, ob sich das Wasser verlaufen hätte.',
        9: 'Die Taube aber fand keine Stätte für ihren Fuß. So kam sie zu ihm wieder in die Arche; denn auf der ganzen Erde war noch Wasser. Und er streckte seine Hand aus und nahm sie und brachte sie zu sich in die Arche.',
        10: 'Da wartete er noch sieben weitere Tage. Dann sandte er zum zweitenmal die Taube aus der Arche.',
        11: 'Da kam die Taube zu ihm zur Abendzeit mit einem frischen Ölblatt im Schnabel. Da erkannte Noe, daß sich das Wasser von der Erde verlaufen hatte.',
        12: 'Und er wartete noch weitere sieben Tage; dann ließ er die Taube wieder ausfliegen. Diesmal aber kehrte sie nicht mehr zu ihm zurück.',
        13: 'Im 601. Jahre, am ersten Tage des ersten Monats, waren die Wasser auf Erden vertrocknet. Da hob Noe das Dach der Arche und schaute aus, und siehe da, der Erdboden war wasserfrei geworden.',
        14: 'Am 27. Tage des zweiten Monats war die Erde ganz abgetrocknet.',
        15: 'Und Gott sprach zu Noe:',
        16: '"Geh aus der Arche, du selbst, dein Weib, deine Söhne und deine Schwiegertöchter bei dir!',
        17: 'Und alles Getier, das bei dir ist, von jedem Fleisch, an Vögeln, Vieh und jeglichem Gewürm, das auf Erden kriecht, führe du mit dir hinaus! Dann wimmle es auf Erden und sei fruchtbar auf Erden und mehre sich."',
        18: 'Da ging Noe hinaus, seine Söhne, sein Weib und seine Schwiegertöchter bei ihm.',
        19: 'Alles Getier, alles Gewürm, alle Vögel, alles, was sich auf Erden regt nach seinen Sippen, ging aus der Arche.',
        20: 'Und Noe baute dem Herrn einen Altar und nahm von allen reinen Tieren und reinen Vögeln einige und brachte auf dem Altar Brandopfer dar.',
        21: 'Da roch der Herr den süßen Duft. Und der Herr sprach bei sich: "Nicht will ich fortan mehr dem Boden fluchen des Menschen wegen. Der Menschen Herzenstrachten ist böse ja von Jugend auf. Hinfort will ich kein Lebewesen mehr so schlagen, wie ich\'s getan.',
        22: 'Fortan soll nimmer feiern, solange auch die Erde steht, die Saat mitsamt der Ernte und Frost und Hitze, der Sommer und der Winter und Tag und Nacht."',
    },
    9: {
        1: 'Und Gott segnete Noe und seine Söhne und sprach zu ihnen: "Seid fruchtbar, mehret euch und füllt die Erde!',
        2: 'Und Furcht vor euch und Schrecken komme über alle Landtiere und alle Himmelsvögel und über alles, was sich auf dem Boden regt, und über alle Meeresfische; in eure Hand sind sie gegeben.',
        3: 'Alles, was sich regt und lebt, sei euch zur Speise! So wie das grüne Kraut, so gebe ich euch alles.',
        4: 'Nur Fleisch mit seinem Lebensblut sollt ihr nicht essen!',
        5: "Und vollends euer eigen Blut will ich zurückverlangen; von jedem Tiere will ich's fordern; auch von des Menschen Hand, von seines Bruders Hand will ich das Menschenleben fordern.",
        6: 'Wer Menschenblut vergießt, des Blut soll durch die Menschen auch vergossen werden! Als Gottesbild hat er die Menschen ja gemacht.',
        7: 'Ihr, seid nun fruchtbar, mehret euch! Verbreitet euch auf Erden! Herrscht über sie!"',
        8: 'Und Gott sprach zu Noe und seinen Söhnen bei ihm also:',
        9: '"Ich schließe meinen Bund mit euch und euren Nachkommen und mit allen Lebewesen bei euch, was an Vögeln, Vieh und allen anderen Tieren auf Erden bei euch,',
        10: 'mit all denen, die aus der Arche kamen, und allem Getier der Erde.',
        11: 'Ja, meinen Bund errichte ich mit euch; kein Fleischeswesen werde durch der Flut Gewässer mehr vertilgt, und niemals wieder komme eine Flut, die Erde zu verheeren!"',
        12: 'Und Gott sprach: "Dies sei des Bundes Zeichen, den ich aufrichte zwischen mir und euch und allen Lebewesen, die bei euch, für ewige Zeiten:',
        13: 'Ich stelle meinen Bogen in die Wolken. Er sei das Bundeszeichen zwischen mir und dieser Erde!',
        14: 'Und wölke ich Gewölke ob der Erde, und im Gewölk erscheint der Bogen,',
        15: 'alsdarin gedenke ich des Bundes, der zwischen mir und euch und allen anderen Fleischeswesen, die da leben, gilt auf Erden. Nie wird das Wasser wieder eine Flut, die allem Fleische das Verderben brächte.',
        16: 'Und steht der Bogen im Gewölke, dann schaue ich ihn an und denke an den ewigen Bund, der zwischen Gott und allen Fleischeswesen, die da leben, gilt auf Erden."',
        17: 'Und Gott sprach zu Noe: "Dies ist des Bundes Zeichen, den ich errichtet habe zwischen mir und jedem Fleisch auf Erden."',
        18: 'Noes Söhne, die aus der Arche gingen, waren Sem, Cham und Japhet; Cham aber war Kanaans Vater.',
        19: 'Diese drei waren Noes Söhne, und ihnen entsprang die ganze Welt.',
        20: 'Noe aber begann mit dem Landbau und pflanzte einen Weinberg.',
        21: 'Da trank er von dem Wein, ward betrunken und lag entblößt in seinem Zelt.',
        22: 'Da schaute Cham, der Vater Kanaans, die Blöße seines Vaters und sagte es seinen beiden Brüdern draußen.',
        23: 'Sem und Japhet aber nahmen das Obergewand, legten es auf ihre Schultern, gingen rückwärts hinein und bedeckten ihres Vaters Blöße; ihr Gesicht aber war abgewandt, und so hatten sie ihres Vaters Blöße nicht gesehen.',
        24: 'Als Noe von seinem Wein erwachte, erfuhr er, was ihm sein jüngster Sohn getan hatte.',
        25: 'Da sprach er: "Verflucht sei Kanaan! Der niedrigste der Sklaven sei er seinen Brüdern!"',
        26: 'Und er sprach: "Des Herrn Gesegneter, mein Gott, sei Sem! Doch Kanaan sei ihm Sklave!',
        27: 'Für Japhet schaffe Gott gar weiten Raum! In Zelten aber wohne Sem! Und Kanaan sei ihm Sklave!"',
        28: 'Und Noe lebte nach der Flut 350 Jahre.',
        29: 'Und die ganze Lebensdauer Noes betrug 950 Jahre; dann starb er.',
    },
    10: {
        1: 'Und dies ist die Geschlechterfolge der Söhne Noes: Noes Söhnen Sem, Cham und Japhet wurden nach der Flut Söhne geboren.',
        2: 'Japhets Söhne waren Gomer, Magog, Madai, Javan, Tubal, Mesek und Tiras.',
        3: 'Gomers Söhne waren Askenaz, Riphat und Togarma.',
        4: 'Javans Söhne waren Elisa, Tarsis, Kittim und Dodanim.',
        5: 'Von diesen hatten sich der Heiden Inseln abgezweigt nach ihren Ländern, ihren verschiedenen Sprachen, Stämmen und Völkerschaften.',
        6: 'Chams Söhne waren Kusch, Misraim, Put und Kanaan.',
        7: 'Des Kusch Söhne waren Saba, Chavila, Sabta, Regma und Sabteka, und Regmas Söhne waren Scheba und Dedan.',
        8: 'Und Kusch hatte Nimrod gezeugt; dieser war zuerst ein Kriegsheld auf Erden gewesen.',
        9: 'Er war ein gewaltiger Jäger vor dem Herrn; daher pflegt man zu sagen: "Gleich Nimrod ist er ein gewaltiger Jäger vor dem Herrn."',
        10: 'Seine Herrschaft erstreckte sich anfangs auf Babel, Erech, Akkad und Kalne im Lande Sinear.',
        11: 'Von diesem Lande zog er nach Assur; da baute er Ninive - dazu Rechobot-Ir und Kelach',
        12: 'sowie Resen zwischen Ninive und Kelach -, das ist die große Stadt.',
        13: 'Und Misraim zeugte die Luditer, Anamiter, Lehabiter und Naphtuchiter',
        14: 'sowie die Patrusiter und Kasluchiter und die, von denen die Philister stammten, die Kaphtoriter.',
        15: 'Kanaan zeugte Sidon, seinen Erstgeborenen, und Chet,',
        16: 'sowie die Jebusiter, Amoriter und Girgasiter,',
        17: 'Chiviter, Arkiter, Siniter,',
        18: 'Arvaditer, Semariter und Chamatiter; hernach breiteten sich die Kanaaniterstämme aus.',
        19: 'Das Kanaanitergebiet erstreckte sich von Sidon bis nach Gerar, Gaza, Sodoma, Gomorrha, Adma. Seboim und Lesa.',
        20: 'Dies sind Chams Söhne nach ihren Stämmen, Sprachen, Ländern und Völkerschaften.',
        21: 'Auch Sem, dem Stammvater aller Söhne Ebers und ältesten Bruder Japhets, wurden Kinder geboren.',
        22: 'Sems Söhne waren Elam, Assur, Arpaksad, Lud und Aram.',
        23: 'Arams Söhne waren Uz, Chul, Geter und Masch.',
        24: 'Und Arpaksad zeugte Selach und Selach den Eber.',
        25: 'Dem Eber wurden zwei Söhne geboren; der eine hieß Peleg, weil sich zu seiner Zeit die Erde gespalten hatte; sein Bruder hieß Joktan.',
        26: 'Und Joktan zeugte Almodad, Seleph, Chasarmavet, Jerach,',
        27: 'Hadoram, Uzal, Dikla,',
        28: 'Obal, Abimael, Scheba,',
        29: 'Ophir, Chavila und Jobab: dies alles sind Joktans Söhne.',
        30: 'Ihre Wohnsitze reichten von Mesa bis Sephar beim Ostgebirge.',
        31: 'Dies sind die Söhne Sems nach ihren Stämmen, Sprachen, Ländern und Völkerschaften.',
        32: 'Dies sind die Stämme der Noesöhne nach ihren Sippen und Völkerschaften; von ihnen haben sich nach der Flut die Völker auf Erden abgesondert.',
    },
    11: {
        1: 'Die ganze Erde aber hatte eine Sprache und einerlei Worte.',
        2: 'Als sie von Osten herzogen, fanden sie im Lande Sinear eine Ebene und ließen sich darin nieder.',
        3: 'Und sie sprachen zueinander: "Auf! Laßt uns Luftziegel streichen und Backsteine brennen!" Und der Ziegel diente ihnen als Baustein; das Erdpech aber hatte ihnen als Mörtel gedient.',
        4: 'Sie sprachen: "Auf! Bauen wir uns eine Stadt und einen Turm mit einer Spitze bis zum Himmel, und machen wir uns eine Wohnstatt, daß wir uns nicht über die ganze Erde zerstreuen!"',
        5: 'Der Herr aber stieg herab, die Stadt und den Turm zu beschauen, den die Menschenkinder gebaut.',
        6: 'Da sprach der Herr: "Fürwahr! Ein Volk sind sie und haben alle dieselbe Sprache, und dies ist nur der Anfang ihres Tuns, und fortan wäre ihnen nichts verwehrt, was immer sie nur planen.',
        7: 'Auf nun! Wir wollen jetzt hinab und ihre Sprache mischen, daß keiner je des anderen Sprache mehr verstehe."',
        8: 'So zerstreute sie der Herr von dort über die ganze Erde, und sie mußten es lassen, die Stadt auszubauen.',
        9: 'Darum nennt man sie Babel; denn dort hat der Herr die Sprache der ganzen Erde gemischt, und von dort hat der Herr sie über die ganze Erde zerstreut.',
        10: 'Dies ist die Geschlechterfolge Sems: Als Sem 100 Jahre alt war, zeugte er Arpaksad, zwei Jahre nach der Flut.',
        11: 'Und Sem lebte nach Arpaksads Zeugung 500 Jahre und zeugte noch Söhne und Töchter.',
        12: 'Und Arpaksad war 35 Jahre alt; da zeugte er Selach.',
        13: 'Und Arpaksad lebte nach Selachs Zeugung 403 Jahre und zeugte noch Söhne und Töchter.',
        14: 'Und Selach war 30 Jahre alt; da zeugte er Eber.',
        15: 'Und Selach lebte nach Ebers Zeugung 403 Jahre und zeugte noch Söhne und Töchter.',
        16: 'Und Eber war 34 Jahre alt, da zeugte er Peleg.',
        17: 'Und Eber lebte nach Pelegs Zeugung 430 Jahre und zeugte noch Söhne und Töchter.',
        18: 'Und Peleg war 30 Jahre alt; da zeugte er Rëu.',
        19: 'Und Peleg lebte nach Rëus Zeugung 209 Jahre und zeugte noch Söhne und Töchter.',
        20: 'Und Rëu war 32 Jahre alt; da zeugte er Serug.',
        21: 'Und Rëu lebte nach Serugs Zeugung 207 Jahre und zeugte noch Söhne und Töchter.',
        22: 'Und Serug war 30 Jahre alt; da zeugte er Nachor.',
        23: 'Und Serug lebte nach Nachors Zeugung 200 Jahre und zeugte noch Söhne und Töchter.',
        24: 'Und Nachor war 29 Jahre alt; da zeugte er Terach.',
        25: 'Und Nachor lebte nach Terachs Zeugung 119 Jahre und zeugte noch Söhne und Töchter.',
        26: 'Und Terach war 70 Jahre alt; da zeugte er Abram, Nachor und Haran.',
        27: 'Dies ist die Geschlechterfolge Terachs: Terach zeugte Abram, Nachor und Haran, und Haran zeugte Lot.',
        28: 'Es starb aber Haran zu Lebzeiten seines Vaters Terach, in seinem Geburtslande zu Ur Kasdim.',
        29: 'Abram und Nachor nahmen sich dann Weiber; Abrams Weib hieß Sarai und Nachors Weib Milka, die Tochter Harans, des Vaters von Milka und Iska.',
        30: 'Sarai aber war unfruchtbar; sie hatte nie ein Kind geboren.',
        31: 'Und Terach nahm seinen Sohn Abram und seinen Enkel Lot, den Sohn Harans, und seine Schwiegertochter Sarai, das Weib seines Sohnes Abram, und sie zogen mit ihm aus Ur Kasdim, ins Land Kanaan zu wandern. So kamen sie bis Charan; hier aber ließen sie sich nieder.',
        32: 'Die Tage Terachs beliefen sich auf 205 Jahre; dann starb Terach zu Charan.',
    },
    12: {
        1: 'Und der Herr sprach zu Abram: "Aus deinem Lande, deiner Sippe zieh fort, aus deinem Vaterhause, ins Land, das ich dir zeigen werde!',
        2: 'ich mache dich zu einem großen Volke und segne dich und mache deinen Namen hochberühmt, daß du zum Segen werdest.',
        3: 'Denn segnen will ich, die dich segnen, und die verfluchen, die dich lästern. Der Erde Stämme alle sollen sich mit dir dann segnen!"',
        4: 'Und Abram zog fort, wie ihm der Herr gesagt, und mit ihm zog Lot; Abram aber war 75 Jahre alt, als er von Charan fortzog.',
        5: 'Und Abram nahm sein Weib Sarai und seinen Brudersohn Lot und all ihre Habe, die sie erworben, sowie die Seelen, die sie in Charan bekommen hatten, und sie zogen fort, ins Land Kanaan zu wandern, und sie kamen auch in das Land Kanaan.',
        6: 'Und Abram durchzog das Land bis zu Sichems Wohnsitz, bis zum Maulbeerbaum; damals aber waren die Kanaaniter im Land.',
        7: 'Da erschien der Herr dem Abram und sprach: "Ich gebe deinem Stamme dieses Land." Da baute er dort einen Altar dem Herrn, der ihm erschienen war.',
        8: 'Von dort zog er auf das Gebirge östlich von Betel und schlug sein Zelt auf, Betel im Westen und Ai im Osten. Dort baute er dem Herrn einen Altar und rief des Herrn Namen an.',
        9: 'Dann zog Abram weiter und weiter, dem Südland zu.',
        10: 'Nun kam die Hungersnot ins Land, und Abram zog nach Ägypten, hier zu verbleiben; denn schwer lag die Hungersnot auf dem Land.',
        11: 'Als er nahe bei Ägypten war, sprach er zu seinem Weib Sarai: "Ich weiß wohl, daß du ein schönes Weib bist.',
        12: 'Sehen dich nun die Ägypter, dann denken sie: Dies ist sein Weib, und alsdann töten sie mich; dich aber werden sie am Leben lassen.',
        13: 'Sag doch, du seiest meine Schwester, daß es mir um deinetwillen gut gehe. Dann bleibe ich deinetwegen ungefährdet."',
        14: 'Als Abram nach Ägypten kam, sahen die Ägypter, daß das Weib überaus schön war.',
        15: 'Auch des Pharao Fürsten sahen sie und rühmten sie vor Pharao. So ward das Weib in Pharaos Haus geholt.',
        16: 'Dem Abram aber war er ihretwegen hold geworden; und so bekam er Schafe, Rinder, Esel, Sklaven, Mägde, Eselinnen und Kamele.',
        17: 'Der Herr aber schlug mit schweren Plagen Pharao und sein Haus wegen Sarai, des Weibes Abrams.',
        18: 'Da ließ Pharao den Abram rufen und sprach: "Was hast du mir da angetan? Warum hast du mir verhehlt, daß sie dein Weib ist?',
        19: 'Warum hast du gesagt: \'Sie ist nur meine Schwester\'? Und so nahm ich sie mir zum Weib. Nun aber sieh, hier ist dein Weib! Nimm sie und geh fort!"',
        20: 'Und Pharao entbot seinetwegen Leute, daß sie ihn, sein Weib und all seine Habe fortschafften.',
    },
    13: {
        1: 'Abram zog nun von Ägypten aufwärts, er, sein Weib und all seine Habe, auch Lot mit ihm, ins Südland.',
        2: 'Abram war sehr reich an Vieh, Silber und Gold.',
        3: 'Und er zog nach öfterem Lagern aus dem Südland bis nach Betel, bis an die Stätte, wo vordem sein Zelt gestanden, zwischen Betel und Ai,',
        4: 'zu der Stätte des Altars, den er früher dort gebaut hatte. Dort rief Abram des Herrn Namen an.',
        5: 'Auch Lot, der mit Abram zog, besaß Schafe, Rinder und Kamele.',
        6: 'Aber das Land ließ sie nicht beisammen hausen; denn ihre Habe war groß geworden, und so konnten sie nicht beieinander bleiben.',
        7: 'Und Streit ward zwischen den Hirten der Herde Abrams und denen der Herde Lots; die Kanaaniter und die Periziter hausten aber damals im Land.',
        8: 'Da sprach Abram zu Lot: "Nimmer sei Zwietracht zwischen mir und dir, zwischen meinen Hirten und deinen! Wir sind ja Brüder.',
        9: 'Steht nicht das ganze Land dir offen? Trenne dich lieber von mir! Willst du zur Linken, gehe ich zur Rechten; willst du zur Rechten, gehe ich zur Linken."',
        10: 'Da hob Lot seine Augen auf und sah, daß die ganze Au des Jordan völlig bewässert war, bevor der Herr Sodom und Gomorrha zerstörte - gleich dem Garten des Herrn und wie das Ägypterland - bis Soar hin.',
        11: 'Und Lot wählte sich die ganze Au des Jordan. So brach Lot nach Osten auf, und sie schieden voneinander.',
        12: 'Abram hatte sich im Lande Kanaan angesiedelt. Lot aber in den Städten der Au, und so zeltete er bis nach Sodom.',
        13: 'Sodoms Männer aber waren böse und gewaltige Sünder wider den Herrn.',
        14: 'Der Herr aber sprach zu Abram, als Lot von ihm geschieden: "Erhebe deine Augen! Schau von dem Orte, wo du bist, nach Norden, Süden, Osten und Westen!',
        15: 'All das Land, das du erblickst, gebe ich dir und deinem Stamm für immer.',
        16: 'Dann mache ich deinen Stamm den Staubkörnchen der Erde gleich. Vermöchte jemand der Erde Staubkörnchen zu zählen, dann könnte auch dein Stamm gezählt werden.',
        17: 'Auf! Umwandle dieses Land nach Länge und Breite! Denn dir will ich es geben."',
        18: 'Und Abram stimmte zu, kam und ließ sich bei Mamres Terebinthen zu Hebron nieder und baute hier dem Herrn einen Altar.',
    },
    14: {
        1: 'Und es geschah in den Tagen Amraphels, des Königs von Sinear, Adoks, des Königs von Ellasar, Kedorlaomers, des Königs von Elam, und Tidals, des Königs von Gojim.',
        2: 'Diese hatten Krieg beschlossen wider Bera, Sodoms König, Birsa, den König von Gomorrha, Sinab, den König von Adma, Semeber, den König von Seboim, und den König von Bela, das ist Soar.',
        3: 'Alle diese zogen vereint in das Tal Siddim, das ist das Salzmeer.',
        4: 'Zwölf Jahre waren sie Kedorlaomer dienstbar gewesen; im dreizehnten aber fielen sie ab.',
        5: 'Im vierzehnten Jahre nun zogen Kedorlaomer und die Könige bei ihm heran; da schlugen sie die Rephaiter zu Astarot Karnaim, die Zuziter zu Ham und die Emiter in der Ebene von Kirjataim',
        6: 'und die Choriter auf den Bergen von Seïr bis nach EI Paran, das östlich von der Wüste liegt.',
        7: 'Dann machten sie kehrt und kamen nach En Mispat, das ist Kades, und schlugen das ganze Gefilde der Amalekiter, sowie die Amoriter, die in Chasason Tamar hausten.',
        8: 'Da zogen der König von Sodom und der König von Gomorrha aus, sowie der König von Adma, der König von Seboim und der von Bela, das ist Soar, und rüsteten zum Kampfe gegen jene im Siddimtale,',
        9: 'gegen Kedorlaomer, den König von Elam, Tidal, den König von Gojim, Amraphel, den König von Sinear, und Arjok, den König von Ellasar, vier Könige gegen fünf.',
        10: 'Das Siddimtal aber ist voller Erdpechgruben. Als nun die Könige von Sodom und Gomorrha fliehen mußten, warfen sie sich hinein; die übrigen aber flohen ins Gebirge.',
        11: 'Da nahmen jene alle Habe Sodoms und Gomorrhas und all ihren Mundvorrat und zogen ab.',
        12: 'Auch Lot, Abrams Brudersohn, und seine Habe nahmen sie mit und zogen ab; er wohnte nämlich zu Sodom.',
        13: 'Nun kam ein Flüchtling und brachte Kunde dem Hebräer Abram; er wohnte bei den Terebinthen Mamres, des Amoriters, des Bruders von Eskol und Aner, und diese waren mit Abram im Bund.',
        14: 'Als Abram hörte, sein Bruder sei gefangen, entbot er seine Verbündeten und seine 318 Hausgeborenen und jagte bis Dan nach.',
        15: 'Er überfiel sie des Nachts, er und seine Diener, schlug und verfolgte sie bis Choba, links von Damaskus.',
        16: 'So brachte er alle Habe zurück. Auch seinen Bruder Lot und seine Habe brachte er zurück, ebenso die Weiber und das Volk.',
        17: 'Da zog ihm der König von Sodom entgegen, als er vom Sieg über Kedorlaomer und die Könige bei ihm zurückkehrte, im Tale Save, das ist das Königstal.',
        18: 'Der König von Salem aber, Melchisedech, hatte Brot und Wein mitgebracht; er war ja ein Priester des höchsten Gottes.',
        19: 'Und er segnete ihn und sprach: "Vom höchsten Gott, dem Schöpfer Himmels und der Erden, sei gesegnet Abram!',
        20: 'Gepriesen sei der höchste Gott, der deine Feinde dir in die Hand gegeben!" Und Abram gab ihm den Zehnten von allem.',
        21: 'Und der König von Sodom sprach zu Abram: "Gib mir die Leute! Die Habe behalte für dich!"',
        22: 'Da sprach Abram zum König von Sodom: "Zum Herrn, dem höchsten Gott, dem Schöpfer Himmels und der Erde, erhebe ich meine Hand:',
        23: "Keinen Faden, keinen Schuhriemen, gar nichts von dem, was dir eigen, nehme ich an. Du sollst nicht sagen: 'Ich habe Abram reich gemacht.'",
        24: 'Nichts will ich. Nur was die Jungmannschaft verzehrt, und den Anteil für die Männer, die mit mir gezogen, Aner, Eskol und Mamre! Sie mögen ihren Anteil nehmen!"',
    },
    15: {
        1: 'Hernach erging das Wort des Herrn an Abram in einem Gesichte also: "Abram, fürchte dich nicht! Ich bin dir doch ein Schild; dein Lohn ist überreich."',
        2: 'Da sprach Abram: "Herr, ach Herr, was kannst du mir geben, da ich doch kinderlos wandle? Ist doch der Sohn meines Haussklaven Eliezer der Erbesohn."',
        3: 'Und Abram sprach: "Mir hast du ja keinen Nachkommen geschenkt; so wird mich mein Haussklave eben beerben."',
        4: 'Aber da erging das Wort des Herrn an ihn also: "Dieser wird dich nicht beerben; dein eigener Leibessprosse wird dich einst beerben."',
        5: 'Und er führte ihn ins Freie und sprach: "Blick auf zum Himmel und zähle die Sterne! Kannst du sie zählen?" Dann sprach er zu ihm: "Also wird auch dein Stamm sein."',
        6: 'Und er glaubte dem Herrn, und dies erachtete er ihm als Verdienst.',
        7: 'Und er sprach zu ihm: "Ich bin der Herr, der dich aus Ur Kasdim geführt, um dir dies Land zu geben, damit du es besitzest."',
        8: 'Da sprach er: "Herr, ach Herr! Woran erkenne ich, daß ich\'s besitzen soll?"',
        9: 'Und er sprach zu ihm:"Hol mir jetzt eine dreijährige Kuh und eine dreijährige Ziege und einen dreijährigen Widder und eine Turteltaube sowie eine junge Taube!"',
        10: 'Da holte er ihm diese alle. Dann zerlegte er sie mitten durch und legte jede Hälfte der anderen gegenüber; die Vögel aber hatte er nicht zerteilt.',
        11: 'Da stießen die Raubvögel auf die Tierleichen nieder; Abram aber scheuchte sie.',
        12: 'Wie nun die Sonne im Untergehen war, befiel Abram ein Tiefschlaf, und eine schwere, dunkle Ahnung überkam ihn.',
        13: 'Da sprach er zu Abram. "Du sollst jetzt wissen: Dein Stamm wird Fremdling sein in einem Lande, das dir nicht eigen. Dann front er ihm, und dies bedrückt ihn an vierhundert Jahre.',
        14: 'Jedoch das Volk, dem sie dort fronen, das will ich richten. Dann ziehen sie mit reicher Habe aus.',
        15: 'Du aber gehst zu deinen Vätern ein im Frieden, zu deiner Grabesstatt in schönem Alter.',
        16: 'Im vierten Gliede kehren sie hierher; noch ist nicht voll der Amoriter Maß."',
        17: 'Dann ging die Sonne unter, und dichte Finsternis kam; da erschien ein rauchender Ofen und eine Feuerflamme, und zwischen jenen Stücken fuhr es durch.',
        18: 'An jenem Tag schloß der Herr mit Abram einen Bund mit den Worten: "Ich gebe deinem Stamme dieses Land vom Fluß Ägyptens bis zum großen Strom, dem Euphratstrom,',
        19: 'das Gebiet der Keniter, Keniziter, Kadmoniter,',
        20: 'Chittiter, Periziter, Rephaiter',
        21: 'und Amoriter, Kanaaniter, Girgasiter sowie Jebusiter."',
    },
    16: {
        1: 'Sarai aber, Abrams Weib, hatte ihm kein Kind geboren; sie hatte aber eine ägyptische Magd, die Hagar hieß.',
        2: 'Nun sprach Sarai zu Abram: "Der Herr hat mir Kinder versagt. Heirate meine Magd! Vielleicht komme ich durch sie zu Kindern. Und Abram folgte den Worten Sarais.',
        3: 'So nahm Sarai, Abrams Weib, ihre Magd, die Ägypterin Hagar, nach Ablauf von zehn Jahren, die Abram im Lande Kanaan gewohnt, und gab sie ihrem Manne Abram, ihm selbst, zum Weib.',
        4: 'Und er heiratete Hagar, und sie empfing. Als sie aber sah, daß sie guter Hoffnung war, sank ihre Herrin in ihren Augen.',
        5: 'Da sprach Sarai zu Abram: "Meine Kränkung über dich! Ich selbst habe dir meine Magd abgetreten; nun sie aber sah, daß sie in Hoffnung sei, sank ich in ihren Augen. Zwischen mir und dir richte der Herr!"',
        6: 'Da sprach Abram zu Sarai: "In deiner Hand ist deine Magd. Tue mit ihr, wie es dir gefällt!" Da drückte Sarai sie so, daß sie ihr entfloh.',
        7: 'Der Engel des Herrn aber traf sie an einem gewissen Wasserquell in der Wüste, am Quell auf dem Wege nach Schur.',
        8: 'Und er sprach: "Hagar, Sarais Magd, wo kommst du her? Wo gehst du hin?" Sie sprach: "Vor meiner Herrin Sarai bin ich flüchtig."',
        9: 'Da sprach der Engel des Herrn zu ihr: "Kehr heim zu deiner Herrin und unterwirf dich ihren Händen!"',
        10: 'Dann sprach der Engel des Herrn zu ihr: "Ich mache deinen Stamm gar zahlreich; vor Menge kann man ihn nicht zählen."',
        11: 'Und der Engel des Herrn sprach zu ihr: "Du bist gesegnet und wirst einen Sohn gebären. Den heißest du Ismael: denn der Herr hat dein Elend gehört.',
        12: 'Ein Wildeselmensch wird er werden; seine Hand gegen alle und aller Hand gegen ihn! Allen seinen Brüdern steht er dreist gegenüber."',
        13: 'Da nannte sie den Herrn, der mit ihr redete, "du bist der Gott des Trostes"; denn sie sprach: "Habe ich nicht schließlich Trost erfahren?"',
        14: 'Daher nannte man den Brunnen: Lachaj Roi (Des Lebenden Trostbrunnen): er liegt zwischen Kades und Berad.',
        15: 'Und Hagar gebar dem Abram einen Sohn, und Abram nannte den Sohn, den ihm Hagar geboren, Ismael.',
        16: 'Und Abram war 86 Jahre alt, als Hagar dem Abram den Ismael gebar.',
    },
    17: {
        1: 'Abram war 99 Jahre alt; da erschien der Herr dem Abram und sprach zu ihm: "Ich bin ein mächtiger Gott. Vor mir nur wandle! Alsdann fehlt dir nichts.',
        2: 'Ich schließe zwischen mir und dir den Bund und will dich mächtig mehren."',
        3: 'Da fiel Abram auf sein Antlitz, und Gott redete mit ihm also:',
        4: '"Das ist mein Bund mit dir: Stammvater einer Völkermenge wirst du jetzt.',
        5: 'Drum sollst du fortan nimmer Abram heißen. Nein, Abraham ist jetzt dein Name; zu einer Völkermenge Vater mache ich dich ja.',
        6: 'Ich lasse dich gar zahlreich werden und mache dich zu Völkern, und Könige entsprießen dir.',
        7: 'Und zwischen mir und dir errichte ich den Bund und zwischen mir und deinem Stamm nach dir, ja, einen ewigen Bund für alle die Geschlechter, daß ich dir Schutzgott sei und deinem Stamm nach dir.',
        8: 'Ich gebe dir und deinem Stamm nach dir den Boden deiner Pilgerfahrten, das ganze Land von Kanaan, zu ewigem Besitze; ein Schutzgott will ich ihnen sein."',
        9: 'Und Gott sprach zu Abraham: "Du aber halte meinen Bund, du und dein Stamm nach dir, in allen den Geschlechtern!',
        10: 'Das ist mein Bund, den ihr einhalten sollt, der zwischen mir und euch und deinem Stamm nach dir besteht: Bei euch soll alles Männliche beschnitten werden!',
        11: 'Und zwar sollt ihr an eurer Vorhaut Fleisch beschnitten sein! Dies ist das Bundeszeichen zwischen mir und euch.',
        12: 'Bei euch soll mit acht Tagen alles Männliche beschnitten werden, Geschlecht für Geschlecht, auch selbst der Haussklave und der von irgendeinem Fremden Angekaufte, der nimmer deines Stammes ist.',
        13: 'Beschnitten werde dein Haussklave und der von dir mit Geld Erkaufte! So sei mein Bund an eurem Fleisch zum ewigen Bunde!',
        14: 'Doch wer gesund und dennoch unbeschnitten ist, wer nicht an seiner Vorhaut Fleisch beschnitten, ein solches Wesen wird aus seinem Volke ausgestrichen. Zerrissen hat es meinen Bund."',
        15: 'Und Gott sprach zu Abraham: "Du sollst dein Weib Sarai nicht länger Sarai nennen! Nein! Sara soll ihr Name sein!',
        16: 'Ich segne sie und schenke dir durch sie noch einen Sohn. Ich segne sie; dann wird sie eine Völkermutter, und Völkerkönige entsprießen ihr."',
        17: 'Da fiel Abraham auf sein Antlitz, lachte und sprach bei sich: "Sollte einem Hundertjährigen noch ein Kind geboren werden, oder sollte Sara, die neunzigjährige, noch gebären können?"',
        18: 'Und Abraham sprach zu Gott: "Möchte nur Ismael auf dein Geheiß am Leben bleiben!"',
        19: 'Da sprach Gott: "Trotzdem wird Sara, dies dein Weib, dir einen Sohn gebären; den sollst du Isaak heißen! Mit ihm errichte ich dann meinen Bund zum ewigen Bund für seinen Stamm nach ihm.',
        20: 'Auch Ismaels wegen will ich dich erhören; ich segne ihn und lasse Frucht ihn tragen und mehre ihn gar mächtiglich. Zwölf Fürsten wird er zeugen, und also mache ich auch ihn zu einem großen Volke.',
        21: 'Doch meinen Bund will ich mit Isaak schließen, den dir um diese Zeit im künftigen Jahre Sara schenkt."',
        22: 'Und er beendete seine Unterredung mit ihm. Und Gott fuhr vor Abraham auf.',
        23: 'Da nahm Abraham seinen Sohn Ismael und alle seine Haussklaven, sowie alle mit Geld von ihm Erkauften, jedes Männliche unter den Leuten in Abrahams Haus, und beschnitt das Fleisch ihrer Vorhaut an eben diesem Tage, gleich nachdem Gott mit ihm gesprochen hatte.',
        24: 'Abraham aber war 99 Jahre alt, als er am Fleische seiner Vorhaut beschnitten ward.',
        25: 'Und 13 Jahre alt war sein Sohn Ismael, als er am Fleische seiner Vorhaut beschnitten ward.',
        26: 'Am gleichen Tage war Abraham beschnitten worden wie sein Sohn Ismael.',
        27: 'Und alle seine Hausgenossen, sowohl die Haussklaven als auch die mit Geld von Fremden Gekauften, waren mit ihm beschnitten worden.',
    },
    18: {
        1: 'Und der Herr erschien ihm bei den Terebinthen Mamres, als er sich an den Zelteingang zur Vormittagszeit setzte.',
        2: 'Wie er nun seine Augen erhob und aufblickte, standen drei Männer vor ihm. Kaum sah er sie, lief er schon vom Zelteingang auf sie zu und neigte sich zu Boden.',
        3: 'Dann sprach er: "Herr, finde ich in deinen Augen Gnade, dann ziehe nicht an deinem Sklaven vorüber!',
        4: 'Man soll etwas Wasser bringen! Dann wascht ihr euch die Füße und legt euch unter diesen Baum!',
        5: 'Ich hole inzwischen einen Bissen Brot, daß ihr euch stärket. Dann mögt ihr weiterziehen! Denn darum seid ihr bei eurem Sklaven vorbeigekommen." Sie sprachen: "Tu so, wie du gesagt!"',
        6: 'Da eilte Abraham ins Zelt zu Sara und sprach: "Schnell drei Maß Mehl, Feinmehl! Knete und backe Kuchen!"',
        7: 'Dann lief Abraham zu den Rindern, holte ein Kalb, zart und kräftig, und gab es dem Diener, der es eilends bereitete.',
        8: 'Dann holte er Butter und Milch sowie das Kalb, das er hatte bereiten lassen, und setzte es ihnen vor; er selbst wartete ihnen unter dem Baume auf, während sie aßen.',
        9: 'Da sprachen sie zu ihm: "Wo ist denn Sara, dein Weib?" Er sprach: "Hier im Zelt!"',
        10: 'Da sprach er: "Ich kehre zu dir nach Ablauf von neun Monaten zurück; da hat dein Weib Sara einen Sohn." Sara aber horchte am Zelteingang hinter ihm.',
        11: 'Abraham aber und Sara waren alt und hochbetagt, und Sara erging es nicht mehr nach Weiberart.',
        12: 'So lachte Sara in sich hinein, indem sie dachte: "Welk geworden, sollte ich noch der Liebe pflegen? Mein Herr ist gleichfalls alt."',
        13: 'Darauf sprach der Herr zu Abraham: "Warum lacht Sara und denkt dabei: \'Soll ich wahrhaftig ein Kind bekommen, nachdem ich alt geworden?\'',
        14: 'Ist für den Herrn etwas unmöglich? Um diese Zeit kehre ich zu dir nach Ablauf von neun Monaten zurück; dann hat Sara einen Sohn."',
        15: 'Da leugnete Sara und sprach: "Ich habe nicht gelacht"; denn sie hatte Angst bekommen; er aber sprach: "Nein! Du hast gelacht."',
        16: 'Herauf brachen die Männer von da auf und bogen gegen Sodom ab; Abraham aber ging mit ihnen, sie zu begleiten.',
        17: 'Und der Herr sprach: "Soll ich vor Abraham verhehlen, was ich zu tun im Sinne habe?',
        18: 'Doch Abraham soll zu einem Volke werden, groß und stark! Dann sollen sich in ihm die Erdenvölker alle segnen!',
        19: 'Nein! Auserkoren hab ich ihn, auf daß er seinen Söhnen und dem Haus nach ihm gebiete, sie sollen doch den Weg des Herrn einhalten Gerechtigkeit und Recht ausübend, auf daß der Herr das über Abraham brächte, was er ihm einst verheißen hat."',
        20: 'Und der Herr sprach: "Der Klageruf schwillt wider Sodom und Gomorrha an, und ihre Sünde wuchtet schwer.',
        21: 'Ich will hinab und sehen, ob sie getan, so wie ihr Ruf, der vor mich kam, vermeldet. Alsdann Vernichtung! Wenn aber nicht - ich will es wissen."',
        22: 'Da wandten sich die Männer von dort weg und gingen Sodom zu. Abraham aber blieb vor dem Herrn stehen.',
        23: 'Und Abraham trat vor und sprach: "Willst du Schuldlose mit Schuldigen hinraffen?',
        24: "Vielleicht gibt's in der Stadt noch fünfzig Schuldlose. Willst du diese hinraffen und nicht vielmehr den Ort begnadigen, den fünfzig Schuldlosen darin zulieb?",
        25: 'Nicht würdig wäre es deiner, solches zu tun, Schuldige und Unschuldige zusammen zu töten, daß es eins wäre, schuldlos oder schuldig. Das wäre deiner unwürdig. Sollte der ganzen Erde Richter nicht Gerechtigkeit üben?"',
        26: 'Da sprach der Herr: "Fänd ich nur fünfzig Schuldlose zu Sodom in der Stadt, dann wollte ich ihretwegen den ganzen Ort begnadigen."',
        27: 'Da hob Abraham an und sprach: "Ich habe mich nun unterfangen, mit meinem Herrn zu reden, wennschon ich Staub und Asche bin.',
        28: 'Vielleicht fehlen an den fünfzig Schuldlosen nur fünf. Willst du die ganze Stadt um dieser fünfe willen zugrunde richten?" Er sprach: "Nein, falls ich dort fünfundvierzig fände."',
        29: 'Da redete er abermals mit ihm und sprach: "Vielleicht finden sich nur vierzig darin." Er sprach: "Dann tue ich es nicht um der vierzig willen."',
        30: 'Er sprach: "Ach zürne nicht, mein Herr, daß ich noch einmal rede! Vielleicht finden sich nur dreißig darin." Er sprach: "Dann tue ich es nicht, wenn ich nur dreißig darin fände."',
        31: 'Er sprach - "Ich habe mich nun schon unterfangen, mit meinem Herrn zu reden. Vielleicht finden sich nur zwanzig darin." Er sprach: "Ich richte sie nicht zugrunde um der zwanzig Willen."',
        32: 'Er sprach: "Ach zürne nicht, mein Herr, wenn ich dies eine Mal noch rede! Vielleicht finden sich nur zehn darin." Er sprach: "Ich richte sie dann nicht zugrunde wegen dieser zehn."',
        33: 'Dann ging der Herr fort, sogleich, nachdem er das Gespräch mit Abraham beendet hatte. Abraham aber kehrte an seinen Ort zurück.',
    },
    19: {
        1: 'Und die beiden Engel kamen des Abends nach Sodom; Lot aber wohnte in Sodoms Vorstadt. Als Lot sie erblickte, trat er an sie heran und neigte sich bis zum Boden.',
        2: 'Dann sprach er: "Meine Herren! Kehrt doch in eures Knechtes Haus zur Nachtrast ein und wascht euch die Füße! Dann möget ihr frühmorgens eures Weges ziehen!" Sie aber sprachen: "Nein! Wir wollen auf der Straße mächtigen."',
        3: 'Er aber drang inständig in sie, und so kehrten sie bei ihm ein und betraten sein Haus. Da bereitete er ihnen eine Mahlzeit, buk ungesäuerte Kuchen, und sie aßen.',
        4: 'Noch hatten sie sich nicht schlafen gelegt, als schon die Männer der Stadt, die Leute von Sodom, das Haus umringten, jung und alt, das ganze Volk bis auf den letzten Mann.',
        5: 'Und sie riefen nach Lot und sprachen zu ihm: "Wo sind die Männer, die heute abend zu dir gekommen sind? Bring sie uns heraus, damit wir sie erkennen!"',
        6: 'Da ging Lot zu ihnen vor die Tür hinaus; die Tür aber verschloß er hinter sich.',
        7: 'Und er sprach: "Meine Brüder, tut doch nichts so Unnatürliches!',
        8: 'Da habe ich zwei Töchter, die noch keinen Mann erkannt haben, sie will ich zu euch bringen. Tut an ihnen, was euch beliebt. Doch diesen Männern dürft ihr nichts tun; denn darum sind sie in meines Daches Schatten getreten."',
        9: 'Da schrien sie: "Pack dich weg!" und sagten: "Kam einer als Gast und Richter zugleich? Jetzt tun wir dir noch übler als jenen." Und sie drangen hart auf den Mann, auf Lot, ein und gingen daran, die Tür zu erbrechen.',
        10: 'Da griffen die Männer hinaus, zogen Lot zu sich ins Haus, nachdem sie die Tür abgeschlossen hatten.',
        11: 'Die Leute am Hauseingang aber hatten sie mit Blindheit geschlagen, klein und groß, und so konnten sie die Tür nicht finden.',
        12: 'Die Männer aber sprachen zu Lot: "Hast du noch jemanden hier? Etwa einen Schwiegersohn, deine Söhne und deine Töchter? All die Deinen in der Stadt führe von diesem Ort weg!',
        13: 'Denn wir vertilgen diese Stätte, weil der Klageschrei wider sie vor dem Herrn mächtig geworden. Darum sandte uns der Herr, sie zu verderben."',
        14: 'Da ging Lot hinaus und redete mit seinen Schwiegersöhnen, die seine Töchter geheiratet, und sprach: "Auf! Fort aus diesem Ort! Der Herr will diese Stadt vertilgen!" Aber er schien seinen Schwiegersöhnen zu scherzen.',
        15: 'Nach Anbruch der Morgenröte aber drängten die Engel Lot und sprachen: "Auf! Nimm dein Weib und diese deine beiden Töchter hier, daß du nicht weggerafft wirst ob der Missetat der Stadt!"',
        16: 'Als er zögerte, griffen die Männer ihn, sein Weib und seine beiden Töchter an der Hand, weil der Herr ihn schonen wollte; sie führten ihn fort und ließen ihn erst draußen vor der Stadt los.',
        17: 'Während sie sie hinausführten, sprach einer: "Flüchte dich um deines Lebens willen! Schau dich nicht um! Bleib nirgends in der Niederung stehen! Flieh ins Gebirge, daß du nicht weggerafft wirst!"',
        18: 'Lot aber sprach zu ihnen: "Nicht so, Herr!',
        19: 'Dein Knecht hat nun einmal Gnade bei dir gefunden; groß Erbarmen hast du mir erwiesen, mir das Leben zu retten; aber ich kann nicht ins Gebirge fliehen. Dann aber könnte mich das Verderben ereilen, daß ich stürbe!',
        20: 'Siehe, diese Stadt ist nahe genug, hineinzuflüchten, und nur ein kleines Stück ist\'s noch. Dahin könnte ich mich flüchten. Es ist ja nur noch ein kleines Stück; dann könnte ich am Leben bleiben."',
        21: 'Er sprach zu ihm: "Wohlan, ich nehme auch darin Rücksicht auf dich und will diese Stadt, von der du sprichst, nicht zerstören.',
        22: 'Flieh eilends dorthin! Denn ich kann nichts tun, bis du dorthin kommst." Deshalb nannte man die Stadt Soar.',
        23: 'Eben war die Sonne aufgegangen; da kam Lot nach Soar.',
        24: 'Der Herr aber ließ auf Sodom und Gomorrha Schwefel und Feuer regnen, vom Herrn her, vom Himmel herab.',
        25: 'Und er vernichtete diese Städte, die ganze Niederung und alle Insassen der Städte und das Gewächs des Feldes.',
        26: 'Sein Weib aber schaute hinter sich und ward zu einer Salzsäule.',
        27: 'Abraham begab sich nun in der Frühe an die Stätte, wo er vor dem Herrn gestanden.',
        28: 'Und er schaute auf Sodom und Gomorrha hinab und auf das ganze Land der Niederung; da sah er, wie ein Qualm vom Lande aufstieg, wie eines Schmelzofens Qualm.',
        29: 'So war es, als Gott die Städte der Niederung zerstörte; dabei gedachte Gott Abrahams und schickte Lot aus dem Bereich der Zerstörung weg, als er die Städte, in denen Lot gewohnt, zerstörte.',
        30: 'Lot zog dann von Soar hinauf und wohnte im Gebirge mit seinen beiden Töchtern; denn er fürchtete sich, in Soar zu bleiben. So wohnte er in einer Höhle mit seinen beiden Töchtern.',
        31: 'Da sprach die Ältere zu der jüngeren: "Unser Vater ist alt, und auf Erden gibt es niemand mehr, der Umgang mit uns haben könnte nach aller Welt Brauch.',
        32: 'Komm, wir wollen unserem Vater Wein zu trinken geben und uns zu ihm legen, daß wir durch unseren Vater unseren Stamm erhalten!"',
        33: 'Da gaben sie ihrem Vater in jener Nacht Wein zu trinken; dann ging die Ältere hinein und schlief bei ihrem Vater; er aber merkte nicht, wie sie sich legte, noch wie sie aufstand.',
        34: 'Am Tage darauf sprach die Ältere zur Jüngeren: "Siehe, ich habe heute nacht bei meinem Vater geschlafen; wir wollen ihm auch diese Nacht Wein zu trinken geben. Dann geh hinein und schlaf bei ihm, daß wir durch unseren Vater unseren Stamm erhalten!"',
        35: 'Und sie gaben ihrem Vater auch an diesem Abend Wein zu trinken; dann ging die Jüngere hin und schlief bei ihm; er aber merkte nicht, wie sie sich legte, noch wie sie aufstand.',
        36: 'Also kamen die beiden Töchter Lots durch ihren Vater in Hoffnung.',
        37: 'Und die Ältere gebar einen Sohn und nannte ihn Moab; das ist der Stammvater der heutigen Moabiter.',
        38: 'Auch die jüngere gebar einen Sohn und sie nannte ihn Ben Ammi; das ist der Stammvater der heutigen Ammoniter.',
    },
    20: {
        1: 'Und Abraham zog von dort ins Gebiet des Südlands und wohnte zwischen Kades und Schur. Als er einst zu Gerar weilte,',
        2: 'sprach Abraham von seinem Weibe Sara: "Sie ist meine Schwester." Da sandte der König von Gerar, Abimelech, hin und ließ Sara holen.',
        3: 'Gott aber kam im nächtlichen Traume zu Abimelech und sprach zu ihm: "Des Weibes wegen, das du geholt, mußt du sterben, ist sie doch eine Ehefrau."',
        4: 'Abimelech aber war ihr noch nicht genaht; so sprach er: "Herr, bringst du auch schuldlose Leute um?',
        5: 'Er hat doch selbst zu mir gesagt: \'Sie ist meine Schwester\' und auch sie hat gesagt: \'Er ist mein Bruder.\' In meines Herzens Einfalt und mit reinen Händen habe ich das getan."',
        6: 'Da sprach Gott zu ihm im Traume: "Auch ich weiß, daß du in deines Herzens Einfalt so gehandelt, und so bewahrte ich selbst dich davor, gegen mich zu sündigen; darum habe ich dir nicht zugelassen, sie zu berühren.',
        7: 'Gib aber jetzt dem Manne sein Weib heraus! Weil er ein Prophet ist, soll er für dich beten, daß du am Leben bleibst. Gibst du sie aber nicht heraus, so wisse, daß du sterben mußt, du samt all den Deinen!"',
        8: 'Da rief frühmorgens Abimelech alle seine Diener zusammen und erzählte ihnen all das, und die Männer erschraken sehr.',
        9: 'Dann ließ Abimelech Abraham rufen und sprach zu ihm: "Was hast du uns angetan? Womit habe ich gegen dich gefehlt, daß du so schwere Schuld über mich und über mein Gebiet gebracht hast? Was nimmermehr geschehen durfte, hast du mir angetan."',
        10: 'Dann sprach Abimelech zu Abraham: "Was ist dir eingefallen, daß du dies getan hast?"',
        11: 'Da sprach Abraham: "Ich habe eben gedacht: \'Gar keine Furcht vor Gott herrscht an diesem Ort; sie bringen mich meines Weibes wegen um.\'',
        12: 'Auch ist sie wirklich meine Schwester, meines Vaters Tochter, nur nicht meiner Mutter Tochter, und so ist sie mein Weib geworden.',
        13: 'Als mich die Himmlischen aus meines Vaters Hause auf die Irrfahrt schickten, sprach ich zu ihr. \'Tu mir dies zuliebe! Wohin wir kommen, sag von mir: Es ist mein Bruder.\'"',
        14: 'Da nahm Abimelech Schafe und Rinder, Sklaven und Mägde und gab sie Abraham; auch gab er ihm sein Weib Sara heraus.',
        15: 'Und Abimelech sprach: "Mein Land steht dir offen. Laß dich nieder, wo es dir beliebt!"',
        16: 'Zu Sara aber sprach er: "Ich schenke deinem Bruder tausend Silberstücke. Dies sei dir Ersatz für alles, was dir, deinen Knechten und Mägden widerfahren ist."',
        17: 'Abraham aber betete zu Gott, und Gott heilte Abimelech, sein Weib und seine Mägde, daß sie Geburten hatten;',
        18: 'denn der Herr hatte jeden Schoß in Abimelechs Hause wegen Sara, des Weibes Abrahams, verschlossen.',
    },
    21: {
        1: 'Der Herr aber hatte Sara heimgesucht, wie er verheißen. Und der Herr tat an Sara, wie er vorausgesagt hatte.',
        2: 'Und Sara war guter Hoffnung und gebar einen Sohn dem Abraham in seinem Greisenalter um die Zeit, die Gott vorausgesagt hatte.',
        3: 'Und Abraham nannte seinen neugeborenen Sohn, den ihm die Sara gebar, Isaak.',
        4: 'Und Abraham beschnitt seinen Sohn Isaak, als er acht Tage alt war, wie ihm Gott befohlen hatte.',
        5: 'Abraham aber war hundert Jahre alt, als ihm sein Sohn Isaak geboren ward.',
        6: 'Da sprach Sara: "Zum Scherze hat mich Gott gemacht. Wer davon hört, scherzt über mich."',
        7: 'Und sie sprach: "Wer hätte Abraham zugeflüstert: \'Sara stillt Kinder noch?\' Nun habe ich ihm doch noch einen Sohn in seinem Greisenalter geboren."',
        8: 'Und das Kind wuchs und wurde entwöhnt, und Abraham bereitete ein großes Mahl an dem Tag, an dem Isaak entwöhnt ward.',
        9: 'Sara aber sah den Sohn der Ägypterin Hagar, den sie Abraham geboren, wie er seinen Spott trieb.',
        10: 'Da sprach sie zu Abraham: "Jage diese Magd und ihren Sohn fort! Denn dieser Magd Sohn soll nicht mit Isaak, meinem Sohn, erben!"',
        11: 'Dies Wort aber betrübte Abraham heftig wegen seines Sohnes.',
        12: 'Doch Gott sprach zu Abraham: "Nicht um den Knaben sei\'s dir leid und nicht um deine Magd! In allem, was dir Sara sagt, höre auf ihre Stimme! Nur wer von Isaak stammt, trägt deines Stammes Namen.',
        13: 'Doch mache ich zu einem Volke auch den Sohn der Magd; auch er ist ja dein Sproß."',
        14: 'Da nahm Abraham am anderen Morgen früh Brot und einen Schlauch mit Wasser und gab es Hagar; das Kind legte er auf ihre Schultern und schickte sie fort. Da zog sie hin und verirrte sich in der Wüste Beerseba.',
        15: 'Als das Wasser im Schlauch zu Ende ging, ließ sie das Kind unter einem der Sträucher liegen,',
        16: 'ging fort und saß für sich, einen Bogenschuß weit; denn sie sprach: "Ich kann nicht ansehen, wie das Kind stirbt." So saß sie abseits, erhob ihre Stimme und weinte.',
        17: 'Gott aber hörte ihr Gebet um den Knaben, und Gottes Engel rief Hagar vom Himmel her und sprach zu ihr: "Was ist dir, Hagar? Fürchte dich nicht! Gott hat ja dein Gebet um den Knaben gehört, wo immer er ist.',
        18: 'Auf! Nimm den Knaben! Fasse durch ihn wieder Mut! Ich will ihn ja zu einem großen Volke machen."',
        19: 'Und Gott tat ihr die Augen auf, und sie erblickte einen Wasserquell. Da ging sie hin und füllte den Schlauch mit Wasser und gab dem Knaben zu trinken.',
        20: 'Und Gott war mit dem Knaben. Er wuchs heran und wohnte in der Wüste und war ein Meister mit dem Bogen.',
        21: 'Er wohnte in der Wüste Paran, und seine Mutter besorgte ihm ein Weib aus dem Ägypterlande.',
        22: 'In jener Zeit redeten Abimelech und sein Heerführer Pikol mit Abraham: "Gott ist mit dir in allem, was du tust.',
        23: 'Nun schwöre mir hier bei Gott, daß du weder mich noch meinen Schoß und Sproß schädigest, sondern Güte, wie ich an dir geübt, auch an mir üben willst, desgleichen an dem Lande, in dem du zu Gast weilst!"',
        24: 'Da sprach Abraham: "Ich schwöre es."',
        25: 'Abraham aber stellte Abimelech zur Rede wegen des Wasserbrunnens, den Abimelechs Knechte weggenommen hatten.',
        26: 'Abimelech aber sprach: "Ich weiß nicht, wer dies getan; du hast mir nichts gesagt, noch habe ich bis heute davon gehört."',
        27: 'Da nahm Abraham Schafe und Rinder und gab sie Abimelech, und sie schlossen einen Vertrag miteinander.',
        28: 'Abraham aber stellte die sieben Lämmer der Herde besonders.',
        29: 'Da sprach Abimelech zu Abraham: "Was sollen diese sieben Lämmer, die du besonders stellst?"',
        30: 'Er sprach: "Die sieben Lämmer mußt du von mir nehmen, damit sie mir als Zeugnis dienen, daß ich diesen Brunnen gegraben habe."',
        31: 'Diese Stätte heißt daher Beerseba; denn dort haben sie einander zugeschworen.',
        32: 'So schlossen sie einen Vertrag zu Beerseba. Alsdann brachen Abimelech und sein Heerführer Pikol auf und kehrten in das Philisterland zurück.',
        33: 'Er aber pflanzte eine Tamariske zu Beerseba und rief dort den Namen des Herrn an, eines ewigen Gottes.',
        34: 'Und Abraham weilte lange zu Gast im Philisterland.',
    },
    22: {
        1: 'Nach diesen Begebnissen war es; da versuchte Gott den Abraham. Er sprach zu ihm: "Abraham!" Er sprach: "Hier bin ich."',
        2: 'Da sprach er: "Nimm deinen einzigen Sohn, den du so liebst, den Isaak, und zieh ins Morialand und bring ihn zum Brandopfer dort dar, auf einem jener Berge, den ich dir bezeichnen werde!"',
        3: 'Da sattelte Abraham frühmorgens seinen Esel, nahm seine beiden Diener samt seinem Sohne Isaak mit, spaltete Holzscheite zum Brandopfer, brach auf und zog nach der Stätte, von der ihm Gott gesprochen.',
        4: 'Am dritten Tage erhob Abraham seine Augen; da sah er von weitem die Stätte.',
        5: 'Da sprach Abraham zu seinen Dienern: "Bleibt mit dem Esel hier! Ich aber und der Knabe wollen dorthin gehen, anzubeten. Wir kommen dann wieder zu euch."',
        6: 'Und Abraham nahm das Opferholz und legte es seinem Sohne Isaak auf; er aber nahm Feuer und Messer mit. So zogen sie beide zusammen dahin.',
        7: 'Da sprach Isaak zu seinem Vater Abraham; er sprach: "Mein Vater!" Er sprach: "Mein Sohn, hier bin ich." Er sprach: "Da ist Feuer und Holz. Aber wo ist das Schaf zum Opfer?"',
        8: 'Da sprach Abraham: "Gott ersieht sich schon das Schaf zum Opfer, mein Sohn." So zogen sie beide zusammen dahin.',
        9: 'Und sie kamen zu dem Ort, von dem ihm Gott gesprochen. Dort baute Abraham einen Altar und schichtete das Holz. Dann band er seinen Sohn Isaak und legte ihn auf den Altar auf das Holz.',
        10: 'Dann streckte Abraham seine Hand aus und griff nach dem Messer, um seinen Sohn zu schlachten.',
        11: 'Da rief ihm der Engel des Herrn vom Himmel her und sprach: "Abraham! Abraham!" Er sprach: "Hier bin ich."',
        12: 'Er sprach: "Leg deine Hand nicht an den Knaben! Tu ihm nichts! Jetzt weiß ich: Du bist gottesfürchtig; du verweigerst mir ja selbst deinen einzigen Sohn nicht."',
        13: 'Und Abraham erhob seine Augen und sah hin; da hatte sich hinter ihm ein Widder mit den Hörnern im Dickicht verfangen. Abraham ging hin, nahm den Widder und brachte ihn an seines Sohnes Statt zum Opfer dar.',
        14: 'Und Abraham nannte diesen Ort: "Der Herr sorgt", so wie man noch sagt: "Auf dem Berg des Herrn ist man versorgt."',
        15: 'Und des Herrn Engel rief Abraham ein zweitesmal vom Himmel her',
        16: 'und sprach: "Ich leiste bei mir selber einen Schwur" - ein Spruch des Herrn -: "Weil du dies getan und deinen einzigen Sohn mir nicht verweigert,',
        17: 'so gebe ich dir meinen Segen und mache deinen Stamm so zahlreich wie des Himmels Sterne und wie den Sand am Meeresufer. Dein Stamm soll seiner Feinde Tor erobern!',
        18: 'Der Erde Völker alle sollen sich mit deinem Stamme segnen zum Lohn dafür, daß du auf meine Stimme hast gehört."',
        19: 'Und Abraham kehrte zu seinen Dienern zurück; sie brachen auf und zogen miteinander nach Beerseba. Und Abraham blieb in Beerseba wohnen.',
        20: 'Nach diesen Begebnissen geschah es, daß man Abraham meldete: "Auch Milka hat deinem Bruder Nachor Söhne geboren:',
        21: 'Uz, seinen Erstgeborenen, und seinen Bruder Buz und Kemuel, den Vater Arams,',
        22: 'und Kesed, Chazo, Pildas, Jidlaph sowie Betuel."',
        23: 'Betuel aber hatte Rebekka gezeugt. Diese acht hatte Milka dem Nachor, Abrahams Bruder, geboren.',
        24: 'Er hatte auch ein Nebenweib namens Rëuma; sie gebar Tebach, Gacham, Tachas und Maaka.',
    },
    23: {
        1: 'Die Lebensjahre Saras betrugen 127 Jahre; das sind die Lebensjahre Saras.',
        2: 'Und Sara starb zu Kirjat Arba, das ist Hebron, im Lande Kanaan. Und Abraham kam, Sara zu beklagen und zu beweinen.',
        3: 'Dann erhob sich Abraham von dem Leichnam weg und sprach zu den Söhnen Chets also:',
        4: '"Als Gast und Beisaß bin ich bei euch. Gebt mir bei euch doch ein Erbgrab, daß ich meine Tote aus dem Hause bringe und begrabe!"',
        5: 'Und die Söhne Chets antworteten Abraham also:',
        6: '"Nein! Hör uns an, Herr! Ein Gottesfürst bist du in unserer Mitte. Begrabe deine Tote im besten unserer Gräber. Keiner von uns wird dir sein Grab verweigern, deine Tote darin zu bestatten."',
        7: 'Da erhob sich Abraham, neigte sich vor den Landeskindern, den Söhnen Chets',
        8: 'und redete also mit ihnen: "Ist es euch genehm, daß ich meine Tote aus dem Hause bringe und begrabe, so hört mich an! Legt Fürsprache für mich ein bei Ephron, Sochars Sohn,',
        9: 'daß er mir die Höhle der Makpela lasse, die ihm gehört und am Rande seines Feldes liegt! Um vollen Preis lasse er sie mir in eurer Mitte zum Erbbegräbnis!"',
        10: 'Ephron aber hatte einen Sitz unter den Söhnen Chets. So antwortete der Chittiter Ephron dem Abraham laut vor den Söhnen Chets, vor allen, die Zutritt zum Tore seiner Stadt hatten, also:',
        11: '"Nicht so, Herr! Hör mich an: Dieses Feld schenke ich dir; ich schenke dir auch die Höhle, die darauf ist. Vor meiner Volksgenossen Augen schenke ich sie dir. Begrabe deine Tote!"',
        12: 'Da neigte sich Abraham vor den Landeskindern',
        13: 'und sprach zu Ephron laut vor den Landeskindern also: "Ach, möchtest du mir Gehör schenken! Ich zahle den Preis des Feldes. Nimm ihn von mir an, daß ich dort meine Tote begraben kann!"',
        14: 'Da antwortete Ephron dem Abraham also:',
        15: '"Nicht doch, mein Herr! Hör mich an! Ein Feld! Vierhundert Silberringe, was hat dies unter uns zu sagen? Begrabe nur deine Tote!"',
        16: 'Und Abraham hörte auf Ephron. So wog Abraham dem Ephron den Preis dar, von dem er im Beisein der Söhne Chets gesprochen: vierhundert Silberringe Kaufsilber.',
        17: 'So ward Ephrons Feld, das in der Makpela gegenüber Mamre lag, das Feld samt der Höhle darin und allen Bäumen auf dem Feld und in seinem ganzen Umkreise',
        18: 'rechtskräftig Abrahams Eigentum im Beisein der Söhne Chets, all derer, die Zutritt zum Tore seiner Stadt hatten.',
        19: 'Danach begrub Abraham sein Weib Sara in der Höhle des Feldes der Makpela gegenüber Mamre, das ist Hebron, im Lande Kanaan.',
        20: 'So ward das Feld mit der Höhle darin rechtskräftig des Abraham Erbbegräbnis unter Zustimmung der Söhne Chets.',
    },
    24: {
        1: 'Abraham aber war alt und hochbetagt geworden, und der Herr hatte Abraham in allem gesegnet.',
        2: 'Da sprach Abraham zu seinem Knecht, seinem Hausältesten, der über all seinem Eigentume waltete: "Lege deine Hand unter meine Lende!',
        3: 'Ich lasse dich schwören beim Herrn, dem Gott des Himmels und der Erde, daß du meinem Sohn kein Weib freiest von den Töchtern der Kanaaniter, in deren Mitte ich wohne.',
        4: 'Nein! Du ziehst in mein Land und zu meiner Verwandtschaft und freist für Isaak, meinen Sohn, ein Weib."',
        5: 'Da sprach der Knecht zu ihm: "Wenn mir aber das Weib in dies Land nicht folgen will? Soll ich dann deinen Sohn in jenes Land, aus dem du gezogen, wieder zurückbringen?"',
        6: 'Da sprach Abraham zu ihm: "Hüte dich, meinen Sohn dorthin zurückzubringen!',
        7: "Der Herr, des Himmels Gott, der mich aus meinem Vaterhaus und meinem Heimatland geholt und der zu mir geredet und mir feierlich geschworen: 'Ich gebe deinem Stamme dies Land', derselbe sendet seinen Engel vor dir her, daß du ein Weib dorther für meinen Sohn freiest.",
        8: 'Und sollte dir das Weib nicht folgen, dann bist du dieses Eides ledig. Doch keinesfalls darfst du meinen Sohn dorthin verbringen."',
        9: 'Da legte der Knecht seine Hand unter die Lende seines Herrn Abraham und schwur ihm auf dies Wort.',
        10: 'Dann nahm der Knecht zehn Kamele von seines Herrn Kamelen und schickte sich zur Abreise an, im Besitz der Vollmacht über das ganze Vermögen seines Herrn. So brach er auf und zog nach Aram Naharaim, zu der Stadt Nachors.',
        11: 'Da ließ er die Kamele draußen vor der Stadt am Brunnen lagern, zur Abendzeit, um die Zeit, wann die Weiber zum Wasserholen herauskommen.',
        12: 'Er sprach: "Herr, du Gott Abrahams, meines Herrn! Laß es mir heute glücken und zeige dich gnädig gegen Abraham, meinen Herrn!',
        13: 'Hier stehe ich am Wasserquell; der Stadtleute Töchter kommen jetzt zum Wasserschöpfen.',
        14: 'Das Mädchen nun sei es, dem ich sage: \'Neige deinen Krug, auf daß ich trinke!\' und das antwortet: \'Trink! Und auch deine Kamele will ich tränken.\' Sie hast du für deinen Knecht Isaak bestimmt, und an ihr erkenne ich, daß du Huld an meinem Herrn geübt."',
        15: 'Noch hatte er nicht ausgeredet, da kam Rebekka heraus, die dem Betuel, dem Sohne Milkas, des Weibes Nachors, Abrahams Bruders, geboren war, mit ihrem Krug auf der Schulter.',
        16: 'Das Mädchen war überaus schön, eine Jungfrau, die noch keinen Mann erkannt hatte. Sie stieg zum Quell hinab, füllte ihren Krug und stieg heraus.',
        17: 'Da lief ihr der Knecht entgegen und sprach: "Laß mich aus deinem Krug ein wenig Wasser schlürfen!"',
        18: 'Sie sprach:"Trink, mein Herr!", und geschwind ließ sie den Krug auf die Hand nieder und gab ihm zu trinken.',
        19: 'Als sie ihn hatte genug trinken lassen, sprach sie: "Ich will auch deinen Kamelen schöpfen, bis sie sich satt getrunken haben."',
        20: 'Und eilends goß sie ihren Krug in die Tränkrinne, lief wieder zum Brunnen, Wasser zu schöpfen, und schöpfte so für alle seine Kamele.',
        21: 'Der Mann aber sah ihr zu, gespannt zu erfahren, ob der Herr ihm seine Reise habe glücken lassen oder nicht.',
        22: 'Wie sich nun die Kamele sattgetrunken hatten, nahm der Mann einen goldenen Stirnring, einen halben Ring schwer, und legte zwei Armspangen an die Arme, zehn Ringe Goldes schwer.',
        23: 'Und er sprach: "Wessen Tochter bist du? Sag mir\'s doch! Ist wohl Platz in deines Vaters Haus für uns zum Übemachten?"',
        24: 'Sie sprach zu ihm: "Ich bin die Tochter des Betuel, den Milka dem Nachor einst geboren hat."',
        25: 'Dann sprach sie zu ihm: "Stroh und Futter haben wir in Menge sowie Platz zum Übernachten."',
        26: 'Da neigte sich der Mann, warf sich vor dem Herrn nieder und sprach:',
        27: '"Gepriesen sei der Herr, meines Herrn Abraham Gott, der seine Huld und Treue meinem Herrn nicht vorenthalten! Ich bin da auf dem rechten Wege; mich hat der Herr zum Haus der Brüder meines Herrn geführt."',
        28: 'Das Mädchen aber lief und berichtete im Hause ihrer Mutter dies Begebnis.',
        29: 'Rebekka aber hatte einen Bruder namens Laban; Laban lief nun zu dem Mann an den Quell hinaus.',
        30: 'Kaum hatte er aber den Stirnring und die Spangen an den Armen seiner Schwester gesehen und seiner Schwester Rebekka Bericht vernommen: "So hat der Mann zu mir gesprochen", kam er schon zu dem Manne, dieser aber stand noch bei den Kamelen an dem Quell.',
        31: 'Er sprach: "Komm, du Gesegneter des Herrn! Warum stehst du da draußen? Habe ich doch das Haus aufgeräumt und Platz für die Kamele gemacht."',
        32: 'So brachte der Mann die Kamele ins Haus und schirrte sie ab; dann brachte jener Stroh und Futter für die Kamele und Wasser zum Füßewaschen für ihn und die Männer bei ihm.',
        33: 'Dann setzte man ihm zu essen vor; er aber sprach: "Ich esse nicht eher, als bis ich meine Sache vorgebracht." Sie sagten: "So rede!"',
        34: 'Er sprach: "Ich bin Abrahams Knecht.',
        35: 'Reich gesegnet hat der Herr meinen Herrn, daß er zu großem Wohlstande gelangte. Er hat ihm Schafe und Rinder, Silber und Gold geschenkt, Sklaven, Mägde, Kamele und Esel.',
        36: 'Nun gebar auch Sara, meines Herrn Weib, meinem Herrn einen Sohn noch nach ihrem Altern. Ihm übergab er seinen ganzen Besitz.',
        37: "Nun ließ mich mein Herr also schwören: 'Du darfst für meinen Sohn kein Weib freien von den Töchtern der Kanaaniter, in deren Land ich wohne.",
        38: "Nein! Du ziehst zu meines Vaters Haus und zu meiner Sippe und freist meinem Sohne ein Weib.'",
        39: "Da sprach ich zu meinem Herrn: 'Wenn aber das Weib mir nicht folgen will?'",
        40: "Da sagte er zu mir: 'Der Herr, vor dessen Antlitz ich gewandelt, wird seinen Engel mit dir senden; dann läßt er deine Reise wohl gelingen, und du freist meinem Sohne ein Weib aus meiner Sippe, und zwar aus meines Vaters Haus.",
        41: "Nur dann sollst du meines Eides ledig sein. Kommst du zu meiner Sippe und geben sie dir nichts, dann bist du meines Eides ledig.'",
        42: 'Nun kam ich heute zum Quell; da sprach ich: Herr, Gott Abrahams, meines Herrn! Läßt du mir meine Reise, die ich unternommen, wohl gelingen?',
        43: "Hier stehe ich am Wasserquell. Nun sei es das junge Mädchen, das zum Schöpfen kommt und das ich anrede: 'Laß mich ein wenig Wasser aus deinem Kruge trinken!'",
        44: "und das mir sagt: 'Trink du selber! Und auch den Kamelen will ich schöpfen!' Sie ist das Weib, das der Herr dem Sohne meines Herrn bestimmt hat.",
        45: "Kaum hatte ich so bei mir geschlossen, da kam Rebekka heraus, den Krug auf der Schulter, stieg zum Quell hinab und schöpfte. Ich sprach zu ihr: 'Gib mir zu trinken!'",
        46: "Da ließ sie eilends ihren Krug herab und sprach: 'Da! Trink! Und auch deine Kamele will ich tränken.' Da trank ich, und da tränkte sie auch die Kamele.",
        47: "Nun fragte ich sie und sprach: 'Wessen Tochter bist du?' Sie sprach: 'Die Tochter des Nachorsohnes Betuel, den jenem Milka einst geboren.' Da legte ich den Ring ihr an die Stirn und die Spangen an die Arme.",
        48: 'Alsdann verneigte ich mich, warf mich vor dem Herrn nieder und pries den Herrn, meines Herrn Abraham Gott, der mich auf rechten Weg geführt, die Tochter eines Bruders meines Herrn für seinen Sohn zu freien.',
        49: 'Wollt ihr nun Liebe und Treue meinem Herrn erweisen, so sagt es mir! Wo nicht, so sagt\'s mir auch, daß ich mich zur Rechten oder Linken wende!"',
        50: 'Da antworteten Laban und Betuel und sprachen: "Das kommt vom Herrn; wir können weder gut noch übel dich bescheiden.',
        51: 'Rebekka steht dir zur Verfügung. Nimm sie und geh, daß sie dem Sohne deines Herrn zum Weibe werde, wie der Herr gesagt!"',
        52: 'Als Abrahams Knecht ihre Worte hörte, warf er sich vor dem Herrn auf die Erde nieder.',
        53: 'Dann zog der Knecht silberne und goldene Geräte und Gewänder hervor und schenkte sie Rebekka; ihrem Bruder und ihrer Mutter gab er Kleinodien.',
        54: 'Sie aßen nun und tranken, er und die Männer bei ihm und blieben über Nacht. Am anderen Morgen, als sie aufstanden, sprach er: "Entlaßt mich zu meinem Herrn!"',
        55: 'Da sprachen ihr Bruder und ihre Mutter: "Laß noch das Mädchen einige Tage oder doch wenigstens zehn bei uns! Dann mag sie ziehen."',
        56: 'Da sprach er zu ihnen: "Haltet mich nicht auf! Der Herr hat meine Reise glücken lassen. Entlasset mich, daß ich zu meinem Herrn ziehe!"',
        57: 'Sie sprachen: "Wir wollen das Mädchen rufen und sie selbst befragen."',
        58: 'Da riefen sie Rebekka und sprachen zu ihr: "Willst du mit diesem Manne ziehen?" Sie sagte: "Ja!"',
        59: 'Da ließen sie ihre Schwester Rebekka mit ihrer Amme ziehen, ebenso den Knecht Abrahams mit seinen Leuten.',
        60: 'Und sie segneten Rebekka und sprachen zu ihr: "Unsere Schwester, werde du zu ungezählten Tausenden! Mögen deine Nachkommen das Tor ihrer Hasser besetzen!"',
        61: 'Dann brach Rebekka mit ihren Mägden auf; sie ritten auf den Kamelen und folgten dem Manne. So nahm der Knecht Rebekka und zog von dannen.',
        62: 'Isaak aber war vom Brunnen Lachaj Roi hergekommen. Er wohnte nunmehr im Südland.',
        63: 'Nun ging Isaak zum Betrachten bei Abendanbruch aufs Feld hinaus. Wie er aber die Augen erhob, kamen Kamele daher.',
        64: 'Auch Rebekka erhob ihre Augen und erblickte Isaak. Da beugte sie sich vom Kamele herab,',
        65: 'und sprach zu dem Knechte: "Wer ist der Mann da drüben, der uns auf dem Felde entgegenkommt?" Der Knecht sprach: "Das ist mein Herr." Da nahm sie den Schleier und verhüllte sich.',
        66: 'Der Knecht aber erzählte dem Isaak alles, was er ausgerichtet hatte.',
        67: 'Da führte Isaak sie in seiner Mutter Sara Zelt. Er freite Rebekka, und sie ward sein Weib, und er gewann sie lieb. So tröstete sich Isaak über seiner Mutter Verlust.',
    },
    25: {
        1: 'Abraham aber nahm nochmals ein Weib, namens Ketura.',
        2: 'Und sie gebar ihm Zimran, Joksan, Medan, Midian, Isbak und Suach.',
        3: 'Joksan aber hatte Seba und Dedan gezeugt, und Dedans Söhne wurden zu Asuritern, Letusitern und Lëumitern.',
        4: 'Und Midians Söhne sind Epha, Epher, Chanok, Abida und Eldaa; all dies sind Söhne der Ketura.',
        5: 'Dann übergab Abraham all sein Eigentum dem Isaak.',
        6: 'Den Nebenweibersöhnen aber, die Abraham besaß, hatte Abraham Geschenke gegeben; er ließ sie zugunsten seines Sohnes Isaak, noch bei seinen Lebzeiten, ostwärts ins Ostland ziehen.',
        7: 'Dies ist der Lebensjahre Abrahams Dauer, die er durchlebte, 175 Jahre.',
        8: 'Und Abraham verschied und starb in schönem Alter, alt und lebenssatt, und ward zu seinen Stammesgenossen versammelt.',
        9: 'Ihn begruben seine Söhne Isaak und Ismael in der Höhle der Makpela, auf des Chittiters Ephrons, des Socharsohnes, Feld, Mamre gegenüber,',
        10: 'auf dem Feld, das Abraham von Chets Söhnen gekauft. Dort waren Abraham und sein Weib Sara begraben worden.',
        11: 'Nach Abrahams Tode segnete Gott seinen Sohn Isaak; Isaak aber wohnte bei dem Brunnen Lachaj Roi.',
        12: 'Dies ist die Geschlechterfolge des Abrahamsohnes Ismael den die Ägypterin Hagar, Saras Magd, dem Abraham geboren hat.',
        13: 'Dies sind die Namen der Söhne Ismaels nach ihren Namen und ihrem Stammbaum: Ismaels Erstgeborener Nebajot, Kedar, Adbeel, Mibsam,',
        14: 'Misma, Duma, Massa,',
        15: 'Chadad, Tema, Jetur, Naphis und Kedma.',
        16: 'Dies sind die Söhne Ismaels und dies ihre Namen nach ihren Gehöften und Zeltlagern, zwölf Fürsten nach ihren Stammverbänden.',
        17: 'Und dies war Ismaels Lebensdauer: 137 Jahre; da verschied er. Er starb und ward zu seinen Stammesgenossen versammelt.',
        18: 'Sie lagerten von Chavila bis Schur, östlich von Ägypten und bis gen Assur hin. Er fiel zu Lebzeiten all seiner Brüder.',
        19: 'Dies ist die Geschlechterfolge des Abrahamsohnes Isaak: Abraham hat Isaak gezeugt.',
        20: 'Isaak aber war 40 Jahre alt, als er sich Rebekka, des Aramäers Betuel Tochter, aus Paddan Aram, die Schwester des Aramäers Laban, zum Weibe nahm.',
        21: 'Isaak aber flehte zum Herrn für sein Weib, weil es unfruchtbar war. Und der Herr ließ sich von ihm erbitten, und so ward sein Weib Rebekka guter Hoffnung.',
        22: 'Aber die Kinder rannten einander in ihrem Leibe an. Da sprach sie: "Steht\'s so, warum trifft es gerade mich?" Und sie ging den Herrn befragen.',
        23: 'Da sprach der Herr zu ihr: "Zwei Völker sind in deinem Leibe, und zwei Stämme scheiden sich aus deinem Schoße. Ein Stamm beherrscht den anderen; lang wird der jüngere dienstbar sein."',
        24: 'Als ihre Zeit kam zum Gebären, da waren Zwillinge in ihrem Leib.',
        25: 'Der erste, rötlich, kam wie ein haariger Mantel hervor, und man nannte ihn Esau.',
        26: 'Danach kam sein Bruder hervor, und er hielt mit seiner Hand die Ferse Esaus. So nannte man ihn Jakob. Isaak aber war 60 Jahre alt, als sie geboren wurden.',
        27: 'Die Knaben wuchsen nun heran. Esau ward ein tüchtiger Jäger, ein Mann der Steppe; Jakob aber war ein schlichter Mann, der bei den Zelten blieb.',
        28: 'Isaak aber liebte Esau; denn er sprach gern von der Jagd. Rebekka aber liebte Jakob.',
        29: 'Einst kochte Jakob ein Gericht; da kam Esau ganz erschöpft aus der Steppe.',
        30: 'Und Esau sprach zu Jakob: "Laß mich doch eilends von dieser roten Zukost genießen! Denn ich bin erschöpft." Deshalb nannte man ihn Edom.',
        31: 'Da sprach Jakob: "Verkaufe mir zuvor dein Erstgeburtsrecht!"',
        32: 'Esau sprach: "Ich muß sonst sterben. Was nützt mir da die Erstgeburt?"',
        33: 'Jakob sprach: "Schwöre mir zuvor!" Da schwur er ihm und verkaufte sein Erstgeburtsrecht an Jakob.',
        34: 'Jakob aber gab Esau Brot und das Linsengericht. Da aß er und trank, stand auf und ging von hinnen. So verscherzte Esau das Erstgeburtsrecht.',
    },
    26: {
        1: 'Nun kam eine Hungersnot ins Land, eine andere als jene frühere zu Abrahams Zeiten. So zog Isaak zum Philisterkönig Abimelech nach Gerar.',
        2: 'Da erschien ihm der Herr und sprach: "Zieh nicht nach Ägypten hinab! Bleib in dem Land, das ich dir anweise!',
        3: 'Bleib in diesem Lande zu Gast! Und ich will mit dir sein und dich segnen; denn dir und deinem Stamm gebe ich all diese Lande; dann erfülle ich den Schwur, den ich deinem Vater Abraham geschworen habe.',
        4: 'Dann mehre ich deinen Stamm wie des Himmels Sterne und gebe deinem Stamm all diese Lande. In deinem Stamm sollen sich der Erde Völker alle segnen,',
        5: 'zum Lohn dafür, daß Abraham auf meine Stimme gehört hat; er befolgte mein Gebot, meine Satzungen, Gesetze und Vorschriften."',
        6: 'So blieb Isaak zu Gerar.',
        7: 'Als aber die Leute des Ortes nach seinem Weibe fragten, sprach er: "Sie ist nur meine Schwester"; denn er fürchtete sich zu sagen: "Sie ist mein Weib"; sonst könnten mich die Leute des Ortes umbringen; denn Rebekka ist schön.',
        8: 'Als er längere Zeit dort gewesen war, geschah es, daß der Philisterkönig Abimelech zum Fenster hinausschaute. Da sah er Isaak mit seinem Weib Rebekka kosen.',
        9: 'Da rief Abimelech den Isaak herbei und sprach: "Also dein Weib ist sie! Wie hast du sagen können: \'Sie ist meine Schwester!\'?" Da sprach Isaak zu ihm: "Ich habe gedacht, ich müßte ihretwegen sterben."',
        10: 'Abimelech sprach: "Was hast du uns da getan? Wie leicht hätte einer aus dem Volke deinem Weibe beiwohnen können. Dann hättest du Schuld über uns gebracht."',
        11: 'Da gebot Abimelech allem Volke: "Wer diesen Mann und sein Weib berührt, soll des Todes sterben."',
        12: 'Isaak aber säte in jenem Lande. Und er erntete in jenem Jahre hundert Speicher voll. So segnete der Herr ihn.',
        13: 'Und so ward der Mann reich und immer reicher, bis er schwer reich geworden war.',
        14: 'Er besaß Schaf- und Rinderherden und viel Arbeitsvieh. Da beneideten ihn die Philister.',
        15: 'Und die Philister verschütteten alle Brunnen, die seines Vaters Knechte bei seines Vaters Abraham Lebzeiten gegraben, und füllten sie mit Erde.',
        16: 'Und Abimelech sprach zu Isaak: "Zieh fort von uns! Du bist ja mächtiger geworden, als uns lieb."',
        17: 'Und Isaak zog von da weg und lagerte sich im Tale von Gerar und wohnte da.',
        18: 'Da grub Isaak die Wasserbrunnen wieder auf, die man in seines Vaters Abrahams Tagen gegraben und die nach Abrahams Tod die Philister verschüttet hatten, und benannte sie wieder mit den Namen, die ihnen sein Vater gegeben.',
        19: 'Auch gruben Isaaks Knechte im Tale nach und fanden dort einen Brunnen fließenden Wassers.',
        20: 'Die Hirten von Gerar aber stritten mit Isaaks Knechten und sprachen: "Unser ist das Wasser." Da nannte man den Brunnen Esek, weil sie dort gestritten hatten.',
        21: 'Dann bohrten sie einen anderen Brunnen; aber auch um diesen stritten sie, und man nannte ihn Sitna.',
        22: 'Er zog von dort weiter und grub einen anderen Brunnen. Um diesen stritten sie nicht mehr. Und er nannte ihn Rechobot und sprach: "Nun hat der Herr uns freien Raum geschaffen, und wir können im Lande sorglos sein."',
        23: 'Von dort zog er nach Beerseba hinauf.',
        24: 'Und der Herr erschien ihm in selbiger Nacht und sprach: "Ich bin der Gott deines Vaters Abraham. Fürchte dich nicht! Ich bin mit dir. Ich segne dich und mehre deinen Stamm um meines Dieners Abraham Willen."',
        25: 'Und er erbaute dort einen Altar und rief den Namen des Herrn an. Er schlug auch hier sein Zelt auf. Und Isaaks Knechte gruben dort einen Brunnen.',
        26: 'Da kam Abimelech zu ihm aus Gerar, mit seinem Vertrauten Achuzat und seinem Heerführer Pikol.',
        27: 'Da sprach Isaak zu ihnen: "Warum kommt ihr zu mir? Ihr hasset mich doch und jagtet mich von euch fort?"',
        28: 'Sie sprachen: "Wir haben gesehen, daß der Herr mit dir ist. Da sagten wir: Zwischen uns und dir sei ein Eid! Wir wollen einen Bund mit dir schließen,',
        29: 'daß du uns kein Übel tust, wie wir dich nicht angetastet, sondern dir bloß Gutes getan; wir entließen dich doch in Frieden. Du bist ja der Gesegnete des Herrn."',
        30: 'Da gab er ihnen ein Mahl, und sie aßen und tranken.',
        31: 'Frühmorgens schwuren sie einander zu. Dann verabschiedete sie Isaak, und sie gingen von ihm in Frieden.',
        32: 'Am selben Tage aber kamen Isaaks Knechte und machten ihm Meldung über den Brunnen, den sie gegraben; sie sagten zu ihm: "Wir haben Wasser gefunden."',
        33: 'Da nannte er ihn Siba; daher heißt die Stadt bis auf diesen Tag Beerseba.',
        34: 'Als Esau 40 Jahre alt ward, heiratete er des Chittiters Beeri Tochter Judith, ebenso des Chittiters Elon Tochter Basemat.',
        35: 'Sie waren ein schwerer Kummer für Isaak und Rebekka.',
    },
    27: {
        1: 'Als Isaak nun alt geworden und seine Augen erblindet waren, rief er seinen älteren Sohn Esau und sprach zu ihm: "Mein Sohn!" Der sprach zu ihm: "Hier bin ich."',
        2: 'Da sprach er: "Ich bin jetzt alt geworden und kann täglich sterben.',
        3: 'Nimm nun dein Jagdgerät, dein Wehrgehänge und deinen Bogen! Gehe aufs Feld und jage mir ein Wild!',
        4: 'Dann bereite mir Leckerbissen, wie ich sie liebe, und bringe sie zum Essen, auf daß dich meine Seele segne, bevor ich sterbe!"',
        5: 'Rebekka aber hatte gelauscht, wie Isaak mit seinem Sohne Esau sprach. Esau ging nun aufs Feld, Wild zum Vorsetzen zu jagen.',
        6: 'Da sprach Rebekka zu ihrem Sohne Jakob also: "Ich habe eben gehört, wie mit deinem Bruder Esau dein Vater redete und sprach:',
        7: "'Hol mir ein Wild und bereite mir Leckerbissen zum Essen! Dann segne ich dich mit des Herrn Zustimmung vor meinem Tode.'",
        8: 'Nun, mein Sohn, folg meinem Rat, was ich dich heiße!',
        9: "Geh zum Kleinvieh! Hol mir von dort zwei schöne Ziegenböckchen, daß ich sie für deinen Vater zu Leckerbissen bereite, wie er's liebt!",
        10: 'Dann bringst du sie deinem Vater zum Essen, auf daß er dich segne vor seinem Tode."',
        11: 'Da sprach Jakob zu seiner Mutter Rebekka: "Aber mein Bruder Esau ist sehr stark behaart, indes ich glatt bin.',
        12: 'Vielleicht betastet mich mein Vater; dann stehe ich vor ihm als Possenreißer da und bringe über mich nur Fluch, nicht Segen."',
        13: 'Da sprach seine Mutter zu ihm: "Auf mich falle die Verfluchung, die dir gilt, mein Sohn! Folge meinem Rat! Geh hin und hol es mir!"',
        14: 'Da ging er, holte und brachte es seiner Mutter, und seine Mutter bereitete Leckerbissen, wie sein Vater sie liebte.',
        15: 'Dann holte Rebekka ihres ältesten Sohnes Esau Kleider, die sie im Hause drinnen hatte, und zog sie ihrem jüngeren Sohne Jakob an.',
        16: 'Die Ziegenböckchenfelle aber hatte sie um seine Arme und seinen glatten Hals gelegt.',
        17: "Dann gab sie die Leckerbissen samt dem Brot, wie sie's bereitet hatte, ihrem Sohne Jakob in die Hand.",
        18: 'So kam er zu seinem Vater und sprach: "Mein Vater!" Er antwortete: "Hier bin ich. Wer bist du, mein Sohn?"',
        19: 'Da sprach Jakob zu seinem Vater: "Ich bin dein Erstgeborener, Esau. Ich habe getan, wie du mir gesagt. Auf! Iß von meinem Wildbret, auf daß mich deine Seele segne!"',
        20: 'Da sprach Isaak zu seinem Sohn: "Wie hast du\'s, mein Sohn, so schnell gefunden?" Er sprach: "Der Herr, dein Gott, hat es mir in den Weg laufen lassen."',
        21: 'Da sprach Isaak zu Jakob: "Tritt näher, mein Sohn, daß ich dich betaste! Bist du wirklich mein Sohn Esau? Bist du\'s nicht?"',
        22: 'Da trat Jakob näher zu seinem Vater Isaak. Er betastete ihn und sprach: "Die Stimme ist zwar Jakobs Stimme; die Arme aber sind Esaus Arme."',
        23: 'Und er erkannte ihn nicht; denn seine Arme waren wie die seines Bruders Esau behaart. So gab er ihm den Segen.',
        24: 'Er sprach: "Du bist also Esau, mein Sohn?" Er sprach: "Ja."',
        25: 'Da sprach er: "So bring\'s mir her, daß ich von meines Sohnes Wildbret esse, damit dich meine Seele segne!" Da brachte er es ihm, und er aß; dann brachte er ihm Wein, und er trank.',
        26: 'Nun sprach sein Vater Isaak zu ihm: "Tritt näher und küsse mich, mein Sohn!"',
        27: 'Da trat er näher und küßte ihn. Da roch er den Duft seiner Kleider, segnete ihn und sprach: "Wahrhaftig, meines Sohnes Duft ist wie der Duft des Feldes, das der Herr gesegnet.',
        28: 'Dir gebe Gott vom Himmelstau und von der Erde besten Früchten, des Kornes und des Weins die Fülle!',
        29: 'Dir sollen Völker dienen und Stämme sich vor dir verneigen! Sei Herrscher aber deine Brüder! Die Söhne deiner Mutter sollen sich vor dir verneigen! Wer dich verflucht, der sei verflucht! Und wer dich segnet, sei gesegnet!"',
        30: 'Wie aber Isaak den Segen über Jakob beendet und Jakob kaum seinen Vater Isaak verlassen, kam sein Bruder Esau von seiner Jagd.',
        31: 'Er bereitete gleichfalls Leckerbissen und brachte sie seinem Vater. Er sprach zu seinem Vater: "Mein Vater richte sich auf und esse von seines Sohnes Wildbret auf daß deine Seele mich segne!"',
        32: 'Da sprach sein Vater Isaak zu ihm: "Wer bist du?" Er sprach: "Ich bin dein Sohn, dein Erstgeborener, Esau."',
        33: 'Da erschrak Isaak über alle Maßen und sprach: "Wer in aller Welt ist der gewesen, der ein erjagtes Wild mir brachte, daß ich gehörig aß, bevor du kamst? Ihn segnete ich, und gesegnet wird er bleiben."',
        34: 'Wie Esau die Worte seines Vaters vernahm, schrie er überlaut und bitterlich und sprach zu seinem Vater: "Mein Vater, segne auch mich!"',
        35: 'Er sprach: "Dein Bruder ist mit List gekommen, und so nahm er dir deinen Segen."',
        36: 'Da sprach er: "Heißt man ihn nicht Jakob? Schon zum zweitenmal betrog er mich. Mein Erstgeburtsrecht hat er genommen; jetzt nimmt er mir auch den Segen." Dann sprach er: "Hast du mir keinen Segen aufbewahrt?"',
        37: 'Darauf erwiderte Isaak und sprach zu Esau: "Ich habe ihn zum Herrn über dich gesetzt. All seine Brüder habe ich ihm zu Knechten gegeben und ihn mit Korn und Most belehnt. Was in aller Welt kann ich dir tun, mein Sohn?"',
        38: 'Da sprach Esau zu seinem Vater: "Hast du nur den einen Segen, mein Vater? Mein Vater, segne doch auch mich!" und Esau fing laut zu weinen an.',
        39: 'Darauf hub sein Vater Isaak an und sprach zu ihm: "Fern von der Erde edlen Frucht wird dein Wohnsitz sein, und fern vom Tau des Himmels droben.',
        40: 'Von deinem Schwerte wirst du leben und deinem Bruder dienstbar sein, nur wenn du heimatlos umherschweifest, dann hältst du deinem Nacken fern sein Joch."',
        41: 'So ward Esau dem Jakob feind wegen des Segens, den ihm sein Vater gegeben. Und Esau dachte bei sich: "Kommen die Trauertage um meinen Vater, dann töte ich meinen Bruder Jakob."',
        42: 'Der Rebekka verriet sich aber das Vorhaben ihres älteren Sohnes Esau. So sandte sie hin, ließ ihren jüngeren Sohn Jakob rufen und sprach zu ihm: "Siehe, dein Bruder Esau sinnt auf Rache gegen dich und will dich töten.',
        43: 'So folge meinem Rat, mein Sohn! Brich auf und mach, daß du geschwind zu meinem Bruder Laban nach Charan kommst!',
        44: 'Dann bleibe eine Zeit bei ihm, bis sich deines Bruders Groll legt!',
        45: 'Läßt dann deines Bruders Zorn von dir ab und vergißt er, was du ihm getan, dann sende ich und lasse dich von dort holen. Warum soll ich euch beide an einem Tag verlieren?"',
        46: 'Und Rebekka sprach zu Isaak: "Ich bin des Lebens überdrüssig der Töchter Chets wegen. 47 Holt sich auch Jakob ein Weib von den Töchtern Chets, wie diese da aus des Landes Töchtern, wozu lebte ich noch?"',
    },
    28: {
        1: 'Da rief Isaak den Jakob, segnete ihn, beschied ihn und sprach zu ihm: "Du darfst kein Weib aus Kanaans Töchtern freien!',
        2: 'Mach dich auf und zieh nach Paddan Aram, zum Haus der Betuel, des Vaters deiner Mutter, und freie dir dort ein Weib, eine der Töchter Labans, deines Mutterbruders!',
        3: 'Gott, der Allmächtige, segne dich, mache dich fruchtbar und mehre dich, daß du zu einer Menge Völker werdest!',
        4: 'Er verleihe dir Abrahams Segen, dir und deinem Stamme nach dir, daß du deiner Pilgerschaft Land zu eigen bekommst, das Gott dem Abraham verliehen!"',
        5: 'So entließ Isaak den Jakob, und er zog nach Paddan Aram zu Betuels Sohn Laban, dem Aramäer, dem Bruder der Rebekka, der Mutter Jakobs und Esaus.',
        6: "Esau aber hatte bemerkt, daß Isaak den Jakob gesegnet und ihn nach Paddan Aram gesandt, sich dort ein Weib zu holen, und daß er ihn segnete und so beschied: 'Du darfst kein Weib aus Kanaans Töchtern nehmen',",
        7: 'und daß Jakob auf seinen Vater und seine Mutter hörte und nach Paddan Aram ging.',
        8: 'Da merkte Esau, daß Kanaans Töchter seinem Vater Isaak mißfielen.',
        9: 'So ging Esau zu Ismael und nahm Machalat, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajots, zu seinen Weibern hin sich zum Weibe.',
        10: 'Jakob aber zog von Beerseba aus und wanderte nach Charan.',
        11: 'Und er kam an eine gewisse Stätte und übernachtete hier, weil die Sonne unterging. Er nahm einen von den Steinen der Stätte und machte ein Lager für sein Haupt und legte sich an dieser Stätte schlafen.',
        12: 'Da träumte ihm: Auf der Erde stand eine Treppe, deren Spitze bis zum Himmel reichte, und darauf stiegen die Engel Gottes auf und ab.',
        13: 'Da stand auch der Herr vor ihn, und sprach: "Ich bin der Herr, der Schutzgott deines Vaters Abraham und Isaaks; das Land, auf dem du ruhst, das gebe ich dir und deinem Stamme.',
        14: 'Dann wird dein Stamm dem Staub der Erde gleich; nach Westen, Osten, Norden, Süden breitest du dich aus. Dann segnen sich in dir der Erde Geschlechter alle, sowie in deinem Stamme.',
        15: 'Fürwahr, ich bin mit dir und hüte dich allüberall, wohin du gehst. Dann bringe ich dich auch zu diesem Boden wieder. Denn ich verlasse nimmer dich, bis ich vollbracht, was ich dir jetzt verheißen."',
        16: 'Da erwachte Jakob aus seinem Schlafe und sprach: "Wahrlich, der Herr ist an dieser Stätte, und ich wußte es nicht."',
        17: 'Und er erschauerte und sprach: "Wie schauervoll ist diese Stätte! Hier ist nichts anderes als Gottes Haus, und jenes ist die Himmelspforte."',
        18: 'Frühmorgens nahm Jakob den Stein, den er zum Kopfpolster gemacht, stellte ihn als Malstein auf und goß Öl oben darauf.',
        19: 'Und er nannte jenen Ort Betel; vorher aber hieß die Stadt Luz.',
        20: 'Und Jakob machte ein Gelübde und sprach: "Ist Gott mit mir und behütet er mich auf dem Wege, den ich gehen muß, und gibt er mir Brot zur Nahrung und Kleider zur Bedeckung',
        21: 'und kehre ich heil zu meines Vaters Haus heim, dann ist der Herr mir zum Schutzgott,',
        22: 'und dieser Stein, den ich als Malstein aufgestellt, wird ein Gotteshaus, und alles, was Du mir geben wirst, will ich Dir getreulich verzehnten."',
    },
    29: {
        1: 'Da machte sich Jakob auf den Weg und wanderte ins Land der Söhne des Ostens.',
        2: 'Er schaute aus; da war im Feld ein Brunnen, und drei Schafherden lagerten daran; denn aus diesem Brunnen pflegte man die Herden zu tränken. Der Stein aber über dem Brunnenloch war groß.',
        3: 'Waren nun alle Herden dort beisammen, dann wälzte man den Stein vom Brunnenloch und tränkte die Schafe. Dann brachte man den Stein für das Brunnenloch wieder an seine Stelle.',
        4: 'Da sprach Jakob zu ihnen: "Brüder! Wo seid ihr her?" Sie sagten: "Aus Charan."',
        5: 'Er sprach zu ihnen: "Kennt ihr Laban, Nachors Sohn?" Sie sprachen: "Jawohl!"',
        6: 'Er sprach zu ihnen: "Geht\'s ihm auch gut?" Sie sprachen: "Ja! Und da kommt gerade seine Tochter Rachel mit den Schafen."',
        7: 'Er sprach: "Noch ist\'s hoch am Tag und noch zu früh, das Vieh einzutreiben. Tränket die Schafe und weidet weiter!"',
        8: 'Sie sprachen: "Wir können es nicht, bis alle Herden beisammen sind; dann wälzt man den Stein vom Brunnenloch, und wir tränken die Schafe."',
        9: 'Noch redete er mit ihnen, da kam Rachel mit den Schafen ihres Vaters; denn sie war Hirtin.',
        10: 'Wie nun Jakob Rachel, die Tochter seines Mutterbruders Laban, erblickt hatte und die Schafe seines Mutterbruders Laban, da trat Jakob herzu und wälzte den Stein vom Brunnenloch und tränkte seines Mutterbruders Laban Schafe.',
        11: 'Dann küßte Jakob die Rachel und hob laut zu weinen an.',
        12: 'Und Jakob erzählte der Rachel, er sei ein Bruder ihres Vaters und zwar ein Sohn Rebekkas. Da lief sie und erzählte es ihrem Vater.',
        13: 'Wie Laban solche Kunde von seinem Schwestersohne Jakob vernahm, lief er ihm entgegen, umarmte und küßte ihn und führte ihn in sein Haus; jener aber erzählte Laban die ganze Geschichte.',
        14: 'Und Laban sprach zu ihm: "So bist du also von meinem Bein und Fleisch." Als er einen Monat lang bei ihm war.',
        15: 'sprach Laban zu Jakob: "Wolltest du, weil du mein Bruder bist, mir umsonst dienen? Sag mir: Was soll dein Lohn sein?"',
        16: 'Nun hatte Laban zwei Töchter; die ältere hieß Lea, die jüngere Rachel.',
        17: 'Lea hatte glanzlose Augen, Rachel aber war schön von Gestalt und Antlitz.',
        18: 'Und Jakob gewann Rachel lieb. Er sprach: "Ich diene dir sieben Jahre um Rachel, deine jüngere Tochter."',
        19: 'Laban sprach: "Besser, ich gebe sie dir als einem fremden Mann. Bleib bei mir!"',
        20: 'So diente Jakob um Rachel sieben Jahre, und sie dünkten ihm wie wenige Tage, weil er sie liebte.',
        21: 'Dann sprach Jakob zu Laban: "Gib mir mein Weib! Denn meine Zeit ist um, daß ich sie heirate."',
        22: 'Da lud Laban alle Männer des Ortes ein und bereitete ein Gastmahl.',
        23: 'Als es Abend ward, nahm er seine Tochter Lea und führte sie ihm zu, und er wohnte ihr bei.',
        24: 'Und Laban gab seine Magd Zilpa seiner Tochter Lea zur Magd.',
        25: 'Am Morgen aber war es die Lea. Da sprach er zu Laban: "Was hast du mir da getan? Habe ich nicht um Rachel bei dir gedient? Warum hast du mich betrogen?"',
        26: 'Laban sprach:"An unserem Ort ist\'s nicht der Brauch, die jüngere vor der Älteren wegzugehen.',
        27: 'Führe mit der einen die Woche zu Ende, dann werden wir dir auch die andere geben um den Dienst von weiteren sieben Jahren bei mir."',
        28: 'Und Jakob tat so und führte mit der einen die Woche zu Ende. Dann gab Laban ihm seine Tochter Rachel zum Weib.',
        29: 'Und Laban gab seiner Tochter seine Magd Bilha zur Magd.',
        30: 'So wohnte er auch Rachel bei. Er liebte aber Rachel mehr als Lea, und so diente er bei ihm andere sieben Jahre.',
        31: 'Wie nun der Herr sah, daß Lea nicht geliebt wurde, öffnete er ihren Mutterschoß; Rachel aber blieb unfruchtbar.',
        32: 'So empfing Lea, gebar einen Sohn und nannte ihn Ruben; denn sie sprach: "Gesehen hat ja der Herr mein Elend. Nun wird mein Mann mich liebgewinnen.',
        33: 'Wieder ward sie guter Hoffnung und gebar einen Sohn. Da sprach sie: "Gehört hat ja der Herr, daß ich ungeliebt bin. Darum gab er mir auch diesen." Und sie nannte ihn Simeon.',
        34: 'Wieder ward sie guter Hoffnung und gebar einen Sohn. Da sprach sie: "Nun endlich wird sich mein Mann mit mir verbinden; drei Söhne habe ich ihm geboren." Darum nannte man ihn Levi.',
        35: 'Wieder ward sie guter Hoffnung und gebar einen Sohn. Da sprach sie: "Endlich kann ich den Herrn lobpreisen." Darum nannte sie ihn Juda. Danach hörte sie mit Gebären auf.',
    },
    30: {
        1: 'Als Rachel sah, daß sie dem Jakob kein Kind gebar, ward Rachel auf ihre Schwester neidisch. Sie sprach zu Jakob: "Schaff mir Kinder! Wenn nicht, dann sterbe ich."',
        2: 'Da ging Jakob die Geduld gegenüber Rachel aus, und er sprach: "Bin ich an Gottes Statt, der dir die Leibesfrucht versagt?"',
        3: 'Sie sprach: "Hier ist meine Magd Bilha. Wohne ihr bei, daß sie für meinen Schoß gebäre und auch ich durch sie zu Kindern komme!"',
        4: 'So gab sie ihm ihre Magd Bilha zum Weib, und Jakob wohnte ihr bei.',
        5: 'Bilha ward guter Hoffnung und gebar Jakob einen Sohn.',
        6: 'Da sprach Rachel: "Mir hat Gott Recht verschafft; auch hat er auf meine Stimme gehört und mir einen Sohn geschenkt." Deshalb nannte sie ihn Dan.',
        7: 'Wieder ward Bilha, Rachels Magd, guter Hoffnung und gebar einen zweiten Sohn.',
        8: 'Da sprach Rachel: "Gotteskämpfe habe ich gekämpft mit meiner Schwester und habe gesiegt." Und sie nannte ihn Naphtali.',
        9: 'Als Lea sah, daß sie aufhörte zu gebären, nahm sie ihre Magd Zilpa und gab sie Jakob zum Weib.',
        10: 'Und Leas Magd Zilpa gebar Jakob einen Sohn.',
        11: 'Da sprach Lea: "Glück auf!" Und sie nannte ihn Gad.',
        12: 'Und Leas Magd Zilpa gebar Jakob einen zweiten Sohn.',
        13: 'Da sprach Lea: "Heil mir! Mich preisen Töchter glücklich." Und sie nannte ihn Asser.',
        14: 'Ruben ging in den Tagen der Weizenernte aus und fand auf dem Felde Liebesäpfel und brachte sie seiner Mutter Lea. Da sprach Rachel zu Lea: "Gib mir doch von deines Sohnes Liebesäpfeln!"',
        15: 'Sie sprach zu ihr: "lst\'s nicht genug, daß du meinen Mann wegnimmst, mußt du nun auch noch die Liebesäpfel meines Sohnes wegnehmen?" Da sprach Rachel: "So schlafe er diese Nacht bei dir für die Liebesäpfel deines Sohnes!"',
        16: 'Als Jakob des Abends vom Felde kam, ging Lea ihm entgegen und sprach zu ihm: "Bei mir mußt du einkehren; denn ich habe dich mir für meines Sohnes Liebesäpfel ausbedungen." Und er schlief bei ihr in jener Nacht.',
        17: 'Und Gott erhörte Lea, und sie empfing und gebar Jakob einen fünften Sohn.',
        18: 'Da sprach Lea: "Gott hat mir meinen Lohn für das gegeben, was ich meiner Verwandten für meinen Mann gegeben habe." Und sie nannte ihn Issakar.',
        19: 'Wieder ward Lea guter Hoffnung und gebar Jakob einen sechsten Sohn.',
        20: 'Und Lea sprach: "Gott hat mir eine schöne Spende gespendet; diesmal bleibt mein Mann bei mir; denn sechs Söhne habe ich ihm geboren." Und sie nannte ihn Zabulon.',
        21: 'Danach gebar sie eine Tochter und nannte sie Dina.',
        22: 'Da erinnerte sich Gott der Rachel. Und Gott erhörte sie und öffnete ihr den Mutterschoß.',
        23: 'Und sie ward guter Hoffnung und gebar einen Sohn. Da sprach sie: "Weggenommen hat Gott meine Schmach."',
        24: 'Und sie nannte ihn Joseph, indem sie sagte: "Noch einen Sohn schenkte mir der Herr!"',
        25: 'Als Rachel den Joseph geboren hatte, sprach Jakob zu Laban: "Entlaß mich, daß ich in meine Heimat ziehe, in mein Land!',
        26: 'Gib mir meine Weiber und meine Kinder, um die ich dir gedient! Dann gehe ich. Du kennst selbst meine Dienste, mit denen ich dir gedient."',
        27: 'Da sprach Laban zu ihm: "Mit Vergunst! Ich hab\'s erraten: Deinetwegen hat der Herr mich gesegnet."',
        28: 'Und er sprach: "Nenne deine Lohnforderung an mich, damit ich sie erfülle!"',
        29: 'Er sprach zu ihm: "Du weißt selbst, wie ich dir gedient habe und was aus deinem Viehstand bei mir geworden ist.',
        30: 'Denn wenig ist es gewesen, was du vor mir hattest. Dann aber mehrte es sich in Fülle. So hat dich der Herr nach meiner Ankunft gesegnet. Nun aber, wann soll ich für meinen Hausstand sorgen?"',
        31: 'Er sprach: "Was soll ich dir geben?" Da sprach Jakob: "Gar nichts sollst du mir geben. Gewährst du mir folgendes, dann will ich aufs neue deine Schafe sorgsam weiden.',
        32: 'Ich gehe heute alle deine Schafe durch. Entferne daraus jegliches gesprenkelte und gescheckte Stück! Dann ist jedes Schwarze bei den Lämmern und alles Scheckige und Gesprenkelte bei den Ziegen mein Lohn.',
        33: 'Dann zeugt meine Ehrlichkeit in Zukunft für mich vor dir, kommst du, mich zu belohnen. Was nicht gesprenkelt und nicht scheckig bei den Ziegen und was nicht schwarz bei Lämmern ist, gelte bei mir als gestohlen!"',
        34: 'Und Laban sprach: "Es sei, wie du gesagt!"',
        35: 'So sonderte er am selben Tage die gestreiften und scheckigen Böcke ab, alle gesprenkelten und scheckigen Ziegen, alles, woran Weiß war, und alles Schwarze bei den Lämmern und übergab es seinen Söhnen.',
        36: 'Dann ließ er einen Zwischenraum von drei Tagereisen zwischen sich und Jakob; Jakob aber weidete Labans übriges Vieh.',
        37: 'Da holte Jakob frische Stäbe von Pappeln, Mandelbäumen und Platanen und schälte daran weiße Streifen heraus, das Weiße an den Stäben bloßlegend.',
        38: 'Dann stellte er die geschälten Stäbe in die Tränkrinnen, in die Wasserrinnen, wohin die Tiere zur Tränke kamen, gerade vor die Tiere hin. Sie waren aber in Brunst, als sie zur Tränke kamen.',
        39: 'So begatteten sich die Tiere vor den Stäben. Dann warfen die Tiere gestreifte, gesprenkelte und scheckige Junge.',
        40: 'Die Lämmer aber sonderte Jakob ab. So machte er die besten Tiere in Labans Herden zu gestreiften und ganz schwarzen Stücken und legte sich besondere Herden an, die er nicht zu Labans Herden tat.',
        41: 'Sooft fortan die Brunstzeit der kräftigen Tiere kam, legte Jakob die Stäbe den Tieren vor Augen in die Rinnen, auf daß sie sich vor den Stäben begatteten.',
        42: 'Waren aber die Tiere schwächlich, dann legte er sie nicht hin. So fielen die schwächlichen dem Laban zu, die kräftigen Jakob.',
        43: 'So ward der Mann ohne Maßen reich und kam zu viel Vieh, zu Mägden und Knechten, Kamelen und Eseln.',
    },
    31: {
        1: 'Er vernahm aber die Reden der Labansöhne, die sagten: "Jakob bringt die ganze Habe unseres Vaters an sich; von dem, was unseres Vaters war, hat er all diesen Reichtum geschaffen."',
        2: 'Jakob sah auch an Labans Angesicht, daß er nicht mehr so wie früher gegen ihn war.',
        3: 'Da sprach der Herr zu Jakob: "Kehr in deiner Väter Land zurück, zu deiner Verwandtschaft! Ich will mit dir sein."',
        4: 'Da sandte Jakob und rief Rachel und Lea aufs Feld zu seiner Herde.',
        5: 'Er sprach zu ihnen: "Ich sehe an eures Vaters Angesicht, daß er zu mir nicht mehr so ist wie früher, und doch ist meines Vaters Gott mit mir.',
        6: 'Ihr wißt aber, daß ich mit all meiner Kraft eurem Vater gedient habe.',
        7: 'Doch euer Vater hat mich betrogen und mir den Lohn zehnmal geändert. Aber Gott hat ihm nicht verstattet, mich zu schädigen.',
        8: "Sprach er: 'Die Gesprenkelten seien dein Lohn!', dann warfen alle Tiere Gesprenkelte. Und sprach er: 'Die Gestreiften seien dein Lohn!', dann warfen alle Tiere Gestreifte.",
        9: 'So entzog Gott das Vieh eurem Vater und gab es mir.',
        10: 'Es war in der Brunstzeit der Tiere, da erhob ich meine Augen und sah im Traum, wie die Böcke die Schafe bespringen, gestreift, gesprenkelt und gescheckt.',
        11: "Und Gottes Engel sprach zu mir im Traum: 'Jakob!' Ich sprach: 'Hier bin ich.'",
        12: "Er sprach: 'Hebe deine Augen und sieh: Alle Böcke, die die Schafe bespringen, sind gestreift, gesprenkelt und gescheckt. Ich sehe ja alles, was Laban dir tut.",
        13: 'Ich bin der Herr, der Gott von Betel, wo du ein Steinmal gesalbt und mir ein Gelübde gemacht. Nun auf! Zieh aus diesem Land und kehr in dein Heimatland zurück!"\'',
        14: 'Da antworteten Rachel und Lea und sprachen zu ihm: "Haben wir noch Teil und Erbe im Hause unseres Vaters?',
        15: 'Gelten wir ihm nicht als Fremde? Er hat uns ja verhandelt. Soll er auch unseren Erlös verzehren dürfen?',
        16: 'Ja, all der Reichtum, den Gott unserem Vater entzogen, gehört uns und unseren Kindern. Tu also ganz, wie Gott zu dir gesagt!"',
        17: 'Da erhob sich Jakob, hob seine Kinder und Weiber auf die Kamele',
        18: 'und führte all sein Vieh weg und all seine Habe, die er erworben, das Vieh seines Besitzes, das er zu Paddan Aram erworben, um zu seinem Vater Isaak ins Land Kanaan zu ziehen.',
        19: 'Während Laban ging, seine Schafe zu scheren, stahl Rachel ihres Vaters Teraphim.',
        20: 'Jakob aber überlistete Laban, den Aramäer; durch nichts hatte er ihn ahnen lassen, daß er fliehen wollte.',
        21: 'So floh er mit all seiner Habe. Er brach auf und setzte über den Strom und nahm die Richtung auf das Gebirge Gilead.',
        22: 'Am dritten Tage bekam Laban die Kunde, Jakob sei entflohen.',
        23: 'Da nahm er seine Brüder mit, verfolgte ihn sieben Tagereisen und holte ihn auf dem Gebirge Gilead ein.',
        24: 'Da kam Gott zu Laban, dem Aramäer, nachts im Traum und sprach zu ihm: "Hüte dich, mit Jakob herausfordernd zum Bösen zu reden!"',
        25: 'Als Laban Jakob erreichte, hatte Jakob auf dem Berge sein Zelt aufgeschlagen; Laban aber schlug es mit seinen Brüdern auf dem Gebirge Gilead auf.',
        26: 'Und Laban sprach zu Jakob: "Was hast du getan, daß du mich überlistet und meine Töchter wie Kriegsgefangene fortgeführt hast?',
        27: "Warum bist du heimlich geflohen und hast mich bestohlen? Warum hast du's mir nicht kundgetan? Dann hätte ich dir mit Jauchzen und Singen, mit Pauken und Zithern das Geleite gegeben.",
        28: 'Warum hast du mich nicht zum Abschied meine Enkel und meine Töchter küssen lassen? Nun, du hast recht töricht gehandelt.',
        29: "Ich habe die Macht, euch übel zu tun. Aber deines Vaters Gott hat gestern Nacht zu mir gesprochen: 'Hüte dich, mit Jakob herausfordernd zum Bösen zu reden!'",
        30: 'Nun bist du eben fortgezogen, weil du dich nach deinem Vaterhause gesehnt hast. Warum hast du aber meine Götter gestohlen?"',
        31: 'Da antwortete Jakob und sprach zu Laban: "Wohl! Ich habe Angst gehabt, weil ich gedacht habe, du könntest deine Töchter mir entreißen.',
        32: 'Bei wem du aber deine Götter findest, der soll nicht länger leben. Erkennst du im Beisein unserer Brüder etwas als dein eigen, dann nimm es an dich!" Jakob aber wußte nicht, daß Rachel sie gestohlen hatte.',
        33: 'So kam Laban in Jakobs und in Leas Zelt sowie in das Zelt der beiden Mägde, fand aber nichts; dann ging er aus Leas Zelt und kam in das der Rachel.',
        34: 'Rachel aber hatte die Teraphim genommen und legte sie in die Kamelsänfte und setzte sich auf sie. Laban durchstöberte das ganze Zelt, fand aber nichts.',
        35: 'Da sprach sie zu ihrem Vater: "Sei nicht böse, mein Herr, daß ich vor dir nicht aufstehe! Mir ergeht es nach Weiberart." So suchte er, fand aber die Teraphim nicht.',
        36: 'Da ward Jakob zornig und schalt Laban. Und Jakob hob an und sprach zu Laban: "Was ist mein Verbrechen? Was mein Vergehen, daß du hinter mir herhetzest',
        37: "und mir all mein Gerät durchstöberst? Was hast du von all deinem Hausrat gefunden? Leg's her vor meine und vor deine Brüder, daß sie zwischen uns entscheiden!",
        38: 'Zwanzig Jahre bin ich so bei dir gewesen. Deine Mutterschafe und -ziegen haben nie einen Fehlwurf, und nie habe ich deiner Herde Widder verzehrt.',
        39: 'Zerrissenes habe ich nie vor dich bringen dürfen; ich mußte es ersetzen; von mir fordertest du es. So bin ich betrogen worden bei Tag und bei Nacht.',
        40: 'So ist es mir ergangen: Bei Tage hat mich die Hitze gefressen und der Frost bei Nacht. Meine Augen floh der Schlaf.',
        41: 'Volle zwanzig Jahre habe ich so in deinem Hause dir gedient, vierzehn Jahre um deine beiden Töchter und sechs um deine Schafe, und zehnmal ändertest du meinen Lohn.',
        42: 'Hätte ich nicht meines Vaters Gott gehabt, den Gott Abrahams und Isaaks Schrecken, leer hättest du mich ziehen lassen. Mein Abplagen und meiner Hände Mühen hat aber Gott gesehen und gestern nacht hat er entschieden."',
        43: 'Da erwiderte Laban und sprach zu Jakob: "Mein sind die Töchter, mein die Kinder, mein das Vieh, und alles, was du siehst, gehört mir, also meinen Töchtern. Was könnte ich heute diesen tun oder ihren Kindern, die sie geboren haben?',
        44: 'Nun komm! Wir wollen einen Bund miteinander schließen. Der Herr sei Zeuge zwischen mir und dir!"',
        45: 'Und Jakob nahm einen Stein und richtete ihn als Steinmal auf.',
        46: 'Jakob aber sprach zu seinen Brüdern: "Sammelt Steine!" Da nahmen sie Steine und machten einen Wall. Und sie aßen dort auf dem Wall.',
        47: 'Laban nannte ihn Jegar Sahaduta, und Jakob nannte ihn Galed.',
        48: 'Da sprach Laban: "Dieser Wall ist heute Zeuge zwischen mir und dir." Deshalb nannte er ihn Galed.',
        49: 'Auch Mispa, weil er sagte: "Der Herr wache zwischen mir und dir, wenn wir einander ferne sind.',
        50: 'Ob du meine Töchter schlecht behandelst oder ob du noch andere Weiber zu meinen Töchtern nimmst, ist auch kein Mensch bei uns, bedenke: Zwischen mir und dir ist ein Gott Zeuge!"',
        51: 'Ferner sprach Laban zu Jakob: "Hier dieser Wall und dieses Steinmal, das ich errichte zwischen mir und dir:',
        52: 'Dieser Wall sei Zeuge und Zeuge dieses Steinmal! Ich darf diesen Wall zu dir nicht überschreiten, noch darfst du diesen Wall und dieses Steinmal zu mir überschreiten in böser Absicht.',
        53: 'Zwischen uns richte der Gott Abrahams und Nachors Gott, der Gott ihrer Väter!" Da schwur Jakob beim Schrecken seines Vaters Isaak.',
        54: 'Dann schlachtete Jakob ein Schlachtopfer auf dem Berg und lud seine Brüder ein, das Mahl zu halten. Da hielten sie das Mahl und nächtigten auf dem Berg.',
    },
    32: {
        1: 'Frühmorgens aber küßte Laban seine Enkel und seine Töchter und segnete sie. Dann brach Laban auf und kehrte heim.',
        2: 'Auch Jakob zog seines Wegs; da stießen Gottes Engel auf ihn.',
        3: 'Jakob sprach, als er sie sah: "Dies ist Gottes Heerlager", und er nannte diesen Ort Machanaim.',
        4: 'Jakob sandte nun Boten voraus an seinen Bruder Esau ins Land Seïr, in Edoms Gefilde.',
        5: 'Er trug ihnen folgendes auf: "So sollt ihr sprechen: \'Meinem Herrn Esau läßt dein Sklave Jakob also melden: Bei Laban war ich zu Gast und verzögerte mich bis jetzt.',
        6: 'Ich kam aber zu Rindern und Eseln, zu Schafen, Sklaven und Mägden. Und so wollte ich es meinem Herrn melden lassen, um Huld bei dir zu finden.\'"',
        7: 'Die Boten kehrten zu Jakob zurück und meldeten: "Zu deinem Bruder Esau sind wir gekommen, aber schon zieht er dir entgegen mit vierhundert Mann."',
        8: 'Da geriet Jakob in große Furcht und Bangigkeit. Dann teilte er die Leute bei sich sowie die Schafe, Rinder und Kamele in zwei Lager.',
        9: 'Er dachte nämlich: Kommt Esau über das eine Lager und schlägt es, dann kann das andere Lager entrinnen.',
        10: 'Und Jakob sprach: "Gott meines Vaters Abraham! Gott meines Vaters Isaak! Herr, der du zu mir sprachst: \'Kehr in dein Land zurück, zu der Verwandtschaft! Ich will dir wohltun\',',
        11: 'nicht wert bin ich all der Liebe und Treue, die du deinem Diener erwiesen. Denn nur mit meinem Stock habe ich diesen Jordan überschritten, und jetzt besitze ich zwei Lager.',
        12: 'Ach, rette mich aus meines Bruders Esau Hand! Ich fürchte mich vor ihm. Daß er nicht komme und mich schlage, die Mutter samt den Kindern!',
        13: 'Du aber hast gesprochen: \'Ich will dir reichlich wohltun; dann mache ich wie Sand am Meere deinen Stamm, vor Menge nicht zu zählen.\'"',
        14: 'Er blieb nun dort in jener Nacht; dann nahm er aus dem, was ihm zur Hand war, ein Geschenk für seinen Bruder Esau,',
        15: '200 Ziegen, 20 Böcke, 200 Mutterschafe und 20 Widder,',
        16: '30 säugende Kamele mit ihren Füllen, 40 junge Kühe, 10 junge Stiere, 20 Eselinnen und 10 Eselsfüllen.',
        17: 'Er übergab diese seinen Knechten, jede Herde besonders, und sprach zu seinen Knechten: "Ziehet mir voraus und laßt jedesmal einen Zwischenraum zwischen den Herden!"',
        18: 'Und er wies den vordersten an: "Wenn mein Bruder Esau auf dich stößt und dich fragt: \'Wessen bist du? Wohin Willst du? Wessen sind diese da vor dir?\',',
        19: 'so sprich: \'Deines Sklaven Jakob Geschenke sind sie, abgeschickt für Esau, meinen Herrn. Er selber folgt uns auf dem Fuße nach.\'"',
        20: 'Ebenso wies er den zweiten, den dritten und alle übrigen an, die die Herden trieben, und sprach: "Genauso sollt ihr zu Esau sprechen, wenn ihr ihn treffet.',
        21: 'Ihr sollt sagen: \'Auch dein Sklave Jakob folgt uns auf dem Fuß!\'" Er dachte nämlich: Ablenken will ich seine Aufmerksamkeit durch das Geschenk, das mir vorausgeht; erst dann trete ich ihm vor die Augen. Vielleicht nimmt er mich gnädig auf.',
        22: 'So ging ihm das Geschenk voraus; er selber nächtigte in jener Nacht zu Machanaim.',
        23: 'In derselben Nacht stand er auf, nahm seine beiden Weiber, seine beiden Mägde und seine elf Kinder und führte sie über die Jabbokfurt.',
        24: 'Er nahm sie und führte sie über den Fluß und brachte alles, was er hatte, hinüber.',
        25: 'Jakob blieb allein zurück; da rang mit ihm ein Mann bis zum Anbruch der Morgenröte.',
        26: 'Und als er sah, daß er ihn nicht überwände, rührte er an seine Hüftpfanne, und Jakobs Hüftpfanne ward verrenkt, als er mit ihm rang.',
        27: 'Dann sprach er: "Laß mich los! Die Morgenröte bricht an." Er sprach: "Ich lasse dich nicht los, bevor du mich segnest."',
        28: 'Er sprach zu ihm: "Wie heißest du?" Er sprach: "Jakob."',
        29: 'Da sprach er: "Fortan sollst du nicht Jakob heißen, sondern Israel. Du hast mit Gott gekämpft, und so trägst du den Sieg davon auch über Menschen."',
        30: 'Da bat Jakob und sprach: "Tu auch deinen Namen kund!" Er sprach: "Warum doch fragst du mich nach meinem Namen?" Und er segnete ihn dort.',
        31: 'Jakob nannte den Ort Penuël: "Ich habe Gott geschaut von Angesicht zu Angesicht und kam mit dem Leben davon."',
        32: 'Die Sonne strahlte ihm auf, als er an Penuël vorüberzog; er aber hinkte an seiner Hüfte. Darum sollen Israels Söhne bis auf diesen Tag keine Sehne des Schenkels essen, der auf der Hüftpfanne läuft, weil er Jakobs Hüftpfanne, die Sehne des Schenkels, berührt hat.',
    },
    33: {
        1: 'Jakob aber erhob seine Augen und schaute; da kam Esau mit 400 Mann. Da verteilte er die Kinder auf Lea, Rachel und die beiden Mägde.',
        2: 'Und zwar stellte er die Mägde und ihre Kinder voran, dahinter Lea mit ihren Kindern und ganz hinten Rachel und Joseph.',
        3: 'Er selbst ging ihnen voraus und neigte sich siebenmal zur Erde, bis er zu seinem Bruder kam.',
        4: 'Da lief ihm Esau entgegen, umarmte ihn, fiel ihm um den Hals und küßte ihn. Und sie weinten.',
        5: 'Dann erhob er seine Augen, sah die Weiber mit den Kindern und sprach: "Was sind diese da bei dir?" Er sprach: "Das sind die Kinder, die Gott deinem Sklaven geschenkt hat."',
        6: 'Da traten die Mägde mit ihren Kindern herzu und verneigten sich.',
        7: 'Auch Lea und ihre Kinder traten herzu und verneigten sich. Danach traten Joseph und Rachel herzu und verneigten sich.',
        8: 'Er sprach: "Was soll dir dies ganze Lager, auf das ich gestoßen bin?" Er sprach: "Auf daß ich Gnade finde bei meinem Herrn!"',
        9: 'Da sprach Esau: "Ich habe übergenug, mein Bruder. Behalte, was dir gehört!"',
        10: 'Jakob sprach: "Nicht doch! Habe ich in deinen Augen Gnade gefunden, dann mußt du meine Gabe von mir annehmen. Denn ich habe dein Antlitz gesehen, so, wie ich Gottes Antlitz sah, und du nahmst mich zu Gnaden an.',
        11: 'Nimm doch mein Grußgeschenk, das dir dargebracht ward! Denn Gott hat mich begnadet, und ich habe vollauf." So drang er in ihn, bis er es nahm.',
        12: 'Dann sprach er: "Laßt uns aufbrechen und weiterziehen! Ich halte gleichen Schritt mit dir."',
        13: 'Er aber sprach zu ihm: "Mein Herr sieht selber, daß die Kinder zart sind, und säugende Schafe und Kinder stehen in meiner Obhut. Wollte ich sie einen Tag über Gebühr anstrengen, dann stürbe die ganze Herde.',
        14: 'So ziehe mein Herr doch vor seinem Sklaven her! Ich ziehe gemächlich weiter, im Schritte des Viehstands vor mir und im Schritte der Kinder, bis ich zu meinem Herrn nach Seïr komme!"',
        15: 'Da sprach Esau: "So will ich wenigstens bei dir einen Teil meiner Leute lassen." Er aber sprach: "Wozu? Möchte ich nur Huld bei meinem Herrn finden!"',
        16: 'So kehrte Esau an jenem Tag nach Seïr zurück.',
        17: 'Jakob aber zog nach Sukkot weiter und baute sich ein Haus, seinem Vieh aber machte er Laubhütten. Daher nennt man den Ort Sukkot.',
        18: 'Und Jakob kam in friedlicher Gesinnung nach der Stadt Sichem im Lande Kanaan auf seiner Fahrt aus Paddan Aram und lagerte östlich von der Stadt.',
        19: 'Er kaufte das Stück Feld, wo er sein Zelt gespannt, von den Söhnen Chamors, des Herrn von Sichem, um 100 Beutel.',
        20: 'Und er stellte dort einen Altar auf und pries bei ihm den Gott Israels.',
    },
    34: {
        1: 'Einst ging Dina, Leas Tochter, die sie Jakob geboren, aus, sich unter des Landes Töchtern sehen zu lassen.',
        2: 'Da erblickte sie Sichem, der Sohn des chiwitischen Landesfürsten Chamor, entführte sie, wohnte ihr bei und tat ihr Gewalt an.',
        3: 'Er aber hängte sich mit ganzer Seele an Jakobs Tochter Dina und gewann das Mädchen lieb. So redete er dem Mädchen zu Herzen.',
        4: 'Und Sichem sprach zu seinem Vater Chamor also: "Freie dies Kind mir zum Weibe!"',
        5: 'Jakob aber hatte vernommen, man habe seine Tochter Dina geschändet. Seine Söhne aber waren mit seinem Vieh auf dem Felde gewesen. So hatte Jakob bis zu ihrer Rückkehr geschwiegen.',
        6: 'Da ging Sichems Vater Chamor zu Jakob, mit ihm Rücksprache zu nehmen.',
        7: 'Die Söhne Jakobs aber waren sofort vom Felde heimgekommen, als sie davon gehört hatten. Die Männer waren erbittert und in heftigem Zorn; denn eine Schandtat hatte er an Israel begangen, daß er Jakobs Tochter beschlief. Solches durfte nicht geschehen!',
        8: 'Chamor aber redete mit ihnen also: "Mein Sohn Sichem hat sein Herz an eure Tochter gehängt. Gebt sie ihm doch zum Weibe!',
        9: 'Verschwägert euch mit uns! Eure Töchter gebt ihr uns und nehmt euch unsere Töchter!',
        10: 'Dann bleibt ihr bei uns wohnen. Das Land steht euch offen. Bleibt da und zieht umher und siedelt darin!"',
        11: 'Und Sichem sprach zu ihrem Vater und ihren Brüdern: "Möchte ich Gnade in euren Augen finden! Was ihr auch von mir fordert, ich gebe es.',
        12: 'Fordert noch soviel Kaufgeld und Geschenke von mir, ich will\'s geben, wie ihr\'s von mir fordert. Nur gebt das Mädchen mir zum Weibe."',
        13: 'Da antworteten Jakobs Söhne Sichem und seinem Vater Chamor arglistig; das Wort aber führten die, deren Vollschwester Dina er geschändet hatte.',
        14: 'Sie sprachen zu ihm: "Wir können dies nicht tun, unsere Schwester einem unbeschnittenen Mann geben. Denn dies gilt uns als schmachvoll.',
        15: 'Doch unter der Bedingung willfahren wir euch, wenn ihr werdet wie wir, insofern alles Männliche bei euch beschnitten wird.',
        16: 'Dann geben wir euch unsere Töchter und nehmen uns eure Töchter und wohnen bei euch und werden so ein Volk.',
        17: 'Wollt ihr aber wegen der Beschneidung nicht auf uns hören, dann nehmen wir unsere Tochter und gehen."',
        18: 'Und der Vorschlag gefiel Chamor, ebenso Chamors Sohne Sichem.',
        19: 'Der Jüngling aber zauderte nicht, dies zu veranlassen; denn er hatte Gefallen an Jakobs Tochter. Auch war er im ganzen Hause seines Vaters der Angesehenste.',
        20: 'So kamen Chamor und sein Sohn Sichem zum Tor ihrer Stadt und redeten also zu den Männern ihrer Stadt:',
        21: '"Friedlich gesinnt sind uns diese Männer. Sie sollen im Lande wohnen und darin verkehren, hat doch das Land nach allen Seiten Raum für sie. Wir wollen ihre Töchter uns zu Weibern nehmen und ihnen unsere Töchter geben.',
        22: 'Doch einzig unter der Bedingung wollen diese Männer bei uns wohnen bleiben und ein Volk werden, wenn sich alles Männliche bei uns beschneidet, wie sie beschnitten sind.',
        23: 'Werden ihre Herden aller Art und all ihr Vieh uns nicht von Nutzen sein? So wollen wir ihnen willfahren, daß sie bei uns wohnen bleiben."',
        24: 'Da hörten auf Chamor und seinen Sohn Sichem alle, die zum Tore seiner Stadt hinausziehen konnten, und alle Männer, die zum Tore seiner Stadt hinausziehen konnten, ließen sich beschneiden.',
        25: 'Aber am dritten Tage, als sie wundkrank waren, griffen die beiden Jakobssöhne, Simeon und Levi, Dinas Brüder, jeder nach seinem Schwert, überfielen dreist die Stadt und erschlugen jede Mannesperson.',
        26: 'Auch Chamor und seinen Sohn Sichem schlugen sie mit des Schwertes Schärfe, dann holten sie Dina aus Sichems Hause.',
        27: 'Dann zogen auch die anderen Jakobssöhne aus, kamen über die Erschlagenen und plünderten die Stadt, weil sie ihre Schwester geschändet hatten.',
        28: 'Sie nahmen ihre Schafe, Rinder, Esel, was in der Stadt und draußen war.',
        29: 'All ihre Habe und all ihre Kinder und ihre Weiber erbeuteten sie; und plünderten alles, was in den Häusern war.',
        30: 'Da sprach Jakob zu Simeon und Levi: "Ihr habt mich verstört. Ihr macht mich bei des Landes Bewohnern, den Kanaanitern und den Perizitern, verhaßt, und doch habe ich nur wenige ohnmächtige Wichte. Rotten sie sich gegen mich zusammen, dann schlagen sie mich, und ich werde mit meinem Haus vernichtet."',
        31: 'Sie sprachen: "Durfte man denn unsere Schwester wie eine Dirne behandeln?"',
    },
    35: {
        1: 'Gott sprach zu Jakob: "Auf! Hin nach Betel, bleib dort und baue dort einen Altar dem Gott, der dir erschienen ist, als du vor deinem Bruder Esau bist geflohen."',
        2: 'Da sprach Jakob zu seiner Familie und allen anderen bei ihm: "Werft die fremden Götter bei euch weg! Reinigt euch und bessert eure Kleider aus!',
        3: 'Wir wollen uns aufmachen und nach Betel ziehen! Dort will ich einen Altar bauen dem Gott, der mich an meinem Nottag erhört und mit mir auf dem Weg gewesen, den ich gegangen bin."',
        4: 'Da gaben sie Jakob alle fremden Götter aus ihrem Besitz, samt ihren Ohrringen, und Jakob vergrub sie unter der Terebinthe bei Sichem.',
        5: 'Dann brachen sie auf. Aber ein Gottesschrecken fiel auf die Städte ringsum; da verfolgten sie nicht die Jakobssöhne.',
        6: 'So kam Jakob nach Luz im Land Kanaan, das ist Betel, er und all die Leute bei ihm.',
        7: 'Er baute dort einen Altar und rief bei dem Orte den Gott von Betel an; denn hier hatten sich ihm die göttlichen Mächte geoffenbart, als er vor seinem Bruder floh.',
        8: 'Da starb Rebekkas Amme Debora. Sie ward unterhalb Betels unter der Eiche begraben; man nannte sie Klageeiche.',
        9: 'Und Gott erschien nochmals Jakob nach seiner Rückkehr aus Paddan Aram und segnete ihn.',
        10: 'Und Gott sprach zu ihm: "Du heißest Jakob; fortan sollst du nicht Jakob heißen, nein, Israel soll nun dein Name sein!" Daher nannte man ihn Israel.',
        11: 'Und Gott sprach zu ihm: "Gott bin ich, der Allmächtige. Sei fruchtbar, mehre dich! Ein Volk, ja Völkerscharen sollen dir entstammen und Könige aus deinen Lenden sprossen!',
        12: 'Das Land, das ich gegeben Abraham und Isaak, gebe ich dir. Auch deinem Stamm nach dir verleihe ich das Land."',
        13: 'Und Gott fuhr von ihm an der Stätte auf, wo er mit ihm geredet hatte.',
        14: 'Da errichtete Jakob ein Mal an dem Ort, wo er mit ihm geredet, ein Steinmal, und goß darauf ein Trankopfer und schüttete Öl darüber.',
        15: 'Und Jakob nannte die Stätte, wo Gott mit ihm geredet, Betel.',
        16: 'Sie zogen von Betel weiter. Es war aber noch ziemlich weit nach Ephrat; da mußte Rachel gebären, und sie bekam eine schwere Geburt.',
        17: 'Als ihr die Geburt so schwer ward, sprach die Geburtshelferin zu ihr: "Sei getrost! Du hast auch diesmal einen Sohn."',
        18: 'Als ihr aber der Lebenshauch entfloh, denn sie mußte sterben, nannte sie ihn Ben Oni; sein Vater aber hieß ihn Benjamin.',
        19: 'So starb Rachel. Sie ward am Weg nach Ephrat, das ist Bethlehem, begraben.',
        20: 'Jakob stellte auf ihrem Grab ein Steinmal auf. Das ist das Steinmal am Rachelgrab bis auf diesen Tag.',
        21: 'Israel zog weiter und spannte sein Zelt jenseits vom Herdenturm auf.',
        22: 'Während Israel in dieser Gegend wohnte, ging Ruben hin und beschlief seines Vaters Nebenweib Bilha, und Israel vernahm es. Die Jakobssöhne waren aber ihrer zwölf.',
        23: 'Die Leasöhne waren Jakobs Erstgeborener Ruben, Simeon, Levi, Juda, Issakar und Zabulon.',
        24: 'Die Rachelsöhne waren Joseph und Benjamin.',
        25: 'Die Söhne Bilhas, der Magd der Rachel, waren Dan und Naphtali.',
        26: 'Und die Söhne Zilpas, der Magd der Lea, waren Gad und Asser; dies sind die Jakobssöhne, die ihm zu Paddan Aram geboren sind.',
        27: 'Jakob kam nun zu seinem Vater Isaak nach Mamre bei Kirjat Arba, das ist Hebron, wo Abraham und Isaak als Gäste geweilt hatten.',
        28: 'Und Isaaks Lebensdauer betrug 180 Jahre,',
        29: 'da verschied Isaak. Er starb und ward zu seinen Stammesgenossen versammelt, alt und lebenssatt. Ihn begruben seine Söhne Esau und Jakob.',
    },
    36: {
        1: 'Das ist die Geschlechterfolge Esaus, das ist Edoms:',
        2: 'Esau nahm seine Weiber aus den Töchtern Kanaans: Ada, die Tochter des Chittiters Elon, und Oholibama, die Tochter Anas, der Tochter des Choriters Sibon,',
        3: 'und Basemat, die Tochter Ismaels und Schwester Nebajots.',
        4: 'Ada gebar dem Esau den Eliphaz; Basemat aber hatte den Reguel geboren',
        5: 'und Oholibama den Jëus, Jalam und Korach. Dies sind die Esausöhne, die im Lande Kanaan geboren sind.',
        6: 'Esau nahm seine Weiber, Söhne und Töchter, überhaupt alle Seelen seines Hauses und seine Herde, all sein Vieh und seine ganze Habe, die er sich im Lande Kanaan erworben hatte, und zog in ein anderes Land, fort von seinem Bruder Jakob.',
        7: 'Denn ihr Besitz war zu groß geworden zum Beisammenbleiben, und das Land, in dem sie als Gäste weilten, hatte wegen ihrer Herden für sie nicht ausgereicht.',
        8: 'So ließ sich Esau auf dem Gebirge Seïr nieder: Esau ist Edom.',
        9: 'Das ist die Geschlechterfolge Esaus, des Vaters von Edom, auf dem Gebirge Seïr.',
        10: 'Dies sind die Namen der Söhne Esaus: Eliphaz, der Sohn der Ada, des Weibes Esaus, und Reguel, der Sohn der Basemat, des Weibes Esaus.',
        11: 'Die Söhne des Eliphaz waren Teman, Omar, Sepho, Gatam und Kenaz.',
        12: 'Timna aber war ein Nebenweib des Esausohnes Eliphaz, und sie gebar dem Eliphaz den Amalek. Dies sind die Söhne der Ada, des Weibes Esaus.',
        13: 'Und dies sind die Söhne Reguels. Nachat, Zerach, Samma und Mizza. Dies waren die Söhne der Basemat, des Weibes Esaus.',
        14: 'Und dies waren die Söhne der Oholibama, der Tochter Anas, der Tochter Sibons und des Weibes Esaus: Sie gebar dem Esau den Jëus, den Jalam und den Korach.',
        15: 'Dies sind die Häuptlinge der Söhne Esaus. Die Söhne des Erstgeborenen Esaus, Eliphaz, waren der Häuptling Teman, der Häuptling Omar, der Häuptling Sepho und der Häuptling Kenaz,',
        16: 'der Häuptling Korach, der Häuptling Gatam und der Häuptling Amalek. Dies sind die Häuptlinge des Eliphaz im Lande Edom; dies sind die Söhne der Ada.',
        17: 'Und dies sind die Söhne des Esausohnes Reguel: der Häuptling Nachat, der Häuptling Zerach, der Häuptling Samma und der Häuptling Mizza; dies sind die Häuptlinge Reguels im Lande Edom; dies sind die Söhne Basemats, des Weibes Esaus.',
        18: 'Und dies sind die Söhne der Oholibama, des Weibes Esaus: der Häuptling Jëus, der Häuptling Jalam und der Häuptling Korach; dies sind die Häuptlinge der Oholibama, der Tochter Anas und des Weibes Esaus.',
        19: 'Dies sind die Söhne Esaus und dies ihre Häuptlinge: das ist Edom.',
        20: 'Dies sind die Söhne des Choriters Seïr, die Einwohner des Landes: Lotan, Sobal, Sibon und Ana,',
        21: 'Dison, Eser und Disan; dies sind die Häuptlinge der Choriter, der Söhne Seïrs im Lande Edom.',
        22: 'Die Söhne Lotans waren Chori und Hemam, und Lotans Schwester war Timna.',
        23: 'Und dies sind die Söhne Sobals: Alwan, Manachat, Ebal, Sepho und Onam.',
        24: 'Und dies sind die Söhne Sibons: Ajja und Ana; das ist der Ana, der die Ungeheuer in der Wüste angetroffen hat, als er seinem Vater Sibon die Esel weidete.',
        25: 'Und dies sind die Söhne Anas: Dison, und Oholibama war die Tochter des Ana.',
        26: 'Und dies sind die Söhne des Disan, Chemdan, Esban, Jitran und Keran..',
        27: 'Dies sind die Söhne des Eser: Bilhan, Zaawan und Akan.',
        28: 'Dies sind die Söhne Disans: Uz und Aram.',
        29: 'Dies sind die Häuptlinge der Choriter: der Häuptling Lotan, der Häuptling Sobal, der Häuptling Sibon und der Häuptling Ana,',
        30: 'der Häuptling Dison, der Häuptling Eser, der Häuptling Disan; dies sind die Häuptlinge der Choriter nach ihren Geschlechtern im Lande Seïr.',
        31: 'Dies sind die Könige, die im Lande Edom geherrscht haben, bevor ein König über Israels Söhne herrschte.',
        32: 'König über Edom war Bela, Beors Sohn, und seine Stadt hieß Dinhaba.',
        33: 'Als Bela starb, ward an seiner Statt König Jobab, Zerachs Sohn, aus Bosra.',
        34: 'Als Jobab starb, ward an seiner Statt König Chusam aus dem Land der Temaniter.',
        35: 'Als Chusam starb, ward an seiner Statt König Bedads Sohn Hadad, der die Midianiter auf Moabs Gefilden schlug, und seine Stadt hieß Awit.',
        36: 'Als Hadad starb, ward an seiner Statt Samla aus Masreka König.',
        37: 'Als Samla starb, ward an seiner Statt Saul aus Nechobot am Strome König.',
        38: 'Als Saul starb, ward an seiner Statt Baalchanan aus Akbor König.',
        39: 'Als Baalchanan aus Akbor starb, ward an seiner Statt Hadad König, und seine Stadt hieß Pau und sein Weib Mehetabel, die Tochter Matreds, der Tochter von Mezahab.',
        40: 'Dies sind die Namen der Häuptlinge Esaus nach ihren Geschlechtern, ihren Ortschaften und Namen: der Häuptling Timna, der Häuptling Alwa, der Häuptling Jetet,',
        41: 'der Häuptling Oholibama, der Häuptling Ela, der Häuptling Pinon,',
        42: 'der Häuptling Kenaz, der Häuptling Teman, der Häuptling Mibsar,',
        43: 'der Häuptling Magdiel und der Häuptling Iram. Dies sind die Häuptlinge Edoms nach ihren Wohnsitzen in ihrem besetzten Gebiet. Das ist Esau, der Vater Edoms.',
    },
    37: {
        1: 'Jakob aber wohnte in dem Land, in dem sein Vater zu Gast geweilt, im Land Kanaan.',
        2: 'Dies ist Jakobs Geschlechterfolge: Als Joseph siebzehn Jahre alt geworden, pflegte er seine Brüder bei den Schafherden zu besuchen. Er hielt sich aber als junger Mann zu den Söhnen Bilhas und Zilpas, der Weiber seines Vaters. Und so konnte Joseph ihrem Vater schlimme Geschichten über sie vermelden.',
        3: 'Israel aber liebte Joseph mehr als alle seine anderen Söhne; denn er war ihm in seinem Alter geboren, und so hatte er ihm einen langen Leibrock machen lassen.',
        4: 'Wie nun seine Brüder sahen, daß ihn sein Vater mehr als alle seine Brüder liebte, da haßten sie ihn, und so konnten sie nicht unter sich freundlich über ihn reden.',
        5: 'Einst hatte nun Joseph einen Traum und erzählte ihn seinen Brüdern; da haßten sie ihn noch mehr.',
        6: 'Er sprach zu ihnen: "Hört doch, was ich geträumt habe!',
        7: 'Wir banden Garben auf dem Felde. Da hat sich meine Garbe aufgerichtet und ist stehengeblieben. Aber eure Garben stellten sich herum und neigten sich vor meiner Garbe."',
        8: 'Da sprachen seine Brüder zu ihm "Du wärst wohl gern König über uns; du wärst wohl gern unser Herrscher?" Und sie haßten ihn noch ärger wegen seines Traumes und seiner Erzählung.',
        9: 'Er träumte aber wieder und erzählte es seinen Brüdern. Er sprach: "Noch einen Traum habe ich gehabt: Die Sonne, der Mond und elf Sterne neigten sich vor mir."',
        10: 'Als er dies seinem Vater und seinen Brüdern erzählte, schalt ihn sein Vater und sprach zu ihm: "Was ist das für ein Traum, den du gehabt? Sollen wir, ich, deine Mutter und deine Brüder kommen und uns vor dir zur Erde neigen?"',
        11: 'Seither waren ihm seine Brüder mißgesinnt. Sein Vater aber merkte sich die Sache.',
        12: 'Nun gingen seine Brüder, ihres Vaters Schafe bei Sichem zu weiden.',
        13: 'Da sprach Israel zu Joseph: "Weiden deine Brüder nicht zu Sichem? Komm! Ich will dich zu ihnen senden." Er sprach zu ihm: "Ich bin bereit."',
        14: 'Da sprach er zu ihm: "Geh! Schau nach dem Befinden deiner Brüder und der Herde und bringe mir Bescheid!" So schickte er ihn aus dem Tal von Hebron, und er kam nach Sichem.',
        15: 'Da sah ihn ein Mann auf dem Feld umherirren, und der Mann fragte ihn: "Wen suchst du?"',
        16: 'Er sprach: "Ich suche meine Brüder. Sag mir doch, wo sie weiden!"',
        17: 'Da sprach der Mann: "Sie sind von hier weggezogen. Ich habe sie nämlich sprechen gehört: \'Wir wollen nach Dotain gehen.\'" Da ging Joseph seinen Brüdern nach und traf sie in Dotain.',
        18: 'Sie sahen ihn aber schon von ferne, und bevor er zu ihnen kam, heckten sie gegen ihn einen Mordplan aus.',
        19: 'Sie sprachen zueinander: "Seht, dort drüben kommt der Träumer!',
        20: 'Nun auf! Erschlagen wir ihn und werfen wir ihn in eine der Gruben; dann sagen wir: \'Ein wildes Tier hat ihn gefressen.\' Dann sehen wir, was aus seinen Träumen wird."',
        21: 'Als Ruben dies hörte, suchte er ihn aus ihrer Hand zu retten. Er sprach: "Wir wollen ihn nicht totschlagen."',
        22: 'Dann sprach Ruben zu ihnen: "Vergießt kein Blut! Werft ihn in die Grube da in der Steppe! Aber legt nicht Hand an ihn!" So wollte er ihn aus ihrer Hand retten und ihn seinem Vater heimbringen.',
        23: 'Wie nun Joseph zu seinen Brüdern kam, rissen sie Joseph seinen Leibrock ab, den langen Leibrock, den er anhatte.',
        24: 'Und sie packten ihn und warfen ihn in die Grube; die Grube aber war leer und wasserlos.',
        25: 'Dann setzten sie sich zum Mahle nieder. Wie sie nun aufblickten, sahen sie, wie eine Karawane von Ismaelitern aus Gilead herankam, ihre Kamele beladen mit Tragakanth, Mastix und Ladanharz, auf dem Weg nach Ägypten.',
        26: 'Da sprach Juda zu seinen Brüdern: "Was haben wir davon, wenn wir unseren Bruder umbrächten und dann sein Blut zudeckten?',
        27: 'Kommt! Wir wollen ihn den Ismaelitern verkaufen! Aber unsere Hand komme nicht an ihn! Er ist doch unser Bruder, unser eigen Fleisch." Da willigten seine Brüder ein.',
        28: 'Als aber midianitische Handelsleute vorüberzogen, zogen sie Joseph aus der Grube. Und sie verkauften Joseph an die Ismaeliter um zwanzig Silberlinge. Diese aber brachten Joseph nach Ägypten.',
        29: 'Als nun Ruben wieder zu der Grube kam, war Joseph nicht mehr in der Grube. Da zerriß er seine Kleider,',
        30: 'kehrte zu seinen Brüdern zurück und sprach: "Der Knabe ist nicht mehr da. Wie kann ich da heimgehen?"',
        31: 'Da nahmen sie Josephs Leibrock, schlachteten einen Ziegenbock und tauchten den Rock in das Blut.',
        32: 'Dann machten sie den langen Leibrock noch schmutzig, brachten ihn ihrem Vater und sprachen: "Dies haben wir gefunden. Sieh zu, ob\'s deines Sohnes Rock ist oder nicht!"',
        33: 'Er betrachtete ihn und sprach: "Meines Sohnes Rock ist\'s. Ein wildes Tier hat ihn gefressen. Ach, Joseph ist zerrissen worden."',
        34: 'Und Jakob zerriß seine Kleider, legte ein härenes Gewand um seine Hüften und trauerte um seinen Sohn viele Tage.',
        35: 'Da machten sich all seine Söhne und Töchter daran, ihn zu trösten; er aber wollte sich nicht trösten lassen. Er sprach: "Nein! Trauernd fahre ich zu meinem Sohne in die Unterwelt." Und sein Vater weinte um ihn.',
        36: 'So hatten ihn die Midianiter nach Ägypten verkaufen lassen an Potiphar, den Kämmerer des Pharao und den Anführer der Leibwache.',
    },
    38: {
        1: 'In jener Zeit verließ Juda seine Brüder und schloß sich einem Mann von Adullam, namens Chira, an.',
        2: 'Dort sah nun Juda die Tochter eines Kanaaniters namens Sua; er freite und heiratete sie.',
        3: 'Und sie empfing und gebar einen Sohn; er nannte ihn Ger.',
        4: 'Wieder ward sie guter Hoffnung und gebar einen Sohn; sie nannte ihn Onan.',
        5: 'Dann gebar sie noch einen Sohn; sie nannte ihn Sela; zu Kezib war es gewesen, wo sie ihn gebar.',
        6: 'Dann freite Juda für seinen Erstgeborenen Ger ein Weib namens Tamar.',
        7: 'Ger aber, Judas Erstgeborener, machte sich dem Herrn mißfällig, und so ließ ihn der Herr sterben.',
        8: 'Da sprach Juda zu Onan: "Komm zu dem Weibe deines Bruders! Leiste ihr die Schwagerpflicht und erwecke deinem Bruder Nachkommen!"',
        9: 'Onan aber wußte, daß ihm die Nachkommenschaft nicht gehören würde; als er nun zu seines Bruders Weibe kam, vereitelte er die Zeugung, um nicht seinem Bruder Nachkommen zu schenken.',
        10: 'Dem Herrn aber mißfiel, was er getan, und er ließ auch ihn sterben.',
        11: 'Da sprach Juda zu seiner Schwiegertochter Tamar: "Bleib als Witwe in deines Vaters Haus, bis mein Sohn Sela erwachsen ist!" Denn er dachte, auch dieser könnte wie seine Brüder sterben. Tamar ging nun und blieb in ihres Vaters Haus.',
        12: 'Längere Zeit verstrich; da starb Suas Tochter, Judas Weib. Als Juda ausgetrauert hatte, ging er hinauf zu seiner Schafschur mit seinem Freunde, dem Adullamiter Chira, nach Timna.',
        13: 'Da ward Tamar gemeldet: "Dein Schwiegervater kommt nach Timna zur Schafschur."',
        14: 'Da legte sie ihre Witwenkleider ab, bedeckte sich mit dem Schleier, vermummte sich und setzte sich an den Zugang nach Enaim, am Wege nach Timna. Sie hatte nämlich bemerkt, daß Sela erwachsen war, und dennoch war sie ihm nicht zum Weibe gegeben worden.',
        15: 'Juda aber sah sie und hielt sie für eine Dirne; denn sie hatte ihr Gesicht verhüllt.',
        16: 'Und er bog zu ihr an den Weg ab und sprach: "Laß mich, bitte, zu dir kommen!" Denn er merkte nicht, daß es seine Schwiegertochter war. Sie sprach: "Was gibst du mir dafür, wenn du zu mir kommen darfst?"',
        17: 'Er sprach: "Ich sende dir ein Ziegenböckchen von der Herde." Sie sprach: "Wenn du mir ein Pfand gibst, bis du\'s schickst."',
        18: 'Er sprach: "Was für ein Pfand soll ich dir geben?" Sie sprach: "Dein Siegel, deine Schnur und den Stab in deiner Hand!" Er gab es ihr; dann kam er zu ihr, und sie empfing von ihm.',
        19: 'Dann erhob sie sich, legte ihren Schleier ab und zog ihre Witwenkleider wieder an.',
        20: 'Juda sandte nun das Ziegenböckchen durch seinen Freund, den Adullamiter, um dafür das Pfand von dem Weibe zurückzuerhalten. Aber er fand sie nicht mehr.',
        21: 'Da fragte er die Leute ihres Ortes: "Wo ist die Weihdirne, die hier bei Enaim am Wege gewesen ist?" Sie sprachen: "Hier ist doch keine Dirne gewesen."',
        22: 'Da kehrte er zu Juda zurück und sprach: "Ich fand sie nicht, und auch die Leute im Orte sagten: "Hier war keine Dirne."',
        23: 'Da sprach Juda: "So mag sie\'s behalten! Daß wir nur nicht zum Gespött werden! Ich aber habe dies Böckchen geschickt, und du hast sie nur nicht gefunden."',
        24: 'Nach ungefähr drei Monaten ward Juda berichtet: "Deine Schwiegertochter Tamar hat nicht nur gebuhlt, sondern ist durch die Buhlerei auch in Hoffnung gekommen." Da sprach Juda: "Führt sie hinaus! Sie werde verbrannt!"',
        25: 'Schon wurde sie hinausgeführt, da schickte sie zu ihrem Schwiegervater und ließ sagen: "Von jenem Mann, dem dies gehört, bin ich guter Hoffnung." Sie ließ ihm auch sagen: "Sieh doch genau zu! Wem gehört dies, das Siegel, die Schnüre und der Stab?"',
        26: 'Und Juda betrachtete sie und sprach: "Sie hat recht gegen mich. Warum habe ich sie nicht meinem Sohne Sela gegeben?" Er aber hatte fortan keinen Umgang mehr mit ihr.',
        27: 'Zur Zeit ihres Gebärens aber waren Zwillinge in ihrem Leibe.',
        28: 'Als sie gebar, streckte der eine eine Hand vor. Da nahm die Hebamme einen roten Faden und band ihn um seine Hand, wobei sie sprach: "Dieser ist zuerst herausgetreten."',
        29: 'Als er aber seine Hand zurückzog, kam sein Bruder zum Vorschein. Da sprach sie: "Wie du dir einen Vorläufer bestellt hast!" Und man nannte ihn Peres.',
        30: 'Hernach kam sein Bruder zum Vorschein, an dessen Hand der rote Faden war. Und man nannte ihn Zerach.',
    },
    39: {
        1: 'So war Joseph nach Ägypten gebracht worden. Da kaufte ihn Potiphar, Pharaos Kämmerer und Oberster der Leibwächter, ein ägyptischer Mann, von den Ismaelitern, die ihn dorthin gebracht hatten.',
        2: 'Der Herr aber war mit Joseph, und so ward er ein Mann, dem alles gelang. Da er im Hause seines ägyptischen Herrn blieb,',
        3: 'sah sein Herr, daß der Herr mit ihm sei und daß der Herr ihm alles, was er vornahm, gelingen ließ.',
        4: 'So fand Joseph in seinen Augen Gnade und durfte ihn bedienen. Dann setzte er ihn als Verwalter über sein Haus und vertraute ihm sein ganzes Eigentum.',
        5: 'Und seitdem er ihn über sein Haus bestellt und all sein Eigentum ihm anvertraut hatte, segnete der Herr das Haus des Ägypters um Josephs willen. Und des Herrn Segen ruhte auf seinem Eigentum in Haus und Feld.',
        6: 'So überließ er all sein Eigentum Joseph und kümmerte sich bei ihm um nichts als um die Speise, die er genoß. Joseph aber ward schön von Gestalt und Antlitz.',
        7: 'Nach diesen Begebnissen geschah es, daß seines Herrn Weib die Augen zu Joseph erhob und sprach: "Leg dich zu mir!"',
        8: 'Er aber weigerte sich und sprach zu seines Herrn Weib: "Sieh! Mein Herr kümmert sich bei mir um nichts im Hause; all sein Eigentum hat er mir übergeben.',
        9: 'Niemand ist in diesem Hause größer als ich. Gar nichts hat er mir vorenthalten als dich, weil du sein Weib bist. Wie sollte ich nun dieses schwere Unrecht tun, daß ich mich wider Gott versündigte?"',
        10: 'Sie redete aber Tag für Tag auf Joseph ein. Er aber war ihr nicht zu Willen, sich zu ihr zu legen und mit ihr beisammen zu sein.',
        11: 'Da geschah es an einem solchen Tage, daß er ins Haus kam, seine Arbeit zu tun; vom Hausgesinde aber war keines dort im Gemach.',
        12: 'Da packte sie ihn am Gewand und sprach: "Leg dich zu mir!" Er aber ließ sein Gewand in ihrer Hand und floh hinaus ins Freie.',
        13: 'Als sie sah, daß er sein Gewand in ihrer Hand gelassen und ins Freie geflohen war,',
        14: 'rief sie ihr Hausgesinde herbei und sprach zu ihm: "Seht! Da hat man uns einen hebräischen Mann gebracht, daß er seinen Mutwillen mit uns treibe. Er kam zu mir herein und wollte sich zu mir legen; da schrie ich laut.',
        15: 'Wie er aber hörte, daß ich lautes Geschrei erhob, ließ er sein Kleid bei mir, floh und lief ins Freie."',
        16: 'Und sie legte sein Gewand neben sich, bis sein Herr heimkäme.',
        17: 'Da berichtete sie ihm das gleiche und sprach: "Kommt da der hebräische Sklave, den du uns hergebracht, zu mir herein und will seinen Mutwillen mit mir treiben.',
        18: 'Wie ich aber laut schrie, ließ er sein Kleid bei mir und floh ins Freie."',
        19: 'Als der Herr seines Weibes Erzählung vernahm, die sie ihm vorgetragen: "Also hat dein Sklave mir getan", da ward er sehr zornig.',
        20: 'Und Josephs Herr ließ ihn ergreifen und ins Gefängnis werfen, dahin, wo die Königsgefangenen saßen. Und so lag er dort im Kerker.',
        21: 'Aber der Herr war mit Joseph und wandte ihm Huld zu. Er verschaffte ihm die Gunst des Oberkerkermeisters.',
        22: 'Und der Oberkerkermeister vertraute Joseph alle Gefangenen im Kerker an, und alles, was man dort zu tun hatte, besorgte er.',
        23: 'Der Oberkerkermeister aber kümmerte sich um gar nichts, was durch jenen geschah, weil der Herr mit ihm war und der Herr alles, was er vornahm, gelingen ließ.',
    },
    40: {
        1: 'Nach jenen Begebnissen geschah es, daß sich des ägyptischen Königs Mundschenk und Bäcker gegen ihren Herrn, den König von Ägypten, vergingen.',
        2: 'Und Pharao ergrimmte über seine beiden Hofleute, über den Obermundschenk und den Oberbäcker.',
        3: 'Er ließ sie in Gewahrsam legen, ins Haus des Anführers der Leibwache, in den Kerker, an die Stätte, wo Joseph gefangen saß.',
        4: 'Und der Anführer der Leibwächter gab ihnen Joseph bei, sie zu bedienen. So blieben sie längere Zeit im Gewahrsam.',
        5: 'Da träumten beide in der gleichen Nacht, und zwar jeder einen besonderen Traum, des ägyptischen Königs Mundschenk und Bäcker, die im Kerker saßen.',
        6: 'Am Morgen kam Joseph zu ihnen und sah sie an. Da waren sie verstimmt.',
        7: 'Da fragte er des Pharaos Höflinge, die mit ihm im Gewahrsam in seines Herrn Haus waren: "Warum macht ihr heute solch böse Gesichter?"',
        8: 'Sie sprachen zu ihm: "Wir haben einen Traum gehabt, und niemand ist da, der ihn deute." Da sprach Joseph zu ihnen: "Sind Deutungen nicht Gottes Sache? Erzählt mir doch!"',
        9: 'Da erzählte der Obermundschenk dem Joseph seinen Traum und sprach zu ihm: "In meinem Traume stand vor mir ein Weinstock.',
        10: 'Und am Weinstock sind drei Ranken. Er schlägt aus; dann kommt er zum Blühen, und schon tragen seine Kämme reife Trauben.',
        11: 'Ich aber habe Pharaos Becher in der Hand, nehme die Trauben, presse sie in Pharaos Becher aus und gebe den Becher dem Pharao in die Hand."',
        12: 'Da sprach Joseph zu ihm: "Dies ist seine Deutung: Drei Ranken sind drei Tage.',
        13: 'Drei Tage noch, dann nimmt dich Pharao persönlich vor und stellt dich wieder auf deinen Posten, und du reichst Pharao wieder den Becher, ganz wie früher, als du sein Mundschenk gewesen.',
        14: 'Denkst du also an mich, wenn es dir wieder gut geht, dann habe die Güte, mich beim Pharao zu empfehlen und mir so aus diesem Hause zu helfen!',
        15: 'Denn aus der Hebräer Land bin ich entführt worden, und auch hier habe ich nichts verbrochen, daß sie mich in den Kerker werfen mußten."',
        16: 'Als der Oberbäcker bemerkte, daß er zum Guten ausgelegt, sprach er zu Joseph: "In meinem Traume waren auf meinem Kopf drei geflochtene Körbe.',
        17: 'Im obersten der Körbe waren allerlei Eßwaren für den Pharao, Backwerk; jedoch die Vögel fraßen es aus dem Korb auf meinem Kopfe weg."',
        18: 'Da erwiderte Joseph und sprach: "Dies ist die Deutung: Drei Körbe sind drei Tage.',
        19: 'Drei Tage noch, dann nimmt dich der Pharao persönlich in deiner Sache vor; dann hängt er dich an das Holz, und dann fressen die Vögel dein Fleisch von dir ab."',
        20: 'Am dritten Tage war es, dem Geburtstag Pharaos; da bereitete er ein Mahl für alle seine Diener. Dabei nahm er den Obermundschenk und den Oberbäcker im Beisein seiner Diener persönlich vor.',
        21: 'Da setzte er den Obermundschenk wieder zu seinem Mundschenk ein, und er durfte Pharao den Becher wieder reichen.',
        22: 'Den Oberbäcker aber ließ er hängen, wie ihnen Joseph vorhergesagt.',
        23: 'Der Obermundschenk aber gedachte nicht mehr Josephs. Er vergaß ihn.',
    },
    41: {
        1: 'Nach Verlauf zweier Jahre träumte Pharao, er stehe am Nil.',
        2: 'Da stiegen aus dem Nil sieben Kühe, prächtig von Aussehen und fett an Fleisch, und weideten im Riedgras.',
        3: 'Ihnen nach stiegen sieben andere Kühe aus dem Nil, häßlich von Aussehen und mager an Fleisch, und traten neben jene Kühe am Nilufer.',
        4: 'Dann fraßen die häßlichen und mageren Kühe die sieben stattlichen und fetten Kühe. Da erwachte Pharao.',
        5: 'Er schlief wieder ein, da träumte er zum zweitenmal. Sieben Ähren wuchsen an einem Halm, dick und schön.',
        6: 'Ihnen nach sproßten sieben Ähren, dürr und vom Ostwind versengt.',
        7: 'Und die dürren Ähren verschlangen die sieben dicken und vollen Ähren. Da erwachte Pharao; ein Traum war es gewesen.',
        8: 'Am Morgen aber war sein Gemüt noch unruhig; da sandte er hin und ließ alle Schriftkundigen und Weisen Ägyptens rufen. Und Pharao erzählte ihnen seine Träume; aber niemand vermochte sie dem Pharao zu deuten.',
        9: 'Da nahm der Obermundschenk das Wort und sprach zu Pharao: "Heute muß ich meiner Nachlässigkeit gedenken.',
        10: 'Der Pharao hatte einst auf seine Diener gezürnt, und so legte er mich in Gewahrsam in das Haus des Anführers der Leibwächter, mich und den Oberbäcker.',
        11: 'Da träumten wir beide in einer Nacht, und zwar hatte jeder einen besonderen Traum.',
        12: 'Nun war bei uns dort ein hebräischer Jüngling, ein Sklave des Obersten der Leibwächter, und dem erzählten wir es, und jener deutete uns unsere Träume. Jedem deutete er, seinem Traum gemäß.',
        13: 'Und wie er es uns gedeutet, so traf es ein. Mich hat man wieder auf meinen Posten gestellt, und ihn hat man gehenkt."',
        14: 'Da sandte Pharao und ließ Joseph rufen. Eilends entließen sie ihn aus dem Kerker. Er ließ sich scheren und wechselte seine Kleider. Dann kam er zu Pharao.',
        15: 'Und Pharao sprach nun zu Joseph: "Ich habe einen Traum gehabt, und niemand kann ihn deuten. Nun habe ich von dir gehört, man sage, du brauchtest einen Traum nur zu hören, und du könntest ihn deuten!"',
        16: 'Da erwiderte Joseph dem Pharao also: "Ich nicht; Gott nur kann offenbaren, was Pharao frommt."',
        17: 'Da erzählte Pharao dem Joseph: "In meinem Traume stand ich an des Niles Ufer.',
        18: 'Da stiegen sieben Kühe aus dem Nil, fett an Fleisch und stattlich anzusehen, und weideten im Riedgras.',
        19: 'Ihnen nach stiegen sieben andere Kühe, elend und häßlich an Gestalt und mager an Fleisch. In ganz Ägypten habe ich nie etwas so Häßliches gesehen wie sie.',
        20: 'Da fraßen die mageren und häßlichen Kühe die ersten sieben fetten Kühe.',
        21: 'Sie kamen so in ihren Magen; aber man hatte gar nicht gemerkt, daß sie in ihren Magen gekommen waren; denn ihr Aussehen blieb häßlich, wie zuvor. Da erwachte ich.',
        22: 'Und wieder sah ich in meinem Traum: Da wuchsen sieben Ähren voll und schön an einem Halm.',
        23: 'Ihnen nach sproßten sieben andere Ähren, taub, dürr und vom Ostwind versengt.',
        24: 'Und diese dürren Ähren verschlangen die sieben schönen Ähren. Ich sagte es den Schriftgelehrten; aber keiner konnte mir Bescheid geben."',
        25: 'Da sprach Joseph zu Pharao: "Pharaos Traum ist unzweideutig. Gott tut dem Pharao kund, was er zu tun gedenkt.',
        26: 'Die sieben schönen Kühe sind sieben Jahre. Die sieben schönen Ähren sind auch sieben Jahre. Nur ein Traum ist es.',
        27: 'Und diese sieben mageren und häßlichen Kühe, die nach ihnen kamen, sind sieben Jahre, und die sieben leeren, vom Ostwind versengten Ähren bedeuten sieben Hungerjahre.',
        28: "Das ist dasselbe, was ich Pharao schon sagte: 'Was Gott zu tun gedenkt, hat er Pharao schauen lassen.'",
        29: 'Sieh, sieben Jahre kommen, da herrscht großer Überfluß im ganzen Land Ägypten.',
        30: 'Nach ihnen kommen sieben Hungerjahre. Da weiß man nichts mehr von irgendwelchem Überfluß im Land Ägypten. Dann zehrt der Hunger im Land.',
        31: 'Dann merkt man nichts mehr vom Überfluß im Land wegen dieser Hungersnot hernach; denn sie wird überschwer sein.',
        32: 'Und daß der Traum des Pharao zweimal in verschiedener Form erschien, heißt: Die Sache ist fest bei Gott beschlossen, und Gott setzt eilends sie ins Werk.',
        33: 'Nun ersehe sich Pharao einen klugen, weisen Mann und setze ihn über das Ägypterland!',
        34: 'Möge Pharao unverzüglich über das Land Aufseher setzen und dann den fünften Teil aus dem Land Ägypten in den sieben Jahren des Überflusses als Abgabe erheben.',
        35: 'Dann soll man jeglich Korn dieser kommenden guten Jahre aufspeichern und Getreide zu Pharaos Verfügung in den Städten zur Nahrung anhäufen und verwahren!',
        36: 'Dann ist das Korn dem Land ein Rückhalt für die sieben Hungerjahre, die über das Ägypterland kommen, damit das Land durch die Hungersnot nicht zugrunde gehe."',
        37: 'Diese Rede gefiel nun Pharao und all seinen Dienern.',
        38: 'Und Pharao sprach zu seinen Dienern: "Könnten wir jemanden wie diesen finden, einen Mann, in dem Gottes Geist ist?"',
        39: 'Und Pharao sprach zu Joseph: "Weil ein Gott dir all dies geoffenbart, ist keiner so klug und weise wie du.',
        40: 'Du sollst meinem Hause vorstehen! Mein ganzes Volk soll deine Rede achten! Nur um den Thron will ich größer sein als du."',
        41: 'Dann sprach Pharao zu Joseph: "Siehe! Ich setze dich über ganz Ägypterland."',
        42: 'Dann zog Pharao seinen Siegelring von seiner Hand und streifte ihn an Josephs Hand, kleidete ihn mit Linnengewändern und legte ihm die goldene Kette um den Hals.',
        43: 'Dann ließ er ihn auf seinem Wagen zweiten Ranges fahren und vor ihm ausrufen: Abrek! und daß man ihn einsetze als König über ganz Ägypterland.',
        44: 'Und Pharao sprach zu Joseph: "Ich bin Pharao. Aber ohne dich hebe niemand Hand noch Fuß in ganz Ägypterland!"',
        45: 'Und Pharao hieß Joseph Saphnat Paneach. Und er gab ihm zum Weibe Asenat, die Tochter Potipheras, des Priesters von On. So ward Joseph im Ägypterland bekannt.',
        46: 'Joseph war dreißig Jahre alt, als er in des ägyptischen Königs Pharao Dienste trat. Nachdem Joseph von Pharao weggegangen war, durchzog er ganz Ägypterland.',
        47: 'Das Land war nun in den sieben Jahren des Überflusses überaus fruchtbar.',
        48: 'So speicherte er jegliches Korn der sieben Jahre im Ägypterland auf und legte Korn in die Städte. In jede Stadt legte er das Korn des Feldes, das sie umgab.',
        49: 'So häufte Joseph Getreide wie Sand am Meere überaus viel auf, bis man das Messen lassen mußte; denn es war unmeßbar.',
        50: 'Zwei Söhne aber waren Joseph geboren worden, bevor das Hungerjahr kam. Asenat, die Tochter Potipheras, des Priesters von On, hatte sie ihm geboren.',
        51: 'Und Joseph nannte den Erstgeborenen Manasse; denn "Gott hat mich vergessen lassen all mein Unglück und mein ganzes Haus".',
        52: 'Den zweiten nannte er Ephraim; denn "Gott hat mich zur Macht im Lande meines Elends kommen lassen".',
        53: 'Zu Ende gingen nun die sieben Jahre des Überflusses im Ägypterland.',
        54: 'Und die sieben Jahre des Hungers hoben an, wie Joseph gesagt hatte. Hunger war in allen Ländern; aber in ganz Ägypten gab es Brot.',
        55: 'Als aber auch ganz Ägypterland hungerte, schrie das Volk zu Pharao um Brot; da sprach Pharao zu jedem Ägypter: "Geht zu Joseph! Was er euch sagen wird, tut!"',
        56: 'Nun kam der Hunger über die ganze Erde. Da öffnete Joseph alle Speicher und verkaufte den Ägyptern Getreide. Aber auch in Ägypten ward der Hunger immer stärker.',
        57: 'Alle Welt kam nun nach Ägypten, Getreide bei Joseph zu kaufen, denn stark war der Hunger auf der ganzen Erde geworden.',
    },
    42: {
        1: 'Auch Jakob erfuhr, daß es in Ägypten Brotgetreide gebe; da sprach Jakob zu seinen Söhnen: "Warum zögert ihr?"',
        2: 'Und er sprach: "Ich habe gehört, daß in Ägypten ein Kornmarkt ist. Ziehet dorthin und holt uns von dort Getreide, daß wir am Leben bleiben und nicht sterben!"',
        3: 'Da zogen zehn der Brüder Josephs hinab, in Ägypten Getreide zu kaufen.',
        4: 'Den Benjamin aber, Josephs Vollbruder, hatte Jakob nicht mit seinen Brüdern ziehen lassen; denn er dachte, ihn könnte ein Unfall treffen.',
        5: 'So kamen Israels Söhne zum Markt inmitten der Herbeiströmenden; denn im Lande Kanaan war der Hunger.',
        6: 'Joseph aber war der Gebieter des Landes; er war es, der jedem Volk der Erde Getreide verkaufte. So kamen auch Josephs Brüder und neigten sich vor ihm zu Boden.',
        7: 'Da sah Joseph seine Brüder und erkannte sie; aber er stellte sich fremd gegen sie, ließ sie hart an und fragte sie: "Woher kommt ihr?" Sie sagten: "Aus dem Lande Kanaan zum Getreidekauf."',
        8: 'Joseph erkannte seine Brüder; sie aber hatten ihn nicht erkannt.',
        9: 'Da gedachte Joseph der Träume, die er ihretwegen gehabt. Er sprach zu ihnen: "Spione seid ihr. Ihr seid gekommen, die Blöße des Landes zu erspähen."',
        10: 'Sie sprachen zu ihm: "Nein, Herr! Mundvorrat zu kaufen, sind deine Sklaven gekommen.',
        11: 'Wir alle sind eines Mannes Söhne. Wir sind ehrlich. Niemals waren deine Knechte Spione."',
        12: 'Er sprach zu ihnen: "Nichts da! Die Blöße des Landes zu erspähen, seid ihr gekommen."',
        13: 'Sie sprachen: "Deiner Sklaven sind es zwölf, lauter Brüder, Söhne eines gewissen Mannes im Lande Kanaan. Der jüngste aber ist jetzt noch bei unserem Vater, und einer ist nicht mehr."',
        14: 'Da sprach Joseph zu ihnen: "Dabei bleibt es, was ich zu euch gesagt: Spione seid ihr.',
        15: 'Daran sollt ihr geprüft werden. Beim Leben Pharaos! Ihr dürft nicht eher von hier fort, bis euer jüngster Bruder herkommt.',
        16: 'Schicket von euch einen, daß er euren Bruder hole! Ihr aber bleibt gefangen. So werden eure Aussagen geprüft, ob Wahrheit bei euch ist oder nicht. Beim Leben Pharaos! Ihr seid Spione."',
        17: 'Und er ließ sie drei Tage in Gewahrsam legen.',
        18: 'Am dritten Tage sprach Joseph zu ihnen: "Tut dies, dann bleibt ihr am Leben! Denn ich bin gottesfürchtig:',
        19: 'Seid ihr ehrliche Leute, so bleibe von euch einer im Hause, darin ihr in Gewahrsam wart! Ihr anderen aber geht und bringt Korn für den Hunger eurer Familien heim!',
        20: 'Euren jüngsten Bruder aber müßt ihr mir bringen, daß sich eure Worte bewahrheiten und ihr nicht sterben müßt! Tut also!"',
        21: 'Da sprachen sie zueinander: "Leider haben wir dies an unserem Bruder verschuldet. Wir haben seine Angst gesehen, wie er uns anflehte, und wir haben nicht darauf geachtet. Deshalb ist diese Not über uns gekommen."',
        22: 'Da antwortete ihnen Ruben und sprach: "Habe ich euch nicht gesagt: \'Versündigt euch nicht an dem Kinde!\' Ihr aber habt nicht gehört. Nun wird sein Blut gefordert."',
        23: 'Sie aber wußten nicht, daß Joseph zuhörte; denn der Dolmetscher war zwischen ihnen.',
        24: 'Und er wandte sich von ihnen und weinte. Dann wandte er sich ihnen zu und redete mit ihnen. Hierauf ließ er Simeon aus ihrer Mitte greifen und vor ihren Augen fesseln.',
        25: 'Joseph befahl aber, ihre Geräte mit Korn zu füllen und jedem sein Geld wieder in seinen Sack zu legen und ihnen Zehrung auf den Weg zu geben. Man tat so.',
        26: 'Sie luden nun ihr Korn auf ihre Esel und zogen von dannen.',
        27: 'Da öffnete der eine seinen Sack, um seinen Esel in der Herberge zu füttern, und erblickte sein Geld. Obenan lag es in seinem Sack.',
        28: 'Da sprach er zu seinen Brüdern: "Mein Geld ist wieder da. Hier liegt es in meinem Sack." Da entsank ihnen der Mut, und bebend sahen sie einander an und sprachen: "Was hat uns Gott da getan?"',
        29: 'Und sie kamen zu ihrem Vater Jakob ins Land Kanaan und berichteten ihm alles, was ihnen begegnet war, und sprachen:',
        30: '"Hart hat uns der Mann, der Herr des Landes, angelassen; er stellte uns hin wie Auskundschafter seines Landes."',
        31: 'Wir sagten ihm: "Wir sind ehrliche Leute; nie waren wir Spione.',
        32: 'Zwölf Brüder sind wir, lauter Söhne unseres Vaters. Einer ist nicht mehr. Der jüngste aber ist jetzt noch bei unserem Vater im Lande Kanaan.',
        33: "Aber der Mann, der Herr des Landes, sprach zu uns: 'Daran werde ich erkennen, ob ihr ehrliche Leute seid: Laßt einen von euch Brüdern hier bei mir! Den Bedarf für den Hunger eurer Familien nehmt mit und zieht ab!",
        34: 'Doch bringt mir euren jüngsten Bruder, daß ich erkenne, daß ihr keine Spione seid, sondern ehrliche Leute! Ich werde euch dann euren Bruder zurückgeben, und ihr dürft im Lande umherziehen!\'"',
        35: 'Wie sie nun ihre Säcke leerten, war eines jeden Geldbeutel in seinem Sack. Sie erblickten samt ihrem Vater ihre Geldbeutel und erschraken.',
        36: 'Da sprach ihr Vater Jakob zu ihnen: "Ihr beraubt mich der Kinder! Joseph ist nicht mehr, Simeon nicht mehr. Nun wollt ihr Benjamin fortnehmen. Über mich kommt alles."',
        37: 'Da sprach Ruben zu seinem Vater: "Töte meine beiden Söhne, wenn ich ihn nicht zurückbringe! Vertraue ihn mir an! Ich bringe ihn dir wieder."',
        38: 'Er sprach: "Niemals darf mein Sohn mit euch reisen. Denn sein Bruder ist tot; er allein ist übrig. Träfe ihn ein Leid auf dem Weg, den ihr ziehen müßt, so senktet ihr mein graues Haupt mit Kummer in die Unterwelt."',
    },
    43: {
        1: 'Der Hunger aber lag schwer auf der Erde.',
        2: 'Als sie nun das aus Ägypten gebrachte Korn aufgezehrt hatten, sprach ihr Vater zu ihnen: "Geht noch einmal, ein wenig Korn für uns zu kaufen!"',
        3: 'Da sprach Juda zu ihm: "Nachdrücklich hat uns der Mann eingeschärft: \'Ihr dürft mir nicht mehr vor die Augen kommen, euer Bruder sei denn bei euch.\'',
        4: 'Willst du also unseren Bruder mitgeben, dann ziehen wir hinab und kaufen Korn.',
        5: 'Gibst du ihn aber uns nicht mit, dann ziehen wir nicht hinab. Der Mann hat ja zu uns gesagt: \'Ihr dürft mir nicht vor die Augen kommen, euer Bruder sei denn bei euch.\'"',
        6: 'Da sprach Israel: "Warum habt ihr es mir zu Leid getan, dem Manne zu verraten, daß ihr noch einen Bruder habt?"',
        7: 'Da sprachen sie: "Der Mann erkundigte sich genau nach uns und unserer Familie. Er sprach: \'Ist euer Vater noch am Leben? Habt ihr noch einen Bruder?\' Da gaben wir ihm Bescheid, wie es sich verhält. Konnten wir denn wissen, daß er sagen würde: \'Bringt euren Bruder her?\'"',
        8: 'Da sprach Juda zu seinem Vater Israel: "Gib mir den Knaben mit! Dann brechen wir auf und gehen und bleiben am Leben und müssen nicht sterben, wir so gut wie du und unsere Kinder.',
        9: 'Ich bürge für ihn. Fordere ihn von nur! Bringe ich ihn dir nicht und stelle ihn dir nicht vor Augen, so will ich lebenslang vor dir schuldig sein.',
        10: 'Hätten wir nicht allzulange gezaudert, wir wären schon zweimal zurück."',
        11: 'Da sprach ihr Vater Israel zu ihnen: "Muß es sein, so tut dies: Nehmt vom feinsten Landeserzeugnis in euer Gepäck und bringt es als Geschenk dem Manne hinab, etwas Balsam, etwas Honig, Spezereien, Ladanum, Pistazien und Mandeln!',
        12: 'Nehmt noch einmal soviel Geld mit euch! Auch das Geld oben in euren Säcken müßt ihr wieder mitnehmen. Vielleicht war es ein Versehen.',
        13: 'Auch euren Bruder nehmt mit! Auf! Zieht wieder zu dem Manne!',
        14: 'Gott, der Allmächtige, schenke euch Erbarmen bei dem Manne, daß er euren anderen Bruder euch freigebe, desgleichen Benjamin! Ich aber! Nun, dann bin ich eben kinderlos."',
        15: 'So nahmen die Männer jenes Geschenk; auch den doppelten Geldbetrag nahmen sie mit, dazu Benjamin, brachen auf, zogen nach Ägypten und traten vor Joseph.',
        16: 'Und Joseph sah bei ihnen den Benjamin. Da sprach er zu seinem Hausverwalter: "Führe die Männer ins Haus, und man schlachte ein Stück Vieh und richte es her! Die Männer sollen mittags bei mir speisen!"',
        17: 'Und der Mann tat, wie Joseph gesagt. Und der Mann führte die Männer in Josephs Haus.',
        18: 'Aber die Männer fürchteten sich, weil sie in Josephs Haus geführt wurden, und sprachen: "Des Geldes wegen, das beim vorigen Male wieder in unsere Säcke geriet, werden wir hereingebracht. Man will einen Vorwand gegen uns haben, uns überwältigen und uns als Sklaven behalten, samt unseren Eseln."',
        19: 'So traten sie zu dem Manne, der Josephs Haus verwaltete, und redeten ihn an der Hauspforte an.',
        20: 'Sie sprachen: "Bitte, mein Herr! Wir sind schon einmal hierher gereist, Korn zu kaufen.',
        21: 'Als wir danach in die Herberge kamen und unsere Säcke öffneten, da lag eines jeden Geld oben in seinem Sack, unser Geld nach seinem Vollgewicht. Nun bringen wir es eigenhändig zurück.',
        22: 'Wir bringen auch anderes Geld, um Korn zu kaufen. Wir wissen nicht, wer unser Geld in unsere Säcke gelegt hat."',
        23: 'Er sprach: "Beruhigt euch! Fürchtet euch nicht! Euer und eures Vaters Gott hat euch heimlich einen Schatz in eure Säcke gelegt. Euer Geld ist mir zugekommen." Dann gab er ihnen Simeon heraus.',
        24: 'Darauf führte der Mann die Männer in Josephs Haus und brachte Wasser, daß sie sich die Füße wuschen, und ihren Eseln gab er Futter.',
        25: 'Sie aber legten das Geschenk zurecht, bis Joseph mittags käme; denn sie hatten gehört, daß sie dort das Mahl einnehmen sollten.',
        26: 'Joseph trat nun ein; da überreichten sie ihm das Geschenk, das sie bei sich hatten, und neigten sich vor ihm bis zur Erde.',
        27: 'Er fragte nach ihrem Befinden und sprach: "Wie geht es eurem alten Vater, von dem ihr gesprochen? Lebt er noch?"',
        28: 'Sie sprachen: "Gut geht es deinem Diener, unserem Vater: Er lebt noch." Dabei bückten und verneigten sie sich.',
        29: 'Wie er aber seine Augen erhob, erblickte er seinen Vollbruder Benjamin. Da sprach er: "Ist das euer jüngster Bruder, von dem ihr zu mir gesprochen?" Dann sprach er: "Gott gebe dir Huld, mein Sohn!"',
        30: 'Joseph aber brach schnell ab; denn sein Herz brannte nach seinem Bruder, und er ward zu Tränen gerührt. So ging er in das innere Gemach und weinte dort.',
        31: 'Dann wusch er sein Antlitz, trat hervor, hielt an sich und sprach: "Tragt das Mahl auf!"',
        32: 'Da trug man ihm und jenen besonders auf, ebenso den Ägyptern, die mit ihm speisten. Denn die Ägypter dürfen nicht mit den Hebräern zusammen speisen; das ist für die Ägypter ein Greuel.',
        33: 'Sie saßen aber nach seiner Weisung, vom Ältesten bis zum Jüngsten genau nach dem Alter geordnet. Staunend sahen sich die Männer an.',
        34: 'Er aber ließ von sich zu ihnen Gerichte hinüberbringen; Benjamins Gericht war dabei fünfmal größer als ihrer aller Gerichte. Dann tranken sie und wurden bei ihm guter Dinge.',
    },
    44: {
        1: 'Hierauf gebot er seinem Hausverwalter: "Fülle die Säcke der Männer mit Korn, soviel sie tragen können, und leg eines jeden Geld oben in seinen Sack!',
        2: 'Und meinen silbernen Becher leg oben in den Sack des jüngsten samt dem Geld für sein Getreide!" Er tat so, wie Joseph gesagt.',
        3: 'Als der Morgen anbrach, entließ man die Männer mit ihren Eseln.',
        4: 'Eben waren sie zur Stadt hinausgegangen, noch nicht weit, da sprach Joseph zu seinem Hausverwalter: "Auf! Jag den Männern nach! Holst du sie ein, dann sprich zu ihnen: \'Warum vergeltet ihr Gutes mit Bösem?',
        5: 'Ist es nicht der Becher, aus dem mein Herr trinkt und weissagt? Ihr habt übel daran getan, daß ihr so gehandelt.\'"',
        6: 'Er holte sie ein und redete also zu ihnen.',
        7: 'Sie sprachen zu ihm: "Warum spricht mein Herr solcherlei? Ferne sei es deinen Sklaven, so etwas zu tun!',
        8: 'Haben wir doch das Geld, das wir in unseren Säcken oben fanden, dir aus dem Lande Kanaan zurückgebracht. Wie sollten wir aus deines Herren Haus Silber oder Gold stehlen?',
        9: 'Bei wem von deinen Sklaven er sich findet, der soll sterben! Wir anderen wollen meinem Herrn leibeigen sein!"',
        10: 'Da sprach er: "So sollte es eigentlich sein, wie ihr sagt. Doch soll nur der, bei dem er sich findet, mir leibeigen sein; ihr anderen aber geht frei aus."',
        11: 'Da ließ jeder eilends seinen Sack zur Erde und öffnete seinen Sack.',
        12: 'Er aber fing zu suchen an. Beim Ältesten hatte er angefangen und endete beim jüngsten. Da fand sich der Becher in Benjamins Sack.',
        13: 'Darauf zerrissen sie ihre Kleider, beluden jeder seinen Esel und kehrten in die Stadt zurück.',
        14: 'So kam Juda mit seinen Brüdern in Josephs Haus; dieser aber war noch dort, und sie fielen vor ihm zu Boden.',
        15: 'Joseph aber sprach zu ihnen: "Was ist das für eine Tat, die ihr getan? Habt ihr nicht gewußt, daß ein Mann wie ich richtig ahnen kann?"',
        16: 'Da sprach Juda: "Was sollen wir meinem Herrn sagen? Was reden? Wie uns rechtfertigen? Gott hat die Schuld deiner Sklaven gefunden. Wir sind jetzt Sklaven unseres Herrn, wir so gut wie der, bei dem sich der Becher gefunden hat."',
        17: 'Er sprach: "Ferne sei es nur, das zu tun! Der Mann, bei dem sich der Becher gefunden hat, soll allein mir leibeigen sein. Ihr anderen aber zieht in Frieden zu eurem Vater!"',
        18: 'Da trat Juda zu ihm und sprach: "Bitte, mein Herr! Möchte dein Sklave ein Wort an meinen Herrn richten dürfen, ohne daß dein Zorn gegen deinen Sklaven entbrenne! Du bist ja wie Pharao.',
        19: "Mein Herr hat seine Sklaven gefragt: 'Habt ihr noch einen Vater oder einen Bruder?'",
        20: "Da sagten wir zu meinem Herrn: 'Wir haben noch einen alten Vater. Ein kleiner, spätgeborener Sohn ist auch da. Sein Bruder aber ist tot, und so ist er allein von seiner Mutter übrig und ist seines Vaters Liebling.'",
        21: "Du sprachst zu deinen Sklaven: 'Bringt ihn zu mir herab, damit ich ihn mit eigenen Augen sehe!'",
        22: "Da sprachen wir zu meinem Herrn: 'Der Knabe kann seinen Vater nicht verlassen; denn verließe er seinen Vater, so stürbe dieser.'",
        23: "Du aber sprachest zu deinen Sklaven: 'Kommt euer jüngster Bruder nicht mit euch herab, dann dürft ihr nimmermehr mein Antlitz schauen.'",
        24: 'Als wir zu deinem Sklaven, unserem Vater, hinaufgezogen, berichteten wir ihm meines Herrn Wort.',
        25: "Da sprach unser Vater: 'Kauft uns nochmals etwas Korn.'",
        26: "Da sagten wir: 'Wir können nicht hinabziehen; nur wenn unser jüngster Bruder mit uns geht, ziehen wir hinab. Wir dürfen ja dem Manne nicht mehr unter die Augen kommen, ist unser jüngster Bruder nicht bei uns.'",
        27: "Da sprach zu uns dein Sklave, mein Vater: 'Ihr wißt: Mein Weib hat mir zwei Söhne geboren.",
        28: 'Der eine ist von mir gegangen. Ich sagte mir: Sicherlich ist er zerrissen worden. Bis heute habe ich ihn nicht mehr gesehen.',
        29: "Nehmt ihr mir auch diesen weg und träfe ihn ein Leid, dann senktet ihr mein graues Haar im Leid zur Unterwelt.'",
        30: 'Und nun, komme ich zu deinem Sklaven, meinem Vater, und ist der Knabe nicht bei uns, an dem seine Seele hängt,',
        31: 'dann stürbe er, sobald er sieht, der Knabe ist nicht mehr da, und deine Sklaven senkten deines Sklaven, unseres Vaters, graues Haar in Jammer zur Unterwelt.',
        32: "Weil sich dein Sklave für den Knaben meinem Vater so verbürgt hat: 'Wenn ich ihn dir nicht bringe, dann will ich lebenslang vor meinem Vater schuldig sein',",
        33: 'so möchte dein Sklave an des Knaben Statt bleiben, als meines Herren Leibeigener! Der Knabe aber ziehe mit seinen Brüdern hinauf.',
        34: 'Wie könnte ich zu meinem Vater ziehen ohne den Knaben bei mir? Nie könnte ich das Leid ansehen, das meinen Vater überkäme."',
    },
    45: {
        1: 'Da konnte Joseph nicht länger an sich halten, trotz allen Umstehenden. Er rief: "Schafft jedermann von mir hinaus!" Und so war niemand bei ihm, als sich Joseph seinen Brüdern zu erkennen gab.',
        2: 'Er brach in lautes Weinen aus, daß es einige Ägypter hörten; auch Pharaos Haus vernahm davon.',
        3: 'Dann sprach Joseph zu seinen Brüdern: "Ich bin Joseph. Lebt mein Vater noch?" Da konnten ihm seine Brüder keine Antwort geben; so bestürzt standen sie vor ihm.',
        4: 'Da sprach Joseph zu seinen Brüdern: "Tretet zu mir her!" Und sie traten näher. Er sprach: "Ich bin euer Bruder Joseph, den ihr nach Ägypten verkauft habt.',
        5: 'Nun aber grämt euch nicht! Nicht dünke es euch peinlich, daß ihr mich hierher verkauft habt! Denn zur Erhaltung eures Lebens hat mich Gott euch vorausgesandt.',
        6: 'Zwei Jahre schon ist der Hunger im Lande, noch aber kommen fünf Jahre, wo nicht Pflügen noch Ernten ist.',
        7: 'So hat mich Gott euch vorausgesandt, euch eine Zuflucht auf Erden zu schaffen, euch am Leben zu erhalten in wunderbarer Rettung.',
        8: 'Somit habt nicht ihr mich hierhergesandt, sondern Gott. Er machte mich für Pharao zu einem Vater, zum Herrn für sein ganzes Haus und zum Gebieter über ganz Ägypterland.',
        9: "Zieht eilends zu meinem Vater hinauf! Dann sageet ihm: 'So spricht dein Sohn Joseph: Gott hat mich zum Herrn über ganz Ägypten gesetzt. Komm herab zu mir und säume nicht!",
        10: 'Dann läßt du dich im Lande Gosen nieder und bleibst in meiner Nähe, du, deine Söhne, deine Enkel, deine Schafe, deine Rinder und alles, was dein ist!',
        11: "Und ich versorge dich dort; denn noch fünf Jahre währt der Hunger, daß du nicht verkümmerst mit deinem Haus und allem, was dein ist.'",
        12: 'Ihr seht es mit eigenen Augen, auch mein Bruder Benjamin, daß ich es bin, der zu euch spricht.',
        13: 'Dann meldet meinem Vater all meine Ehre in Ägypten und alles, was ihr geschaut! Dann bringt ihr eilends meinen Vater hierher."',
        14: 'Und er fiel seinem Bruder Benjamin um den Hals und weinte; auch Benjamin weinte an seinem Hals.',
        15: 'Dann küßte er all seine Brüder und weinte an ihnen. Nun erst konnten seine Brüder mit ihm sprechen.',
        16: 'Und die Kunde drang in Pharaos Haus, indem man sprach: "Josephs Brüder sind gekommen." Und Pharao mit seinen Dienern war darüber erfreut.',
        17: 'Pharao sprach zu Joseph: "Sag deinen Brüdern: \'Tut also! Beladet eure Lasttiere und zieht ins Land Kanaan!',
        18: "Holt euren Vater sowie eure Familie und kommt zu mir! Ich gebe euch, was das Ägypterland Gutes bietet, und von des Landes Wohlstand sollt ihr genießen.'",
        19: "So bist du ermächtigt: 'Tut also! Nehmt aus Ägypterland euch Wagen für eure Kinder und Weiber mit! Dann laßt ihr euren Vater aufsteigen und kommt her.",
        20: 'Laßt\'s euch nicht leid sein um euren Hausrat! Denn was das ganze Land Ägypten Gutes bietet, soll euer Sein.\'"',
        21: 'Die Söhne Israels taten so. Und Joseph gab ihnen Wagen nach Pharaos Geheiß. Auch gab er ihnen Zehrung auf die Reise mit.',
        22: 'Allen aber, Mann für Mann, hatte er ein Ehrenkleid geschenkt; dem Benjamin aber hatte er 300 Silberlinge und fünf Ehrenkleider gegeben.',
        23: 'Ebenso sandte er seinem Vater zehn Esel, beladen mit Ägyptens bestem Gut, sowie zehn Eselinnen, beladen mit Korn, Brot und Reisekost für seinen Vater.',
        24: 'Dann entließ er seine Brüder, und sie zogen fort. Er sagte noch zu ihnen: "Säumt euch nicht auf dem Wege!"',
        25: 'So zogen sie aus Ägypten hinauf und kamen ins Land Kanaan zu ihrem Vater Jakob.',
        26: 'Und sie berichteten ihm: "Joseph lebt noch. Ja, er waltet über ganz Ägypterland." Da erstarrte sein Herz; denn er glaubte ihnen nicht.',
        27: 'Sie aber berichteten ihm alle Worte Josephs, die er an sie gerichtet. Er sah die Wagen, die Joseph gesandt, ihn hinzubringen. Da lebte der Geist ihres Vaters Jakob auf.',
        28: 'Und Israel sprach: "Genug! Mein Sohn Joseph lebt noch. Ich gehe hin und will ihn sehen, bevor ich sterbe."',
    },
    46: {
        1: 'So brach Israel mit all seiner Habe auf und kam nach Beerseba. Da brachte er dem Gott seines Vaters Isaak Opfer dar.',
        2: 'Und Gott sprach zu Israel in einem Nachtgesichte. Er sprach: "Jakob! Jakob!" Er sprach: "Hier bin ich."',
        3: 'Er sprach: "Ich bin Gott, der Schutzgott deines Vaters. Fürchte dich nicht; nach Ägypten zu ziehen! Denn dort mache ich dich zu einem großen Volke.',
        4: 'Ich selber ziehe mit dir nach Ägypten und ich selber führe dich wieder herauf. Und Joseph wird dir die Hand auf die Augen legen."',
        5: 'Da brach Jakob von Beerseba auf, und Israels Söhne hoben ihren Vater Jakob, ihre Kinder und Weiber auf die Wagen, die Pharao gesandt hatte, ihn zu holen.',
        6: 'Und sie nahmen ihre Herden mit und ihre Fahrnis, die sie im Lande Kanaan erworben hatten. So kam Jakob mit seiner ganzen Nachkommenschaft nach Ägypten.',
        7: 'Bei ihm waren seine Söhne und Enkel, ferner seine Töchter und Enkelinnen, brachte er doch seine ganze Nachkommenschaft mit sich nach Ägypten.',
        8: 'Dies sind die Namen der Söhne Israels, die nach Ägypten kamen, Jakobs und seiner Söhne: Jakobs Erstgeborener Ruben.',
        9: 'Rubens Söhne sind Chanok, Pallu, Chesron und Karmi.',
        10: 'Simeons Söhne sind Jemuel, Jamin, Ohad, Jakin und Sochar sowie der Kanaaniterin Sohn, Saul.',
        11: 'Levis Söhne sind Gerson, Kehat und Merari,',
        12: 'Judas Söhne sind Ger, Onan, Sela, Peres und Zerach; Ger und Onan aber starben schon im Lande Kanaan, und des Peres Söhne sind Chesron und Chamul.',
        13: 'Issakars Söhne sind Tola, Pua, Job und Simron.',
        14: 'Zabulons Söhne sind Sered, Elon und Jachleel.',
        15: 'Dies sind die Söhne der Lea, die sie Jakob zu Paddan Aram gebar, sowie seine Tochter Dina; alles zusammen 33 Söhne und Töchter.',
        16: 'Gads Söhne sind Siphjon, Chaggi, Suni, Esbon, Eri, Arodi und Areli.',
        17: 'Assers Söhne sind Jimna, Jisma, Jiswi, Beria sowie ihre Schwester Serach; Berias Söhne sind Cheber und Malkiel.',
        18: 'Dies sind die Söhne Zilpas, die Laban seiner Tochter Lea mitgegeben; sie hatte diese dem Jakob geboren, sechzehn Seelen.',
        19: 'Die Söhne Rachels, des Weibes Jakobs, sind Joseph und Benjamin.',
        20: 'Dem Joseph aber wurden im Land Ägypten Kinder geboren, die ihm Asenat, die Tochter Potipheras, des Priesters von On, gebar: Manasse und Ephraim.',
        21: 'Benjamins Söhne sind Bela, Beker, Asbel, Gera, Naaman, Echi, Nos, Muppim, Chuppim und Ard.',
        22: 'Dies sind Rachels Söhne, die dem Jakob geboren worden, zusammen vierzehn Seelen.',
        23: 'Dans Sohn ist Chusim.',
        24: 'Naphtalis Söhne sind Jachseel, Guni, Jeser und Sillem.',
        25: 'Dies sind die Söhne Bilhas, die Laban seiner Tochter Rachel mitgegeben; sie hatte diese dem Jakob geboren, zusammen sieben Seelen.',
        26: 'Aller Seelen, die mit Jakob nach Ägypten kamen, seine leiblichen Nachkommen, ohne die Weiber der Jakobssöhne, waren es sechsundsechzig.',
        27: 'Und der Söhne Josephs, die ihm in Ägypten geboren wurden, waren es zwei. Aller Seelen des Jakobshauses, die nach Ägypten kamen, waren es siebzig.',
        28: 'Nun sandte er Juda zu Joseph voraus, daß er vor ihm Gosen benachrichtige. Und sie kamen ins Land Gosen.',
        29: 'Da ließ Joseph seinen Wagen einspannen und fuhr hinauf nach Gosen, seinem Vater Israel entgegen. Als er vor ihm erschien, fiel er ihm um den Hals und weinte noch lange an seinem Hals.',
        30: 'Dann sprach Israel zu Joseph: "Jetzt sterbe ich gern, nachdem ich dein Antlitz gesehen und weiß, daß du lebst."',
        31: 'Joseph aber sprach zu seinen Brüdern und zu den anderen Hausgenossen seines Vaters: "Ich will vorauf, es Pharao melden und ihm sagen: \'Meine Brüder sowie meines Vaters Hausgenossen, die im Lande Kanaan waren, sind zu mir gekommen.',
        32: "Schafhirten aber sind diese Männer; denn Viehzüchter waren sie von je. Sie haben ihre Schafe, Rinder und alle ihre Habe mitgebracht.'",
        33: "Wenn euch nun Pharao rufen läßt und spricht: 'Was ist euer Gewerbe?',",
        34: 'dann sagt: \'Von Jugend auf bis heute sind deine Sklaven Viehzüchter gewesen, wir wie auch unsere Väter\', damit ihr im Lande Gosen bleiben dürft; denn jeder Schafhirte ist den Ägyptern ein Greuel."',
    },
    47: {
        1: 'So kam Joseph, meldete es Pharao und sprach: "Mein Vater und meine Brüder mit ihren Schafen und Rindern und all ihrer Habe sind aus dem Lande Kanaan gekommen und sind jetzt im Lande Gosen."',
        2: 'Er hatte aber fünf der tüchtigsten seiner Brüder mitgenommen. Diese stellte er dem Pharao vor.',
        3: 'Da sprach Pharao zu seinen Brüdern: "Was ist euer Gewerbe?" Sie sprachen zu Pharao: "Schafhirten sind deine Sklaven, wir wie unsere Väter."',
        4: 'Dann sprachen sie zu Pharao: "Wir sind gekommen, im Land zu Gaste zu sein, weil es keine Weide mehr für deiner Sklaven Schafe gibt. Schwer ist ja der Hunger im Lande Kanaan. Nun möchten deine Sklaven in dem Lande Gosen weilen dürfen."',
        5: 'Da sprach Pharao zu Joseph: "Dein Vater und deine Brüder sind zu dir gekommen.',
        6: 'Offen steht dir das Ägypterland. Siedle deinen Vater und deine Brüder im besten Teil des Landes an! Sie mögen in dem Lande Gosen wohnen, und findest du, daß unter ihnen tüchtige Leute sind, dann kannst du sie zu Aufsehern über meine Herden machen."',
        7: 'Da führte Joseph seinen Vater Jakob hinein und stellte ihn Pharao vor. Jakob aber begrüßte Pharao mit einem Segenswunsch.',
        8: 'Da sprach Pharao zu Jakob: "Wie viele Lebensjahre zählst du?"',
        9: 'Da sprach Jakob zu Pharao: "Die Dauer meiner Wanderschaft beträgt 130 Jahre. Wenig und böse sind meine Lebensjahre gewesen. Sie reichen nicht an die Lebensjahre meiner Väter in den Tagen ihrer Pilgerschaft."',
        10: 'Dann segnete Jakob den Pharao. Und so verließ er den Pharao.',
        11: 'Und Joseph siedelte seinen Vater und seine Brüder an und gab ihnen im Lande Ägypten Besitz, im besten Teile des Landes, im Lande Ramses, wie Pharao befohlen hatte.',
        12: 'Und Joseph versorgte seinen Vater, seine Brüder und die ganze Familie seines Vaters mit Brot, vornehmlich die Kinder.',
        13: 'Nun gab es auf der ganzen Erde kein Brot mehr; denn der Hunger war sehr stark. Auch das Land Ägypten war ebenso vom Hunger erschöpft wie das Land Kanaan.',
        14: 'Joseph aber hatte alles Geld im Land Ägypten und im Lande Kanaan an sich gebracht für das Getreide, das sie kaufen mußten. Und Joseph hatte das Geld in Pharaos Haus gebracht.',
        15: 'So war das Geld im Lande Ägypten und im Lande Kanaan verschwunden. Da kam ganz Ägypten zu Joseph und sprach: "Gib uns Brot! Warum sollen wir vor deinen Augen sterben, nur weil das Geld zu Ende ging?"',
        16: 'Da sprach Joseph: "Gebt eure Herden her! Dann gebe ich euch um eure Herden etwas, wenn das Geld zu Ende ist."',
        17: 'So brachten sie ihre Herden zu Joseph, und Joseph gab ihnen Brot um die Rosse, die Schaf- und Rinderherden und die Esel. So versorgte er sie mit Brot um den Preis all ihrer Herden in jenem Jahre.',
        18: 'So verging jenes Jahr. Da kamen sie im zweiten Jahre wieder zu ihm und sprachen zu ihm: "Wir können es meinem Herrn nicht verhehlen: Wenn das Geld zu Ende ist und der Besitz an Vieh an meinen Herrn übergeht, dann ist nichts mehr vor meinem Herrn übrig als unser Leib und unser Ackerland.',
        19: 'Warum sollen wir vor deinen Augen hinsterben, wir und unser Ackerland? Kaufe uns und unser Ackerland um Brot! Wir wollen mit unserem Ackerland dem Pharao fronen. Aber gib Saatkorn her, daß wir leben und nicht sterben und daß das Ackerland nicht veröde!"',
        20: 'So kaufte Joseph den ganzen Ackerboden Ägyptens für Pharao; denn die Ägypter verkauften jeder sein Feld. So hatte sie der Hunger gedrückt. Und das Land kam in Pharaos Besitz.',
        21: 'Das Volk aber ließ er in Städte übersiedeln von einem Ende Ägyptens bis zum anderen.',
        22: 'Nur das Ackerland der Priester kaufte er nicht. Denn die Priester hatten vom Pharao ein festes Einkommen. So lebten sie von ihrem Einkommen, das ihnen Pharao gewährte. Deshalb verkauften sie ihr Ackerland nicht.',
        23: 'Da sprach Joseph zu den Leuten: "Nun habe ich euch samt eurem Ackerland für Pharao gekauft. Hier habt ihr Saatkorn. Dann könnt ihr das Ackerland besäen.',
        24: 'Aber bei der Ernte müßt ihr ein Fünftel dem Pharao abliefern. Die anderen vier Fünftel sollen euch gehören zur Aussaat fürs Feld und zu eurem Unterhalt und dem eurer Familien und zur Nahrung der Kinder!"',
        25: 'Sie sprachen: "Du rettest uns das Leben. Möchten wir Gnade finden in meines Herrn Augen! Dann wollen wir Pharaos Sklaven sein."',
        26: 'So machte es Joseph zum Gesetz bis auf diesen Tag für Ägyptens Ackerland, daß dem Pharao ein Fünftel gehöre. Nur das Ackerland der Priester allein war Pharao nicht zugefallen.',
        27: 'Israel aber blieb im Lande Ägypten, im Lande Gosen. Sie setzten sich darin fest, waren fruchtbar und mehrten sich stark.',
        28: 'Und Jakob lebte im Lande Ägypten 17 Jahre. Der Tage Jakobs, seiner Lebensjahre wurden 147 Jahre.',
        29: 'Als die Tage Israels dem Tod zugingen, rief er seinen Sohn Joseph und sprach zu ihm: "Gelte ich dir etwas, dann lege deine Hand unter meine Lende! Dann erweist du mir treue Liebe. Begrabe mich nicht in Ägypten!',
        30: 'Bei meinen Vätern möchte ich liegen! Möchtest du mich fort aus Ägypten bringen und mich in ihrem Grabe bestattend Er sprach: "Ich tue, wie du sagst."',
        31: 'Er sprach: "Schwöre mir!" Da schwur er ihm. Israel aber neigte sich zu Häupten des Bettes.',
    },
    48: {
        1: 'Nach diesen Begebnissen ward Joseph gemeldet: "Dein Vater ist erkrankt." Da nahm er seine beiden Söhne mit, Manasse und Ephraim.',
        2: 'Man meldete es Jakob und sprach. "Da kommt dein Sohn Joseph zu dir." Da nahm Israel seine Kräfte zusammen und setzte sich aufrecht im Bett.',
        3: 'Und Jakob sprach zu Joseph: "Gott, der Allmächtige, ist mir zu Luz im Lande Kanaan erschienen, hat mich gesegnet und zu mir gesprochen:',
        4: "'Ich lasse fruchtbar dich und zahlreich werden und mache dich zu einer Völkermenge und gebe dieses Land deinem Stamme nach dir zum ewigen Besitz.'",
        5: 'Nun sollen mir deine beiden Söhne gehören, die dir im Ägypterland geboren worden, bevor ich zu dir nach Ägypten kam! Ephraim und Manasse seien mein wie Ruben und Simeon!',
        6: 'Aber die Kinder, die du nach ihnen gezeugt, seien dein! Auf ihrer Brüder Namen seien sie zu ihrem Erbteil berufen!',
        7: 'Als ich aus Paddan kam, starb mir deine Mutter Rachel im Lande Kanaan unterwegs, nur noch eine Strecke Wegs bis Ephrat. Dort begrub ich sie am Wege nach Ephrat, das ist Bethlehem."',
        8: 'Als Israel die Söhne Josephs sah, sprach er: "Wer sind die?"',
        9: 'Da sprach Joseph zu seinem Vater: "Dies sind meine Söhne, die Gott mir hier geschenkt hat." Er sprach: "Bring sie zu mir her, daß ich sie segne!"',
        10: 'Israels Augen nämlich waren stumpf geworden vor Alter, daß er nicht mehr sehen konnte. Da führte er sie zu ihm, und er küßte sie und herzte sie.',
        11: 'Und Israel sprach zu Joseph: "Ich hätte nimmermehr geglaubt, dich wiederzusehen. Nun hat mich Gott selbst deinen Stamm noch sehen lassen."',
        12: 'Da nahm sie Joseph von seinen Knien und verneigte sich bis auf den Boden vor ihm.',
        13: 'Dann nahm Joseph die beiden, Ephraim an seine Rechte, links von Israel, und Manasse an seine Linke, rechts von Israel, und führte sie zu ihm.',
        14: 'Da streckte Israel seine Rechte aus und legte sie auf Ephraims Haupt, obschon er der Jüngere war, und seine Linke auf das Haupt Manasses, seine Hände kreuzend, obschon Manasse der Erstgeborene war.',
        15: 'Dann segnete er Joseph und sprach: "Der Gott, vor dem einst meine Väter Abraham und Isaak sind gewandelt, der Gott, der ist mein Hirte, seit ich bin gewesen, bis auf diesen Tag,',
        16: 'der Engel, der von jedem Übel mich erlöst, er segne diese Knaben! In ihnen lebe fort mein Name und meiner Väter Abraham und Isaak Name fort und fort! Sie sollen sich auf Erden mehren und wachsen!"',
        17: 'Als aber Joseph sah, daß sein Vater seine Rechte auf Ephraims Haupt legte, mißfiel ihm dies, und er griff nach seines Vaters Hand, um sie von Ephraims Haupt auf das Haupt Manasses zu legen.',
        18: 'Und Joseph sprach zu seinem Vater: "Nicht so! Mein Vater! Ist dieser doch der Erstgeborene. Lege deine Hand auf sein Haupt!"',
        19: 'Sein Vater aber weigerte sich und sprach: "Ich weiß, mein Sohn; ich weiß. Auch er wird ein Volk; auch er wird mächtig. Jedoch sein jüngerer Bruder wird mächtiger als er. Sein Stamm wird zur Völkerfülle werden."',
        20: 'So segnete er sie an jenem Tage und sprach: "Mit dir soll Israel segnen, also sprechend: \'Gott mache dich wie Ephraim und wie Manasse!\'" So setzte er Ephraim vor Manasse.',
        21: 'Dann sprach Israel zu Joseph: "Siehe! Ich sterbe. Doch Gott ist mit euch, und so führt er euch heim in eurer Väter Land.',
        22: 'Ich aber gebe dir vor deinen Brüdern Sichem, jenes einzige Stück, das ich den Amoritern einst mit meinem Schwert und Bogen abgenommen habe."',
    },
    49: {
        1: 'Jakob berief nun seine Söhne und sprach: "Versammelt euch, damit ich euch verkünde, was euch begegnet in der Folgezeit.',
        2: 'Schart euch zusammen! Ihr Jakobssöhne, hört! Auf euren Vater Israel hört jetzt!"',
        3: '"Ruben! Mein Erstling du, du meine Kraft, du Erstling meiner Stärke! Aufrechter Pflock! Du starker Pflock!',
        4: 'Des Wassers Überschwang sei nimmer dir zu eigen! Denn du erstiegest deines Vaters Bett, entweihtest mit Gewalt mein Lager."',
        5: '"Simeon und Levi! Das Brüderpaar. Des Unrechts Waffen waren ihre Schwerter.',
        6: 'Nicht möchte meine Seele ihrem Plane beitreten! Nicht möchte mein Gemüt mit ihrem Anschlag sich befreunden! In ihrem Zorne mordeten sie Männer, verstümmelten in ihrer Laune Stiere.',
        7: 'Verflucht ihr Zorn, der stark, ihr Grimm, so hart! Und so verteile ich in Jakob sie, zerstreue sie in Israel."',
        8: '"Dich, Juda, sollen deine Brüder preisen! Am Nacken deiner Feinde deine Hand! Die Söhne deines Vaters neigen sich vor dir.',
        9: 'Ein junger Leu ist Juda. Mein Sohn, vom Raube stiegest du empor. Er kauert, lagert wie der Leu, wie eine Löwin. Wer mag ihn reizen?',
        10: 'Nicht weicht das Zepter je von Juda und nie der Herrscherstab von ihm, bis sein Ersehnter kommt, auf den die Völker hören.',
        11: 'Sein Eselsfüllen bindet er an einen Weinstock und an die Edelrebe seiner Eselin Junges. Er wäscht in Wein sein Kleid, im Traubenblute sein Gewand.',
        12: 'Von Wein die Augen fröhlich, die Zähne weiß von Milch."',
        13: '"Und Zabulon wohnt an dem Meeresstrand und fährt auf Schiffen, und seine Flanke reicht an Sidon."',
        14: '"Issakar ist ein starker Esel, der zwischen Höhen lagert.',
        15: 'Er fand, daß Ruhe etwas Schönes und daß das Land gar prächtig. So beugte er zum Tragen seinen Nacken und ward ein Fronknecht."',
        16: '"Und Dan schafft seinem Volke Recht, wie einer nur von Israels Stämmen.',
        17: 'Am Weg ist eine Schlange Dan und eine Hornviper am Pfad; sie beißt das Roß in seine Hinterfüße, und rückwärts stürzt sein Reiter.',
        18: 'Auf Deine Hilfe hoff ich, Herr."',
        19: '"Den Gad umdrängt die Raubschar; doch schon drängt er dem Nachtrab nach."',
        20: '"Von Asser stammt gar fette Speise; er liefert königliche Leckerbissen."',
        21: '"Und Naphtali ist eine heilige Hirschkuh, die schöne Lämmer wirft."',
        22: '"Ein Stier ist Joseph, ein Stier an einer Quelle. Jungmänner ziehen gegen diesen Stier.',
        23: 'Und ihn bedrängen Pfeilschützen, die ihn beschießen und ihm zusetzen.',
        24: 'Doch wird ihr Bogen unbiegsam, und ihrer Hände Arme zittern vor dem Jakobsfürsten und vor des Israelsohnes Hirten.',
        25: 'Dir helfe deines Vaters Gott, und der Allmächtige segne dich mit Himmelssegen oben, mit Segnungen der Tiefe drunten, mit Segnungen an Brust und Schoß!',
        26: 'Die Segenswünsche deines Vaters, sie übertreffen jene meiner Eltern, den Wunsch der alten Hirten. Gelangen mögen sie auf Josephs Haupt, ja auf den Scheitel des Geweihten unter seinen Brüdern!"',
        27: '"Ein räuberischer Wolf ist Benjamin; am Morgen frißt er Raub und abends teilt er Beute."',
        28: 'All diese sind die zwölf Stämme Israels, und dies war es, was ihr Vater zu ihnen gesprochen hat. Er segnete sie; jeden segnete er mit seinem besonderen Segen.',
        29: 'Und er beschied sie und sprach zu ihnen: "Ich gehe nun zu meinem Volke ein. Begrabet mich bei meinen Vätern in der Höhle auf dem Feld des Chittiters Ephron,',
        30: 'in jener Höhle auf dem Feld der Makpela, Mamre gegenüber im Lande Kanaan, auf jenem Feld, das Abraham von dem Chittiter Ephron zum Erbbegräbnis gekauft!',
        31: 'Dort hat man Abraham begraben und sein Weib Sara. Dort hat man Isaak begraben und sein Weib Rebekka; dort habe auch ich Lea begraben,',
        32: 'auf jenem Felde und in der Höhle, die von den Söhnen Chets stammt."',
        33: 'Als Jakob die Aufträge an seine Söhne beendet hatte, zog er seine Füße auf dem Bett ein, verschied und ward zu seinen Vätern versammelt.',
    },
    50: {
        1: 'Da warf sich Joseph auf seinen Vater, weinte über ihm und küßt ihn.',
        2: 'Dann befahl Joseph seinen Dienern, den Ärzten, seinen Vater einzubalsamieren. Da balsamierten die Ärzte Israel ein.',
        3: 'Darüber vergingen vierzig Tage; denn soviel Tage vergehen mit Einbalsamieren. Man beweinte ihn in Ägypten siebzig Tage lang.',
        4: 'Als aber die Tage seiner Beweinung vorüber waren, sprach Joseph zu Pharaos Haus also: "Habe ich in euren Augen Gnade gefunden, dann legt für mich ein Wort bei Pharao ein!',
        5: 'Mein Vater hat mich schwören lassen; er sprach: \'Siehe! Wenn ich tot bin, sollst du mich in meinem Grabe beisetzen, das ich mir im Lande Kanaan gegraben, dort sollst du mich begraben.\' Nun möchte ich hinaufziehen und meinen Vater dort bestatten und wiederkehren."',
        6: 'Da sprach Pharao: "So zieh hinauf! Bestatte deinen Vater, wie er dich hat schwören lassen!"',
        7: 'So zog Joseph zur Bestattung seines Vaters hinauf; mit ihm zogen alle Diener Pharaos, die Ältesten seines Hauses und die Ältesten des Landes Ägypten,',
        8: 'sowie das ganze Haus Josephs, seine Brüder und das Haus seines Vaters. Nur ihre Kinder, ihre Schafe und Rinder hatten sie im Lande Gosen gelassen.',
        9: 'Mit ihm zogen Wagen und Reiter hinauf, ein ganz gewaltiger Zug.',
        10: 'So kamen sie nach Goren Haatad jenseits des Jordan und hielten dort sehr große und feierliche Totenklage Und er hielt für seinen Vater eine siebentägige Totenfeier ab.',
        11: 'Die Bewohner des Landes aber, die Kanaaniter, sahen die Totenfeier zu Goren Haatad und sprachen: "Da findet eine große Totenfeier der Ägypter statt." Deshalb nannte man seinen Namen Abel Misraim; es liegt jenseits des Jordan.',
        12: 'Und seine Söhne taten ihm, wie er ihnen geboten hatte.',
        13: 'Seine Söhne führten ihn in das Land Kanaan und bestatteten ihn in der Höhle des Feldes der Makpela, des Feldes, das Abraham zum Erbbegräbnis von dem Chittiter Ephron gegenüber Mamre erworben.',
        14: 'Dann kehrte Joseph nach Ägypten zurück, er und seine Brüder sowie alle, die mit ihm zur Bestattung seines Vaters hinaufgezogen waren, nachdem er seinen Vater bestattet hatte.',
        15: 'Als Josephs Brüder sahen, daß ihr Vater gestorben war sprachen sie: "Wenn Joseph uns befeindete und uns all das Böse, das wir ihm angetan, vergälte?"',
        16: 'Da sandten sie zu Joseph und ließen sagen: "Dein Vater hat vor seinem Tode folgendes verordnet:',
        17: '\'Sprecht so zu Joseph: Vergib doch die Missetat deiner Brüder und ihre Sünde, daß sie dir Böses getan!\' Und nun verzeihe doch die Sünde der Verehrer des Gottes deines Vaters!" Da weinte Joseph, als sie so zu ihm sprachen.',
        18: 'Nun gingen auch seine Brüder hin, fielen vor ihm nieder und sprachen: "Hier sind wir, deine Leibeigenen."',
        19: 'Da sprach Joseph zu ihnen: "Fürchtet euch nicht! Bin ich an Gottes Statt?',
        20: 'Ihr freilich habt Böses wider mich ersonnen; Gott aber hat es zum Guten gelenkt, um bis auf heute vorzusorgen, ein großes Volk am Leben zu erhalten.',
        21: 'Nun fürchtet euch nicht. Ich sorge für euch und eure Kinder." So tröstete er sie und sprach ihnen Mut zu.',
        22: 'Joseph blieb in Ägypten, er und seines Vaters Haus. Und Joseph lebte 110 Jahre.',
        23: 'Joseph sah von Ephraim Urenkel; auch die Söhne Makirs, des Manassesohnes, waren auf Josephs Knien geboren worden.',
        24: 'Joseph sprach zu seinen Brüdern: "Ich sterbe; Gott aber sorgt für euch; dann führt er euch aus diesem Lande in das Land, das er Abraham, Isaak und Jakob zugeschworen hat."',
        25: 'Und Joseph ließ die Söhne Israels schwören und sprach: "Gott nimmt sich eurer an. Dann müßt ihr mein Gebein von hier hinaufbringen."',
        26: 'So starb Joseph, 110 Jahre alt. Man balsamierte ihn ein und legte ihn in Ägypten in den Schrein.',
    },
}
